(window.FREALLY_I18N = window.FREALLY_I18N || {})["ar"] = {"hero.headline":"<span class=\"hl-muted\">بحث واحد.</span> <span class=\"hl-bright\">كل المصادر. كل أنظمة التشغيل.</span>","hero.sub":"اعثر على أي ملف أثناء الكتابة: باسمه، أو بالكلمات التي بداخله، أو بحسب صوته، أو بما تقوله ترويسته، أو باسم قريب فقط من الاسم الذي تتذكّره.","hero.chipApp":"تطبيق لسطح المكتب","hero.chipCli":"سطر الأوامر","hero.chipLanguages":"18 لغة","what.title":"ما هو","what.p1":"لكل نظام تشغيل مربع بحث، ولكلٍّ منها قصوره الخاص. جعل Everything من voidtools البحث في أسماء الملفات فوريًا على Windows منذ سنوات، وبقي على Windows.","what.p2":"Freally Sourcerer هو هذا النوع من البحث لـ Windows وmacOS وLinux. يحتفظ بفهرس واحد لأقراصك، يبقى محدّثًا بفضل سجل تغييرات الملفات الخاص بكل نظام — سجل تغييرات NTFS على Windows، وFSEvents على macOS، وinotify وfanotify على Linux — فيُعثر على الملفات الجديدة والمعاد تسميتها دون إعادة فحص.","what.p3":"ثم يقرأ أبعد من الاسم. يمكن لاستعلام واحد أن يسأل عن الاسم، والنص داخل المستند، وشدة الصوت المقيسة لملف صوتي، وما تقوله صورة أو برنامج عن نفسه في ترويسته، والأسماء القريبة فقط مما كتبته.","features.title":"ما الذي يحتويه","features.filename.title":"أسماء الملفات، فورًا","features.filename.body":"السلاسل الفرعية، وأحرف البدل، والتعابير النمطية، وAND وOR وNOT، ومُعدِّلات Everything نفسها للحجم والتاريخ والامتداد والمسار، تُجاب من الفهرس أثناء الكتابة.","features.content.title":"النص داخل الملفات","features.content.body":"بحث في النص الكامل لملفات PDF وWord وExcel وPowerPoint، وMarkdown، والشيفرة المصدرية بـ 32 لغة، وJSON وCSV وYAML، والبريد، وداخل الأرشيفات دون فكّها.","features.audio.title":"الملفات الصوتية بحسب صوتها","features.audio.body":"اعثر على الملفات الصوتية بحسب شدة صوتها المقيسة بـ LUFS، والذروة الحقيقية، والصمت، والمدى الديناميكي، والمدة، والمرمّز، ومعدّل العيّنات — لا بوسوم كتبها شخص ما.","features.properties.title":"ما يقوله الملف عن نفسه","features.properties.body":"اثنتان وسبعون خاصية تُقرأ من ترويسات الملفات: حجم الصورة والكاميرا، ومرمّز الفيديو ومدته، ومؤلف المستند وصفحاته، ومعمارية البرنامج وتوقيعه، والمزيد.","features.similar.title":"أسماء قريبة فحسب","features.similar.body":"تعثر عدسة التشابه على الأسماء القريبة مما كتبته — خطأ إملائي، أو رقم إصدار، أو بادئة مختلفة — والبحث الذي لا يعثر على شيء يقترح أقرب اسم موجود فعلًا.","features.everything.title":"كأنك في بيتك إن كنت قادمًا من Everything","features.everything.body":"صيغة البحث في Everything تعمل هنا أيضًا، وقوائم ملفاته تُفتح وتُصدَّر، فينتقل كتالوج محرك الأقراص بين البرنامجين.","features.results.title":"تصرّف فيما تجده","features.results.body":"افتح، وأظهِر في المجلد، وانسخ، وأعد تسمية مجموعة كاملة من النتائج مع معاينة وإمكانية التراجع، واعثر على الملفات المكرّرة والمجلدات الفارغة، وشغّل أوامرك الخاصة.","features.platforms.title":"تطبيق واحد، ثلاثة أنظمة","features.platforms.body":"التطبيق نفسه ولغة الاستعلام نفسها والفهرس نفسه على Windows وmacOS وLinux، وسطر أوامر للسكربتات، وثماني عشرة لغة.","ladder.title":"الطريق إلى 1.0","ladder.intro":"سطر واحد لكل إصدار. الإصدارات بعد 0.23 هي الخطة، بالترتيب الذي ستُبنى به.","ladder.rung.v0.19.84":"أول بناء عام: بحث في أسماء الملفات يبقى محدّثًا بفضل سجل التغييرات الخاص بكل نظام، ولغة الاستعلام، والتطبيق وإعداداته، بثماني عشرة لغة على Windows وmacOS وLinux.","ladder.rung.v0.21.0":"الميزات الأساسية، الجزء 1 من 3: الملفات المكرّرة، والمجلدات الفارغة، وقوائم ملفات Everything، وكل إجراء على النتيجة من قائمة النقر بالزر الأيمن.","ladder.rung.v0.22.0":"الميزات الأساسية، الجزء 2 من 3: الفهرس يتابع القرص مباشرةً، و«حالة الفهرس»، وإعادة التسمية الجماعية مع التراجع، ومحركات الأقراص المفصولة التي تبقى قابلة للبحث، وسطر أوامر للسكربتات.","ladder.rung.v0.23.0":"الميزات الأساسية، الجزء 3 من 3، والإصدار المستقر: الوضع المحمول، والصوت والفيديو في المعاينة، و«نظرة سريعة»، ومنشئ التعابير النمطية، وتقرير بالمجلدات التي لا يستطيع البحث رؤيتها. وإصداره التصحيحي، 0.23.2، هو الإصدار الحالي.","ladder.rung.v0.24.0":"عدسة الخصائص للصور والفيديو: الأبعاد، وبيانات الكاميرا، والمرمّزات، والمدة، قابلة للبحث ومعروضة كأعمدة.","ladder.rung.v0.25.0":"عدسة الخصائص للمستندات والبرامج والحزم: المؤلفون وعدد الصفحات، والمعماريات والتوقيعات، والمثبّتات، والاختصارات، والأرشيفات، والخطوط، والبريد، وقواعد البيانات.","ladder.rung.v0.26.0":"وسوم الموسيقى، والمزيد لمن يعملون مع الصوت.","ladder.rung.v0.27.0":"الملفات المكرّرة وتنظيف القرص.","ladder.rung.v0.28.0":"وسوم وملاحظات ومجموعات لملفاتك.","ladder.rung.v0.29.0":"البحث المتقدّم: وحدات الماكرو، واللقطات، والمراقِبات، وتجزئات الملفات.","ladder.rung.v0.30.0":"طرق العرض والنوافذ.","ladder.rung.v0.31.0":"مُشغِّل تطبيقات، وارتباط أوثق بنظام تشغيلك.","ladder.rung.v0.32.0":"سطر الأوامر، وواجهة طرفية، والأتمتة.","ladder.rung.v0.33.0":"البحث عبر شبكتك المحلية، والكتالوجات، وأدوات الفهرس للمستخدمين المتقدّمين.","ladder.rung.v1.0.0":"عدستا الشيفرة والمعرفة، والإطلاق: الإصدار 1.0.","ladder.note":"الإصدار المكتمل مبنيّ ومُوسوم. إنه ليس تنزيلًا: لا يوجد أي منها، ولن يوجد حتى الإصدار 1.0.0.","honest.title":"الأشياء التي تضعها معظم المواقع في الأسفل","honest.firstIndex.title":"يستغرق الفهرس الأول وقتًا أطول على macOS وLinux","honest.firstIndex.body":"على Windows، يتيح سجل تغييرات NTFS فهرسة وحدة تخزين كاملة بسرعة. لا يملك macOS وLinux شيئًا مماثلًا، لذا يمرّ الفهرس الأول هناك على كل مجلد: دقائق لا ثوانٍ على قرص كبير. وبعد ذلك تُبقيه أحداث التغيير الخاصة بالنظام محدّثًا.","honest.network.title":"ما يتصل بالإنترنت، وما لا يتصل أبدًا","honest.network.body":"لا يوجد أي قياس عن بُعد (telemetry)، ولا يُرسَل أي شيء عن ملفاتك أو عمليات بحثك إلى أي مكان. ولا يتصل التطبيق من تلقاء نفسه بالإنترنت إلا لأمر واحد: السؤال عمّا إذا كان هناك إصدار أحدث، مرة في اليوم ما لم تغيّر ذلك، ويمكنك إيقاف ذلك. ولا يُرسَل تقرير الخلل إلا حين تختار إرساله، بعد أن ترى ما يحتويه.","honest.unreadable.title":"يخبرك بما لا يستطيع رؤيته","honest.unreadable.body":"المجلد الذي تعذّرت قراءته يبدو تمامًا كمجلد فارغ. يسرد Sourcerer المجلدات التي اضطر إلى تخطّيها، مع السبب والإصلاح المناسب لنظامك، بدلًا من إرجاع نتائج أقل بصمت.","honest.lenses.title":"عدستان من العدسات الخمس غير موصولتين بعد","honest.lenses.body":"عدسة المحتوى، التي تقرأ النص داخل الملفات، وعدسة التشابه، التي تعثر على الأسماء القريبة فحسب، مبنيّتان لكنهما لا تُجيبان عن عمليات البحث بعد. أما اليوم فتُجيب عنها عدسات أسماء الملفات والصوت والخصائص. وتوصيل العدستين الأخريين جزء من الطريق إلى 1.0.","honest.downloads.title":"لا توجد تنزيلات قبل 1.0.0","honest.downloads.body":"لا نسخة تجريبية (beta) على هذه الصفحة، ولا بناء معاينة، ولا وصول مبكر. الإصدار 1.0.0 هو أول ما سيقدّمه هذا الموقع.","site.tagline":"بحث واحد. كل المصادر. كل أنظمة التشغيل.","footer.licence":"ملكية خاصة — جميع الحقوق محفوظة. © Mike Weaver. الاستخدام مجاني اليوم؛ وقد تُباع الإصدارات المستقبلية. ليس مفتوح المصدر.","footer.everything":"Everything علامة تجارية لـ voidtools، ويُذكر اسمها هنا للمقارنة فقط. لا يرتبط Freally Sourcerer بـ voidtools.","featuresPage.lead":"شريط بحث واحد لكل ملف على Windows وmacOS وLinux: الأسماء، والنص داخل المستندات، والملفات الصوتية بحسب صوتها، وما تقوله ترويسة الملف نفسه، والأسماء القريبة فحسب — من فهرس واحد يُبقي نفسه محدّثًا.","featuresPage.version":"تصف هذه الصفحة الإصدار 1.0 من Freally Sourcerer: كل ما فيها موجود في 1.0، ولا شيء مما هو مخطط له بعد 1.0 موجود فيها.","featuresPage.numbers.intro":"كل رقم مأخوذ بالعدّ من شيفرة التطبيق نفسها ومن سجل تغييراته. لا شيء مُقرَّب إلى أعلى.","featuresPage.numbers.lenses":"طرق للبحث في فهرس واحد: اسم الملف، والمحتوى، والصوت، والخصائص، والأسماء المتشابهة","featuresPage.numbers.properties":"خاصية ملف تُقرأ من الترويسات","featuresPage.numbers.code":"لغة برمجة يقرؤها بحثه في المحتوى","featuresPage.numbers.audioTypes":"نوع ملف صوتي في عامل التصفية «صوت»","featuresPage.numbers.matchModes":"أوضاع مطابقة، من «مطابقة حالة الأحرف» إلى «تجاهل علامات الترقيم»","featuresPage.numbers.systems":"أنظمة تشغيل: Windows وmacOS وLinux","featuresPage.numbers.languages":"لغة","featuresPage.numbers.price":"السعر اليوم","featuresPage.free.title":"مجاني اليوم","featuresPage.free.body":"كل ما يفعله Sourcerer اليوم مجاني للجميع: لا فئة مدفوعة، ولا اشتراك، ولا فترة تجربة تنتهي.","featuresPage.cards.title":"ما يفعله الإصدار 1.0","featuresPage.cards.index.title":"فهرس حي لكل قرص","featuresPage.cards.index.body":"فهرس واحد عبر محركات أقراصك، يبقى محدّثًا بفضل تدفق التغييرات الخاص بكل نظام — سجل تغييرات NTFS على Windows، وFSEvents على macOS، وinotify وfanotify على Linux — فتظهر الملفات الجديدة والمعاد تسميتها والمحذوفة دون إعادة فحص. ومحرك الأقراص الذي تفصله يبقى قابلًا للبحث، وتذكر نتائجه على أي محرك توجد.","featuresPage.cards.names.title":"أسماء الملفات، كما يعثر عليها Everything","featuresPage.cards.names.body":"السلاسل الفرعية، وأحرف البدل، والتعابير النمطية، وAND وOR وNOT والتجميع، مع مُعدِّلات Everything وصيغ كتابتها للحجم والتاريخ والامتداد والسمات والمسار، وسبعة أوضاع مطابقة، من «مطابقة حالة الأحرف» إلى «تجاهل علامات الترقيم» ومطابقة الأسماء الصينية واليابانية والكورية بحسب نطقها.","featuresPage.cards.content.title":"النص داخل الملفات","featuresPage.cards.content.body":"بحث في النص الكامل لملفات PDF وWord وExcel وPowerPoint، والنص العادي وMarkdown، والشيفرة المصدرية بـ 32 لغة، وJSON وCSV وYAML، والبريد، وداخل أرشيفات zip و7z وtar دون فكّها. وعارض يتنقّل بين كل تطابق في سياقه.","featuresPage.cards.audio.title":"الملفات الصوتية بحسب صوتها","featuresPage.cards.audio.body":"مقيس لا موسوم: شدة الصوت بـ LUFS، والذروة الحقيقية، والصمت، والمدى الديناميكي، والمدة، والمرمّز، ومعدّل العيّنات، والقنوات. رتّب حسب شدة الصوت أو المدة، وشغّل الملف في المعاينة دون مغادرة القائمة.","featuresPage.cards.properties.title":"ما يقوله الملف عن نفسه","featuresPage.cards.properties.body":"اثنتان وسبعون خاصية تُقرأ من ترويسات الملفات ويُبحث فيها كأي مُعدِّل آخر: حجم الصورة وبيانات الكاميرا، ومرمّز الفيديو ومدته، ومؤلف المستند وعدد صفحاته، ومعمارية البرنامج وتوقيعه، وإصدارات المثبّتات، وأهداف الاختصارات، ومحتويات الأرشيفات، والخطوط، وترويسات البريد، وجداول قواعد البيانات. ويمكن لأيٍّ منها أن يكون عمودًا.","featuresPage.cards.similar.title":"أسماء قريبة فحسب","featuresPage.cards.similar.body":"تعثر عدسة التشابه على الأسماء القريبة مما كتبته — خطأ إملائي، أو رقم إصدار، أو بادئة مختلفة — والبحث الذي لا يعثر على شيء يقترح أقرب اسم موجود فعلًا كتصحيح بنقرة واحدة.","featuresPage.cards.results.title":"كل ما تفعله بالنتيجة","featuresPage.cards.results.body":"فتح، وإظهار، و«فتح باستخدام»، ونسخ المسار أو الاسم أو المحتوى أو الملف نفسه، وفتح طرفية هناك، وتشغيل أوامر تعرّفها بنفسك. تفتح المسافة «نظرة سريعة»، ويُشغَّل الصوت والفيديو في المعاينة، ويفتح عدد النتائج إحصاءات المجموعة كاملة.","featuresPage.cards.rename.title":"أعد التسمية، وتراجع، ونظّم","featuresPage.cards.rename.body":"أعد تسمية مجموعة كاملة من النتائج بالبحث والاستبدال، والتعابير النمطية، والعدّادات، وتغيير حالة الأحرف، مع معاينة أولًا ورفضٍ إذا كان اسمان سيتصادمان. ويعكس «تراجع» إعادة التسمية، حتى بعد إعادة التشغيل. واعثر على الملفات المكرّرة والمجلدات الفارغة مباشرةً من الفهرس.","featuresPage.cards.everything.title":"كأنك في بيتك إن كنت قادمًا من Everything","featuresPage.cards.everything.body":"صيغة البحث في Everything، وعوامل التصفية السريعة، وقوائم الملفات، استيرادًا وتصديرًا، إضافةً إلى CSV والنص العادي وقوائم التشغيل وNDJSON. ويتحقق وضع صارم من أن الاستعلام لا يستخدم إلا ما يفهمه Everything.","featuresPage.cards.cli.title":"سطر أوامر للسكربتات","featuresPage.cards.cli.body":"يتحدث الأمر freally لغة الاستعلام نفسها، ويطبع JSON أو NDJSON أو CSV أو مسارات مفصولة بـ NUL، ويُرجع رموز خروج ذات معنى، ويدعم الإكمال التلقائي في bash وzsh وfish وPowerShell.","featuresPage.cards.portable.title":"محمول، إن أردت","featuresPage.cards.portable.body":"شغّله من وحدة USB: يبقى الفهرس والإعدادات والإشارات المرجعية والسجلات في مجلد Data بجوار التطبيق، ولا يُسجَّل أي شيء لدى الحاسوب الموصول به.","featuresPage.cards.languages.title":"ثماني عشرة لغة، فاتح أو داكن","featuresPage.cards.languages.body":"تتبدّل لغة القوائم والإعدادات وكل نوافذ الحوار فورًا، وتُعرض العربية من اليمين إلى اليسار. ويتبع التطبيق السمة الفاتحة أو الداكنة لنظامك، أو يحتفظ بالسمة التي تختارها.","featuresPage.compare.title":"جنبًا إلى جنب مع الأدوات التجارية","featuresPage.compare.intro":"Freally Sourcerer 1.0 إلى جانب أدوات البحث التجارية لسطح المكتب التي يستخدمها الناس اليوم. كل خانة لمنتج آخر مأخوذة من صفحات الشركة المصنّعة نفسها، وقد تُحقّق منها في 2 أكتوبر 2026، والأسعار هي أسعار القوائم الأمريكية حتى أكتوبر 2026 — إلا حيث لا تعرض الشركة المصنّعة سعرًا أمريكيًا، وتذكر الخانة ذلك.","featuresPage.compare.feature":"الميزة","featuresPage.compare.note.beta":"إصدار تجريبي (beta)","featuresPage.compare.row.price":"السعر (USD، أكتوبر 2026)","featuresPage.compare.freeToday":"مجاني اليوم","featuresPage.compare.note.freeware":"برنامج مجاني","featuresPage.compare.note.oneTime":"دفعة واحدة","featuresPage.compare.note.perYear":"سنويًا، خطة Basic","featuresPage.compare.legend.unknown":"لم يُتحقَّق منه","featuresPage.compare.note.euros":"دفعة واحدة، باليورو فقط","featuresPage.compare.row.systems":"Windows وmacOS وLinux","featuresPage.compare.legend.yes":"متوفر","featuresPage.compare.legend.partly":"جزئيًا","featuresPage.compare.row.liveIndex":"يعثر على الملفات بالاسم من فهرس يبقى محدّثًا مع تغيّر الملفات","featuresPage.compare.note.scheduled":"فهرس يُحدَّث وفق جدول زمني","featuresPage.compare.note.spotlight":"فهرس Spotlight","featuresPage.compare.note.chosenFolders":"مجلدات تختارها","featuresPage.compare.row.content":"يبحث في النص داخل المستندات مثل ملفات PDF وOffice","featuresPage.compare.note.notIndexed":"دون فهرسة، بطيء","featuresPage.compare.row.audio":"يعثر على الملفات الصوتية بحسب شدة الصوت المقيسة أو المرمّز أو معدّل العيّنات أو المدة","featuresPage.compare.note.noLoudness":"دون شدة الصوت","featuresPage.compare.note.tagsBitRate":"الوسوم ومعدّل البت","featuresPage.compare.note.mp3Tags":"وسوم MP3 وFLAC","featuresPage.compare.row.properties":"يبحث فيما تقوله ترويسة الملف: حجم الصورة، والكاميرا، والمؤلف، وعدد الصفحات","featuresPage.compare.note.exifIptc":"EXIF وIPTC","featuresPage.compare.row.similar":"يعثر على ملف من اسم قريب فحسب","featuresPage.compare.note.similarWords":"كلمات متشابهة في المستندات","featuresPage.compare.row.cli":"سطر أوامر للبحث","featuresPage.compare.row.portable":"يعمل دون تثبيت، من وحدة USB","featuresPage.compare.row.duplicates":"يعثر على الملفات المكرّرة","featuresPage.compare.legend.no":"غير متوفر","featuresPage.compare.summaryTitle":"باختصار","featuresPage.compare.summary":"باختصار: Sourcerer وحده يملك كل ذلك — الأنظمة الثلاثة كلها، وفهرسًا حيًا، والنص داخل المستندات، والصوت بحسب شدته، وما تقوله ترويسة الملف، والأسماء القريبة فحسب.","featuresPage.compare.theyWinTitle":"أين يتفوّقون","featuresPage.compare.theyWin":"أين يتفوّقون: Everything لا يكلّف شيئًا، ونسخته التجريبية 1.5 تعثر على الملفات بتجزئاتها أيضًا؛ ويبحث FileLocator Pro في ملفات بريد Outlook؛ ويبحث Copernic أيضًا في Google Drive وDropbox وOneDrive؛ ويعثر DocFetcher Pro داخل المستندات على كلمات مشابهة لتلك التي كتبتها.","featuresPage.compare.asOf":"عمود Sourcerer يخص الإصدار 1.0، الذي لم يصدر بعد، وسعره هو سعر اليوم: Sourcerer مجاني اليوم، وقد تُباع الإصدارات المستقبلية. والمنتجات الأخرى تتغيّر أيضًا؛ وهذا الجدول صحيح حتى 2 أكتوبر 2026.","featuresPage.why.title":"لماذا بُني بهذه الطريقة","featuresPage.why.journal.title":"يستمع بدلًا من إعادة الفحص","featuresPage.why.journal.body":"كل نظام يسجّل أصلًا التغييرات على ملفاته. يقرأ Sourcerer ذلك السجل بدلًا من المرور على مجلداتك وفق مؤقّت، فيبقى الفهرس محدّثًا دون قراءة القرص مجددًا.","featuresPage.why.lazy.title":"لا يقرأ إلا ما يحتاجه السؤال","featuresPage.why.lazy.body":"تُقرأ خصائص الملف أول مرة يسأل عنه فيها بحثٌ، من ترويسته وحدها، وتُحفظ حتى يتغيّر الملف. لا شيء يفكّ ترميز صورة أو يفتح صفوف قاعدة بيانات ليجيب عن عرض صورة ما.","featuresPage.why.honest.title":"يقول ما لا يستطيع رؤيته","featuresPage.why.honest.body":"المجلد الذي تعذّرت قراءته يبدو تمامًا كمجلد فارغ، لذا يسمّي Sourcerer المجلدات التي تخطّاها وسبب ذلك. والعدد الذي بلغ حدّه يُعرض كحدّ أدنى، لا كرقم دقيق أبدًا.","featuresPage.why.careful.title":"يتعامل مع ملفاتك بحذر","featuresPage.why.careful.body":"تُعايَن إعادة التسمية مسبقًا وتحدث كلها دفعة واحدة أو لا تحدث إطلاقًا، ويذهب المحذوف إلى سلة المهملات أو سلة المحذوفات، ويعمل أمرك الخاص كبرنامج مع وسائط، لا كسطر صدفة أبدًا، بعد أن يسألك مرة واحدة.","featuresPage.why.local.title":"يبقى على جهازك","featuresPage.why.local.body":"لا قياس عن بُعد. يوجد الفهرس على قرصك أنت، ولا يُرسَل أي شيء عن ملفاتك أو عمليات بحثك إلى أي مكان. ولا يسأل التحقق من التحديثات إلا عمّا إذا كان هناك إصدار أحدث، ويمكنك إيقافه.","featuresPage.why.everything.title":"يحترم ما تعرفه مسبقًا","featuresPage.why.everything.body":"صيغة Everything وعوامل تصفيته وقوائم ملفاته تتصرّف هنا كما تتصرّف هناك، وتتحقق من ذلك الاختبارات، فتنتقل عادات سنوات معك — إلى نظامي تشغيل إضافيين.","featuresPage.coming.title":"ما الذي لم يأتِ بعد","featuresPage.coming.intro":"نقولها بوضوح، لأن قائمة ميزات تخفي ثغراتها لا تستحق القراءة. هذه الصفحة تصف الإصدار 1.0، وSourcerer يُبنى إصدارًا تلو الآخر: الإصدارات بعد 0.23 لم تأتِ بعد. وكلٌّ منها على الطريق إلى 1.0 موسوم بحالته. عدستان من العدسات الخمس — النص داخل الملفات والأسماء القريبة فحسب — مبنيّتان لكنهما غير موصولتين بالبحث بعد. وهما على هذه الصفحة لأنهما في الإصدار 1.0.","featuresPage.limits.title":"ما لا يفعله الإصدار 1.0","featuresPage.limits.headers":"يقرأ الخصائص من ترويسات الملفات فقط: لا يفكّ ترميز الصور ولا يشغّل الفيديو ولا يعرض المستندات للعثور عليها، لذا لا يمكن البحث في خاصية لا تحملها الترويسة.","featuresPage.limits.firstIndex":"على macOS وLinux يمرّ الفهرس الأول على كل مجلد، لذا يستغرق على قرص كبير دقائق لا ثوانيَ.","featuresPage.limits.portable":"النسخة المحمولة لا تحدّث نفسها: استبدل مجلدها بإصدار أحدث.","featuresPage.coming.downloads":"لا توجد تنزيلات قبل الإصدار 1.0، ولا شيء منها على هذه الصفحة.","docs.intro":"كيف تستخدم Freally Sourcerer كما هو مبنيّ اليوم، على الطريق إلى 1.0؛ ويكبر الدليل مع كل إصدار. على macOS، اقرأ Ctrl على أنه Cmd: فالقوائم تعرض مفاتيح نظامك.","docs.start.title":"البدء","docs.search.title":"البحث","docs.lenses.title":"العدسات الخمس","docs.syntax.title":"صيغة الاستعلام","docs.filters.title":"عوامل التصفية السريعة","docs.bookmarks.title":"الإشارات المرجعية والشريط الجانبي","docs.results.title":"العمل مع النتائج","docs.rename.title":"إعادة التسمية الجماعية","docs.preview.title":"المعاينة و«نظرة سريعة»","docs.drives.title":"محركات الأقراص المفصولة وقوائم الملفات","docs.health.title":"حالة الفهرس والمجلدات المتخطّاة","docs.portable.title":"الوضع المحمول","docs.settings.title":"الإعدادات ومفتاح الاختصار","docs.language.title":"اللغات","docs.cli.title":"سطر الأوامر","docs.privacy.title":"الخصوصية والشبكة","docs.faq.title":"أسئلة","docs.start.p1":"يعمل Sourcerer كجزأين: مُفهرِس في الخلفية، <code>freally-indexd</code>، يُبقي الفهرس محدّثًا، والتطبيق الذي تبحث منه. يثبّت المثبّت الجزأين كليهما، ويبدأ المُفهرِس عند تسجيل دخولك.","docs.start.id":"معرّف التطبيق هو <code>com.freallyproducts.sourcerer</code>، وتُحفظ إعداداتك وإشاراتك المرجعية وفهرسك في مجلد بيانات التطبيقات في نظامك تحت هذا الاسم. استخدمت الإصدارات حتى 0.23.2 المعرّف <code>io.mikeweaver.freally</code>؛ وينقل الإصدار الأحدث ذلك المجلد إلى الاسم الجديد عند أول تشغيل له، فلا تُعاد فهرسة أي شيء.","docs.start.p2":"عند فتح التطبيق أول مرة، يسألك إعداد قصير عن المجلدات التي تريد فهرستها، ومفتاح الاختصار الذي يُحضر التطبيق إلى المقدّمة، ولغتك وسمتك. ويمكنك تغييرها كلها لاحقًا في الإعدادات.","docs.start.p3":"ثم يبني الفهرس. على Windows يقرأ سجل تغييرات NTFS، وهذا سريع؛ وعلى macOS وLinux يمرّ على مجلداتك، وهذا يستغرق دقائق على قرص كبير. ويمكنك البحث أثناء عمله: تمتلئ النتائج تدريجيًا.","docs.start.p4":"لا توجد تنزيلات قبل الإصدار 1.0.0، والشيفرة المصدرية خاصة.","docs.search.type":"اكتب في شريط البحث. تظهر النتائج أثناء الكتابة، مجمّعة حسب العدسة، ومع كل مجموعة المدة التي استغرقتها. كل حرف يضيّقها؛ ولا يوجد ما يُرسَل.","docs.search.move":"تنقّل بين النتائج بمفاتيح الأسهم، واضغط Enter أو انقر نقرًا مزدوجًا على صف لفتح الملف بتطبيقه المعتاد.","docs.search.within":"يبحث <kbd>Ctrl+Shift+F</kbd> داخل النتائج التي لديك أصلًا. يصبح كل مصطلح شريحة يمكنك إزالتها وحدها، فتستطيع التراجع خطوة دون إعادة الكتابة.","docs.search.bold":"ما تكتبه يظهر <strong>بخط عريض</strong> في الأسماء والمسارات. والمُعدِّل مثل <code>ext:json</code> يضيّق القائمة ولا يمثّل شيئًا تبحث عنه، لذا لا يُميَّز.","docs.search.clear":"يمسح <kbd>Esc</kbd> شريط البحث.","docs.lenses.intro":"لدى Sourcerer خمس عدسات، تقرأ كلها الفهرس نفسه. اليوم تُجيب عدسات أسماء الملفات والصوت والخصائص عن عمليات بحثك؛ أما عدستا المحتوى والتشابه فمبنيّتان لكنهما غير موصولتين بشريط البحث بعد — وهذا يأتي على الطريق إلى 1.0.","docs.lenses.filename":"اسم الملف: الأسماء والمسارات، مع أحرف البدل والتعابير النمطية ومُعدِّلات Everything. الأسرع بين الخمس.","docs.lenses.content":"المحتوى: النص داخل ملفات PDF وWord وExcel وPowerPoint، والنص العادي وMarkdown، والشيفرة المصدرية بـ 32 لغة، وJSON وCSV وYAML، والبريد، وأرشيفات zip و7z وtar، دون فكّها. غير موصولة بشريط البحث بعد.","docs.lenses.audio":"الصوت: قياسات الملف الصوتي — شدة الصوت بـ LUFS، والصمت، والمدى الديناميكي، والمدة، والمرمّز، ومعدّل العيّنات — تُحسب أول مرة يسأل فيها بحث، وتُحفظ حتى يتغيّر الملف.","docs.lenses.properties":"الخصائص: ما تقوله ترويسة الملف نفسه — اثنتان وسبعون خاصية تشمل الصور، وبيانات الكاميرا، والفيديو، والمستندات، والبرامج، والمثبّتات، والاختصارات، والأرشيفات، والخطوط، والبريد، وقواعد بيانات SQLite.","docs.lenses.similar":"التشابه: الأسماء القريبة مما كتبته، لحين لا تتذكّر الملف إلا تقريبًا. غير موصولة بشريط البحث بعد؛ وإلى أن تُوصل، يقترح البحث الذي لا يعثر على شيء أقرب اسم موجود فعلًا بدلًا من ذلك.","docs.lenses.prefix":"يمكن تشغيل العدسات وإيقافها من <strong>عرض ← العدسات</strong>.","docs.syntax.intro":"يفهم Sourcerer صيغة Everything من voidtools، ويضيف مُعدِّلات لعدساته الأخرى.","docs.syntax.basics":"الأساسيات","docs.syntax.terms":"تطابق الكلمات العادية أي موضع في الاسم، ويجب أن تطابق كل الكلمات: <code>report 2024</code>.","docs.syntax.wildcards":"يطابق <code>*</code> أي سلسلة من الأحرف، و<code>?</code> حرفًا واحدًا، مقابل الاسم كاملًا: <code>invoice_202?.pdf</code>.","docs.syntax.boolean":"المسافة أو <code>AND</code> تعني كليهما، و<code>|</code> أو <code>OR</code> أحدهما، و<code>!</code> أو <code>NOT</code> الاستبعاد، والأقواس للتجميع: <code>(budget | forecast) !draft</code>.","docs.syntax.regex":"يبدأ <code>regex:</code> تعبيرًا نمطيًا: <code>regex:^report-\\d+</code>. الصياغة صياغة Rust، فلا مراجع خلفية ولا نظر أمامي أو خلفي.","docs.syntax.modifiers":"المُعدِّلات","docs.syntax.modifiersIntro":"تضيّق المُعدِّلات النتائج بحسب ما هو معروف عن الملف. اجمع منها ما شئت.","docs.syntax.col.modifier":"المُعدِّل","docs.syntax.col.matches":"ما يطابقه","docs.syntax.col.example":"مثال","docs.syntax.mod.size":"الحجم، مع kb وmb وgb، والمقارنات والنطاقات","docs.syntax.mod.date":"تاريخ التعديل؛ و<code>dc:</code> للإنشاء، و<code>da:</code> للوصول","docs.syntax.mod.ext":"الامتداد، واحد أو عدة امتدادات مفصولة بفواصل منقوطة","docs.syntax.mod.attrib":"سمات الملف، مثل «مخفي»","docs.syntax.mod.path":"المسار الكامل يحتوي على النص","docs.syntax.mod.parent":"الملف موجود مباشرةً داخل ذلك المجلد","docs.syntax.mod.anchors":"الاسم يبدأ بالنص أو ينتهي به","docs.syntax.mod.loudness":"شدة الصوت المقيسة بـ LUFS، والمدى الديناميكي بـ dB","docs.syntax.mod.length":"مدة الملف الصوتي","docs.syntax.mod.codec":"مرمّز الصوت، ومعدّل العيّنات بـ Hz","docs.syntax.mod.silence":"نسبة الصمت في الملف الصوتي، من 0 إلى 1","docs.syntax.mod.property":"أي خاصية من الخصائص الاثنتين والسبعين؛ و<code>property:</code> هو الصيغة الطويلة","docs.syntax.mod.dupe":"الملفات التي تتشارك الاسم والحجم؛ ويطابق <code>name-dupe:</code> و<code>size-dupe:</code> على أحدهما فقط","docs.syntax.mod.empty":"الملفات والمجلدات الفارغة؛ ويعثر <code>empty:roots</code> على قمة كل سلسلة مجلدات لا تحتوي على أي ملفات","docs.syntax.mod.children":"المجلدات بحسب عدد العناصر التي تحتويها مباشرةً؛ و<code>descendant-count:</code> على أي عمق","docs.syntax.mod.volume":"الملفات على محرك أقراص واحد، باسمه، حتى وهو مفصول","docs.syntax.modes":"أوضاع المطابقة","docs.syntax.modesMenu":"تبدّل قائمة <strong>بحث</strong> «مطابقة حالة الأحرف» (<kbd>Ctrl+I</kbd>)، و«مطابقة الكلمة بالكامل» (<kbd>Ctrl+B</kbd>)، و«مطابقة المسار» (<kbd>Ctrl+U</kbd>)، و«مطابقة التشكيل» (<kbd>Ctrl+M</kbd>).","docs.syntax.ignore":"يتيح <strong>تجاهل علامات الترقيم</strong> لـ <code>foobar</code> العثور على <code>foo-bar</code>، ويتيح <strong>تجاهل المسافات</strong> لـ <code>myreport</code> العثور على <code>my report</code>. وكلاهما معطّل افتراضيًا.","docs.syntax.cjk":"تعثر <strong>مطابقة صوتيات CJK</strong> على الأسماء الصينية واليابانية والكورية بحسب نطقها: <code>wenjian</code> يعثر على 文件.","docs.syntax.regexBuilder":"يعامل <strong>تفعيل التعبير النمطي</strong> (<kbd>Ctrl+R</kbd>) الاستعلام كله كتعبير نمطي. ويختبر منشئ التعابير النمطية بجوار شريط البحث النمطَ على الأسماء الظاهرة على الشاشة أثناء كتابته، مع خطأ المحرّك نفسه إن كان غير صالح.","docs.filters.p1":"تقصر عوامل التصفية السريعة النتائج على نوع من الملفات بنقرة واحدة: صوت، ومضغوط، ومستند، وملف تنفيذي، ومجلد، وصورة، وفيديو. يحمل كلٌّ منها كل امتداد يحمله عامل التصفية المقابل في Everything، وأكثر — 65 نوعًا صوتيًا، و79 للفيديو، و77 للصور، و86 للمستندات، و70 للأرشيفات.","docs.filters.p2":"يمكنك أيضًا كتابتها، بالأسماء البديلة التي تتوقعها: <code>audio:</code> و<code>video:</code> و<code>image:</code> و<code>document:</code> و<code>executable:</code> و<code>archive:</code>، أو <code>music:</code> و<code>photos:</code> و<code>docs:</code> و<code>zip:</code>.","docs.filters.p3":"لا تُصنَّف الشيفرة المصدرية تحت «مستند»، خلافًا لـ Everything؛ ويعيد <code>ext:c;cpp;h</code> تلك المجموعة. ولحفظ بحث خاص بك كعامل تصفية، اختر <strong>بحث ← إضافة إلى عوامل التصفية…</strong>، وعدّلها عبر <strong>تنظيم عوامل التصفية…</strong> (<kbd>Ctrl+Shift+O</kbd>).","docs.bookmarks.add":"يحفظ <kbd>Ctrl+D</kbd> البحث الحالي كإشارة مرجعية، وينظّمها <kbd>Ctrl+Shift+B</kbd>.","docs.bookmarks.recall":"اكتب <code>:</code> متبوعًا باسم الإشارة المرجعية لتشغيلها.","docs.bookmarks.sidebar":"يُظهر <strong>عرض ← الشريط الجانبي</strong> عمودًا يضم إشاراتك المرجعية، وعوامل التصفية السريعة، ومحركات أقراصك، وعمليات بحثك الأخيرة. اسحب الإشارات المرجعية لإعادة ترتيبها؛ وانقر على محرك أقراص للبحث فيه وحده.","docs.bookmarks.history":"لا تُسجَّل عمليات البحث الأخيرة ما دام وضع الخصوصية مفعّلًا أو سجل البحث معطّلًا.","docs.results.intro":"كل صف ملف حقيقي على قرصك. انقر بالزر الأيمن على صف لترى ما يمكنك فعله به:","docs.results.open":"«فتح»، و«إظهار في مدير الملفات»، و«فتح باستخدام» الذي يسرد التطبيقات التي سجّلها نظامك لذلك النوع من الملفات.","docs.results.copy":"«نسخ المحتوى» لنسخ متن ملف نصي، و«نسخ كملف» للصق الملف نفسه في مجلد، و«نسخ قائمة المسارات» — واحد في كل سطر، أو بين علامتي اقتباس، أو مفصولة بمسافات، أو مهيّأة للصدفة.","docs.results.hits":"يعرض «عرض التطابقات في سياقها» كل تطابق في المستند؛ ويتنقّل <kbd>F3</kbd> و<kbd>Shift+F3</kbd> بينها.","docs.results.terminal":"يفتح «فتح طرفية هنا» طرفية في مجلد الملف.","docs.results.commands":"أوامرك الخاصة، من <strong>الإعدادات ← عام ← أوامر مخصّصة</strong>، مع <code>{path}</code> و<code>{dir}</code> و<code>{name}</code> و<code>{stem}</code> و<code>{ext}</code> في وسائطها. يعمل كلٌّ منها كبرنامج مع وسائط، لا كسطر صدفة أبدًا، ويسأل التطبيق مرة واحدة قبل تشغيل أي برنامج لأول مرة.","docs.results.delete":"يرسل «حذف» الملف إلى سلة المهملات أو سلة المحذوفات.","docs.results.view":"اسحب صفًا إلى تطبيق آخر كما لو كان من مدير ملفاتك. انقر على رأس عمود للترتيب، أو استخدم <kbd>Ctrl+1</kbd> إلى <kbd>Ctrl+9</kbd>؛ ويضيف <strong>+</strong> في نهاية صف العناوين خاصيةً كعمود. وتبدّل قائمة <strong>عرض</strong> بين التفاصيل والصور المصغّرة. وانقر على عدد النتائج في شريط الحالة للحصول على إحصاءات مجموعة النتائج كاملة: الأحجام والأعداد حسب النوع، والملفات الأكبر والأقدم والأحدث.","docs.rename.intro":"حدّد النتائج المراد إعادة تسميتها واضغط <kbd>F2</kbd>. تصف التغيير مرة واحدة، ويُعرض كل اسم قديم وجديد قبل أن يلامس أي شيء القرص.","docs.rename.find":"بحث واستبدال، كنص عادي أو كتعبير نمطي، مع <code>$1</code> و<code>$2</code> لما التقطه.","docs.rename.number":"يرقّم <code>{n}</code> في نص الاستبدال الملفاتِ بترتيب المعاينة؛ ويحشو <code>{n:03}</code> الرقم إلى ثلاث خانات.","docs.rename.case":"غيّر حالة الأحرف، واختر هل تنطبق القاعدة على الاسم وحده أم على الامتداد أيضًا. افتراضيًا تُترك الامتدادات على حالها.","docs.rename.check":"تُميَّز الصفوف التي ستتصادم، أو تستبدل ملفًا، أو تُنتج اسمًا يرفضه النظام، ولا يُعاد تسمية أي شيء ما دام أي صف مميّزًا: الدفعة تحدث كاملة أو لا تحدث إطلاقًا.","docs.rename.undo":"يتراجع <kbd>Ctrl+Z</kbd> عن إعادة التسمية، حتى بعد إعادة تشغيل التطبيق، ويعيدها <kbd>Ctrl+Shift+Z</kbd>. على Windows وLinux، يعيد «تراجع» أيضًا الملف المحذوف من سلة المحذوفات أو سلة المهملات. أما على macOS فلا يستطيع: استعد الملف من سلة المهملات بنفسك.","docs.preview.pane":"يعرض <strong>عرض ← معاينة</strong> (<kbd>Alt+P</kbd>) الملف المحدّد بجوار النتائج: الصور، والنصوص والشيفرة، والمستندات.","docs.preview.play":"يُشغَّل الصوت والفيديو في الجزء، مع التشغيل والإيقاف المؤقت، والانتقال، والتكرار، ومستوى الصوت. ويرسم الصوت شكلًا موجيًا يمكنك النقر عليه، مع المرمّز ومعدّل العيّنات والقنوات وشدة الصوت أسفله.","docs.preview.quickLook":"يفتح <kbd>Space</kbd> «نظرة سريعة»، وهي معاينة كبيرة فوق النافذة. وتواصل مفاتيح الأسهم التنقّل بين النتائج وهي مفتوحة، ويُغلقها <kbd>Space</kbd> أو <kbd>Esc</kbd>.","docs.preview.mac":"على macOS، تعرض «نظرة سريعة» أيضًا فتح الملف في «نظرة سريعة» الخاصة بالنظام، للصيغ التي يستطيع النظام عرضها ولا يستطيع Sourcerer.","docs.drives.unplugged":"عند فصل محرك أقراص، يبقى كل ما فُهرس عليه قابلًا للبحث. تحمل نتائجه شارة باسم المحرك، فتجيب أيضًا عن سؤال على أي محرك يوجد الملف، ويبحث <code>volume:</code> في محرك واحد باسمه. والمحرك الذي يعود بحرف آخر أو نقطة تركيب أخرى يُتعرَّف عليه رغم ذلك.","docs.drives.lists":"يحفظ <strong>ملف ← تصدير النتائج…</strong> (<kbd>Ctrl+S</kbd>) النتائج كقائمة ملفات <code>.efu</code> الخاصة بـ Everything، أو CSV، أو نص عادي، أو قائمة تشغيل M3U للملفات الصوتية، أو NDJSON لسكربت. ويبحث <strong>ملف ← فتح قائمة ملفات…</strong> (<kbd>Ctrl+O</kbd>) داخل قائمة، بما فيها قوائم Everything، بدلًا من الفهرس، إلى أن تختار <strong>إغلاق قائمة الملفات</strong>.","docs.health.index":"يُظهر <strong>أدوات ← صيانة الفهرس ← حالة الفهرس…</strong>، لكل موقع مراقَب، هل تصل التغييرات مباشرةً أم عند إعادة الفحص فقط، وكم يتأخر الفهرس، وكم تغييرًا أُسقط. وحين يكون هناك خطأ يقول ما هو، مع إعادة بناء بنقرة واحدة حيث يكون ذلك هو الحل.","docs.health.permissions":"المجلد الذي لا يستطيع التطبيق قراءته يبدو تمامًا كمجلد فارغ. ويسرد <strong>حالة الأذونات…</strong>، في القائمة نفسها أو من شارة «المجلدات المتخطّاة» في شريط الحالة، المجلداتِ التي تُخطّيت، وسبب النظام، والإصلاح. وعلى macOS يتحقق مما إذا كان «الوصول الكامل إلى القرص» ممنوحًا، ويفتح صفحة الإعدادات المناسبة إن لم يكن.","docs.portable.p1":"لتشغيل Sourcerer من وحدة USB، ضع ملفًا فارغًا باسم <code>portable.flag</code> بجوار التطبيق، أو شغّله بـ <code>--portable</code>. عندها يوجد الفهرس والإعدادات والإشارات المرجعية والسجلات في مجلد <code>Data</code> بجوار التطبيق، ولا يُسجَّل أي شيء لدى الحاسوب: لا خدمة في الخلفية، ولا معالج روابط، ولا أداة تحديث. حدّث النسخة المحمولة باستبدال مجلدها.","docs.portable.mac":"على macOS، يُنشأ مجلد <code>Data</code> بجوار التطبيق لا داخله، لأن الكتابة داخل التطبيق تكسر توقيعه.","docs.settings.open":"يفتح <strong>أدوات ← الخيارات…</strong> (<kbd>Ctrl+,</kbd>) الإعدادات، بتخطيط يشبه «الخيارات» في Everything: شجرة لوحات على اليسار، ومربع فوقها يصفّي اللوحات والخيارات أثناء الكتابة، والأزرار <strong>موافق</strong> و<strong>إلغاء</strong> و<strong>تطبيق</strong>.","docs.settings.panels":"تغطي اللوحات مظهر التطبيق، وسلوك البحث، والنتائج، واختصارات لوحة المفاتيح، والمجلدات ومحركات الأقراص والاستبعادات التي يتكوّن منها الفهرس، وكل عدسة، والخصوصية والتحديثات، والسجلات، والنسخ الاحتياطي وإعادة التعيين، واللغة.","docs.settings.hotkey":"يُحضر مفتاح اختصار عام التطبيق إلى المقدّمة من أي مكان، مع شريط البحث جاهزًا. اضبطه في <strong>الإعدادات ← عام ← لوحة المفاتيح</strong>. والرابط بالصيغة <code>freally://search?q=…</code> يفتح التطبيق بذلك البحث.","docs.language.p1":"يتحدث Sourcerer ثماني عشرة لغة. اختر إحداها في <strong>الإعدادات ← اللغة والمنطقة</strong> فيتبدّل التطبيق كله — القوائم والإعدادات ونوافذ الحوار وشريط الحالة — فورًا، دون إعادة تشغيل. وتعرض العربية النافذة من اليمين إلى اليسار.","docs.cli.intro":"يبحث الأمر <code>freally</code> في الفهرس نفسه الذي يبحث فيه التطبيق، عبر المُفهرِس نفسه، وبلغة الاستعلام نفسها.","docs.cli.formats":"تطبع <code>--json</code> و<code>--ndjson</code> و<code>--csv</code> النتائج للسكربتات، ويطبع <code>-0</code> مسارات مفصولة بـ NUL لـ <code>xargs -0</code>، ويختار <code>--fields</code> الأعمدة. ويُبيّن رمز الخروج ما إذا كان أي شيء قد طابق.","docs.cli.strict":"يرفض <code>--strict-everything</code> أي استعلام يستخدم شيئًا لا يملكه Everything، ويسمّيه — وهذه هي الطريقة للتحقق من أن الاستعلام يعمل في كليهما.","docs.cli.manage":"يُظهر <code>freally index</code> حالة المُفهرِس ويستطيع إيقافه مؤقتًا أو استئنافه أو التحقق منه أو ضغطه أو إعادة بنائه؛ ويحفظ <code>freally bookmark</code> الإشارات المرجعية ويسردها ويحذفها.","docs.cli.completions":"يطبع <code>freally completions</code> إكمالات لـ bash وzsh وfish وPowerShell، تشمل أسماء المُعدِّلات وإشاراتك المرجعية.","docs.privacy.telemetry":"لا يوجد أي قياس عن بُعد. يُبنى الفهرس ويُحفظ على حاسوبك أنت، ولا يُرسَل أي شيء عن ملفاتك أو عمليات بحثك إلى أي مكان.","docs.privacy.updates":"يسأل التطبيق مرة في اليوم عمّا إذا كان هناك إصدار أحدث؛ وفي <strong>الإعدادات ← الخصوصية والتحديثات</strong> يمكنك جعل ذلك أسبوعيًا أو شهريًا أو أبدًا، أو التحقق الآن. ويسأل قبل تثبيت أي شيء، مسمّيًا الإصدارين كليهما، والنسخة المحمولة لا تتحقق أبدًا.","docs.privacy.mode":"يوقف وضع الخصوصية تسجيل عمليات البحث الأخيرة ويعطّل عدسة الخصائص، التي تقرأ داخل الملفات.","docs.privacy.reports.title":"الإبلاغ عن مشكلة","docs.privacy.reports.where":"حين يصادف التطبيق خطأً، تحمل رسالته زر <strong>إبلاغ</strong> بجوارها. وبعد أي تعطّل، يعرض التشغيل التالي <strong>إبلاغ</strong> أو <strong>إخفاء</strong>.","docs.privacy.reports.page":"يفتح <strong>إبلاغ</strong> صفحة الإبلاغ، <code>freallyproducts.com/freally-sourcerer/report/</code>، في متصفحك، مع الحقائق التقنية معبّأة مسبقًا: يمكنك قراءتها لكن لا يمكنك تغييرها. وتضيف أنت ما كنت تفعله، وإن شئت عنوان بريد إلكتروني.","docs.privacy.reports.send":"لا يُرسَل أي شيء ما لم تضغط <strong>إرسال</strong> على تلك الصفحة، ولا يُرسَل أي شيء في الخلفية أبدًا.","docs.faq.missing.title":"لماذا يغيب ملف عن النتائج؟","docs.faq.missing.indexing":"ربما لا يزال الفهرس الأول قيد البناء: ويذكر شريط الحالة ذلك.","docs.faq.missing.roots":"ربما لا يكون مجلده مفهرسًا: تحقّق من المجلدات ومحركات الأقراص والاستبعادات تحت <strong>الإعدادات ← الفهارس</strong>.","docs.faq.missing.permissions":"ربما يكون مجلده غير قابل للقراءة: افتح <strong>حالة الأذونات…</strong>.","docs.faq.smaller.title":"كيف أجعل الفهرس أصغر؟","docs.faq.smaller.body":"استبعد المجلدات المليئة بملفات لا تبحث عنها أبدًا، مثل <code>node_modules</code> و<code>.git</code>، تحت <strong>الإعدادات ← الفهارس ← الاستبعاد</strong>.","docs.faq.rebuild.title":"كيف أبدأ الفهرس من جديد؟","docs.faq.rebuild.body":"يمسح <strong>أدوات ← صيانة الفهرس ← فرض إعادة بناء الفهرس…</strong> الفهرس ويبنيه من جديد من البداية. ويتحقق منه <strong>التحقّق من الفهرس…</strong> ويصغّره <strong>ضغط الفهرس…</strong> في القائمة نفسها.","kit.skip":"الانتقال إلى المحتوى","kit.nav.site":"الموقع","kit.nav.home":"الرئيسية","kit.nav.features":"الميزات","kit.nav.documentation":"التوثيق","kit.nav.changelog":"سجل التغييرات","kit.nav.language":"اللغة","kit.nav.allApps":"كل تطبيقات Freally","kit.badge.progress":"v0.23.0 منجز · v0.24.0 هو التالي","kit.cta.features":"شاهد كل الميزات","kit.cta.docs":"اقرأ التوثيق","kit.price":"Freally Sourcerer مجاني اليوم، لكنه قد لا يبقى مجانيًا إلى الأبد: قد تُباع الإصدارات المستقبلية.","kit.noDownloads":"لا توجد تنزيلات بعد، والشفرة المصدرية خاصة.","kit.label.overview":"نظرة عامة","kit.label.inside":"في الداخل","kit.label.roadmap":"خارطة الطريق","kit.ladder.done":"منجز","kit.ladder.planned":"مخطط له","kit.ladder.goal":"الهدف","kit.label.honesty":"الصراحة","kit.family.label":"عائلة Freally","kit.family.title":"<span class=\"hl-muted\">عائلة واحدة.</span> <span class=\"hl-bright\">ثمانية تطبيقات.</span>","kit.cta.label":"ما الذي تغيّر","kit.cta.title":"<span class=\"hl-muted\">كل إصدار،</span> <span class=\"hl-bright\">مدوَّن.</span>","kit.cta.lede":"يسرد سجل التغييرات كل ما تغيّر في Freally Sourcerer، إصدارًا بعد إصدار، بثماني عشرة لغة.","kit.cta.changelog":"اقرأ سجل التغييرات","kit.footer.thisApp":"هذا التطبيق","kit.footer.family":"عائلة Freally","kit.status.devVersion":"قيد التطوير · v0.23.2","kit.head.features":"<span class=\"hl-muted\">كل ما يفعله،</span> <span class=\"hl-bright\">جنبًا إلى جنب.</span>","kit.label.numbers":"بالأرقام","kit.label.free":"مجاني اليوم","kit.label.compare":"مقارنة","kit.label.principles":"المبادئ","kit.label.limits":"الحدود","kit.states.title":"ماذا تعني الحالات","kit.states.done":"مبنيّ وموسوم، لكنه ليس تنزيلًا على هذا الموقع","kit.states.planned":"لم يُبنَ بعد","kit.states.goal":"الإصدار الذي يقود إليه الطريق","kit.states.ladder":"شاهد كل درجة على الطريق","kit.head.documentation":"<span class=\"hl-muted\">كيف يعمل،</span> <span class=\"hl-bright\">خطوة بخطوة.</span>","kit.search.placeholder":"ابحث في التوثيق","kit.docs.contents":"المحتويات","kit.head.changelog":"<span class=\"hl-muted\">كل تغيير،</span> <span class=\"hl-bright\">إصدارًا بعد إصدار.</span>","kit.changelog.lede":"الأحدث أولًا: كل ما تغيّر في Freally Sourcerer، بكل لغة يتحدث بها هذا الموقع.","kit.changelog.versions":"الإصدارات","kit.changelog.unreleased":"غير منشور","kit.search.none":"لا شيء في هذا الموقع يطابق ذلك.","kit.zoom.close":"إغلاق","changelog.69c6a54708de":"<span class=\"release__meta\"><span class=\"release__ver\">غير مُصدَر</span></span>","changelog.6b02e0d363a4":"الإضافات","changelog.1e07f27ea3ab":"<strong>[كل المنصّات]</strong> <strong>عدسة الخصائص</strong> (SRC-N01 … SRC-N15) — عدسة خامسة تقرأ <em>ترويسات الحاويات</em>. <code>width:&gt;1920</code>، <code>camera-model:R5</code>، <code>author:lovelace</code>، <code>binary-type:arm64</code>، <code>package-version:0.23</code>، <code>broken-link:</code>، <code>entry-count:&gt;1000</code>، <code>font-scripts:cyrillic</code>، <code>from:ada@example.com</code>، <code>table-names:notes</code> — اثنتان وسبعون خاصية موزّعة على إحدى عشرة مجموعة، يمكن كتابة كلٍّ منها كمُعدِّل، وكلٌّ منها متاح أيضًا كعمود في النتائج. حزمة crate جديدة هي <code>freally-properties</code>؛ ونطاق أسماء جديد <code>property:</code> في لغة الاستعلام (DSL) للصيغة العامة (<code>property:duration&gt;60</code>، وهي الطريقة للوصول إلى مفتاح يحمل اسمَه مُعدِّلٌ أقدم بالفعل).","changelog.a87ab2c792bf":"<strong>كسولة ويُبطِلها سجل التغييرات.</strong> لا شيء يعمل وقت الفهرسة. تُقرأ الخاصية أول مرة يسأل فيها استعلام عن الملف، ثم تُخزَّن مؤقتًا مقرونةً بقيمة <code>mtime_ns</code> الخاصة به، فيُبطِل سجل التغييرات هذه العدسة دون أن تشترك العدسة فيه أصلًا — وهو العقد نفسه الذي تعمل به عدسة الصوت منذ المرحلة 9. وتُخزَّن حالات الإخفاق مؤقتًا أيضًا: فمجلد من ملفات <code>.txt</code> يكلّف عملية <code>open</code> واحدة لكل ملف في كل جيل من أجيال الفهرس بدلًا من واحدة مع كل ضغطة مفتاح.","changelog.ca8eac0102ce":"<strong>الترويسات فقط.</strong> لا يفكّ أيّ محلّل ترميز صورة، ولا يفصل تدفقًا (demux)، ولا يعرض صفحة، ولا يقرأ صفًّا من قاعدة بيانات أيّ أحد. هذا الحدّ هو ما يُبقي <code>width:&gt;1920</code> قابلًا للإجابة بسرعة الكتابة على مجلد مليء بملفات RAW.","changelog.982e60011610":"<strong>كلّية (total).</strong> لا يمكن لأي ملف أن يُفشل استعلام خصائص. ترويسة مبتورة، أو ملف <code>.png</code> هو في الحقيقة ملف نصي، أو مسار غير قابل للقراءة: كلها تعني «هذا الصف لا خصائص له»، وهو سبب وجيه تمامًا لعدم المطابقة.","changelog.020bc33d94a7":"<strong>الصيغ.</strong> أبعاد صور PNG / JPEG / GIF / WebP / BMP / TIFF / AVIF-HEIC وتفاصيلها الداخلية (SRC-N02، N04)؛ وبيانات الالتقاط EXIF مع علامة تدل على وجود GPS <strong>دون تخزين أي إحداثيات</strong> (N03)؛ والخصائص التقنية لملفات MP4 / MOV / MKV / WebM / AVI (N05)؛ وقواميس معلومات PDF وملفات OOXML <code>core.xml</code> / <code>app.xml</code> (N08)؛ ومعمارية PE / ELF / Mach-O وسلاسل Windows VERSIONINFO وحالة Authenticode (N09)؛ والبيانات الوصفية لحزم MSI / deb / rpm / pkg (N10)؛ وأهداف <code>.lnk</code> / <code>.desktop</code> والروابط الرمزية مع أداة للعثور على الروابط المعطوبة <code>broken-link:</code> (N11)؛ وعدد المُدخلات في zip / 7z / tar ونسبة الضغط واكتشاف التشفير والأرشيفات متعددة الأجزاء (N12)؛ وعائلة خطوط TTF / OTF / WOFF ووزنها وعدد حروفها الرسومية (glyphs) وأنظمة الكتابة التي تدعمها، مقروءةً من جدول <em>cmap</em> لا من نطاق مُعلَن (N13)؛ وترويسات RFC-822 وmbox (N14)؛ ومخطط SQLite (N15).","changelog.2f4f9e89e8ed":"<strong>مُستخرِجا محتوى جديدان.</strong> تغذّي ترويسات ملفات <code>.eml</code> / <code>.mbox</code> ونصوصها عدسةَ المحتوى، مع إدراج المرفقات كمُدخلات افتراضية بصيغة <code>container!inner</code> التي يستخدمها مُستخرِج استعراض الأرشيفات (archive-peek) — ولا تُفكّ <em>بايتات</em> المرفقات أبدًا (N14). أما <code>.db</code> / <code>.sqlite</code> فتُسهم دائمًا بأسماء جداولها وأعمدتها، وبأوائل صفوف الأعمدة النصية <strong>فقط</strong> عبر إعداد يأتي معطَّلًا افتراضيًا (N15): فقاعدة البيانات في مجلد التنزيلات هي بيانات تطبيق يخصّ أحدهم.","changelog.58bf7de69c7c":"<strong>أعمدة الخصائص</strong> (SRC-N06) — يمكن لأي خاصية أن تصبح عمودًا في النتائج من قائمة <code>+</code> في صف العناوين، قابلًا للترتيب، مع تخطيطات تلقائية لكل عامل تصفية سريع (الصور تعرض الأبعاد، والفيديو يعرض المدة والدقة). أصبحت معرّفات الأعمدة الآن <code>name</code> … <code>ext</code> إضافةً إلى <code>prop:&lt;key&gt;</code>، مستمدّةً من سجلّ الخصائص بدلًا من اتحاد (union) ثابت.","changelog.aa4087512231":"<strong>إحصاءات النتائج</strong> (SRC-N07) — النقر على عدد النتائج في شريط الحالة يفتح إجمالي البايتات، والأعداد والأحجام حسب الامتداد وحسب النوع، والصف الأكبر / الأقدم / الأحدث، ومدرّجًا تكراريًا لكل خاصية تحملها المجموعة فعلًا. تُحسب في الخدمة الخلفية على مجموعة النتائج كاملة، لا على الصفحة الظاهرة على الشاشة، بحدّ أقصى قدره 200 000 صف مع ملاحظة «هذا حدّ أدنى» عندما يُبلَغ ذلك الحدّ.","changelog.47c227c9a823":"<strong>الإعدادات ← العدسات ← الخصائص</strong> — تشغيل العدسة أو إيقافها، ومفاتيح تبديل لكل مجموعة، وميزانية الاستخراج لكل ملف، ومفتاح صفوف SQLite، ومفتاح الأعمدة التلقائية. يُوقف وضع الخصوصية العدسة كلها، لأنها تقرأ داخل الملفات، وهذا بالضبط ما يُعنى به وضع الخصوصية.","changelog.2662e0d9c21f":"<strong>انحرافات مُعلَنة لا مُخفاة.</strong> يُبلغ التحقق من التوقيع على macOS عن توقيع <em>مُضمَّن</em> لا عن توقيع جرى التحقق من صحته: ففحص التوثيق (notarization) عبر <code>Security.framework</code> هو FFI غير آمن مقابل إطار عمل لا يملك هذا المشروع أي جهاز يستطيع تجربته عليه، وقيمة <code>valid</code> لا يمكن التحقق منها أسوأ من قيمة <code>embedded</code> صادقة. لا تُنتج خطوط WOFF2 شيئًا — فـ brotli مع تحويلات glyf/loca يمثّلان مكتبة خطوط ثانية، لا مجرد قراءة ترويسة. ولا تحصل ملفات ELF التنفيذية على خاصية <code>signature</code> إطلاقًا، لأن Linux يوقّع الحزم لا الملفات التنفيذية، وSRC-N10 هو موضع تلك الإجابة. <em>أسماء</em> الخصائص مشتقّة من مفاتيحها (<code>aspect-ratio</code> → &quot;Aspect ratio&quot;) في كل اللغات بدلًا من ترجمتها؛ أما عناصر الواجهة المحيطة بها فمترجمة كالمعتاد.","changelog.bc802b748761":"<strong>[كل المنصّات]</strong> <strong>ما تكتبه يظهر بخط عريض في النتائج</strong>، أثناء الكتابة، في عمودي الاسم والمسار كليهما. لا تُميَّز إلا مصطلحات بحثك: فالمُعدِّل مثل <code>ext:json</code> يضيّق القائمة ولا يمثّل شيئًا تبحث عنه، لذا لا تُكتب <code>json</code> بالخط العريض داخل كل اسم ملف. يكون التمييز بسماكة الخط لا بكتلة تظليل، فيبقى مقروءًا على الصف المحدّد وفي كلتا السمتين.","changelog.0a3eaf604faf":"<strong>[كل المنصّات]</strong> <strong>الإبلاغ عن خلل</strong> — <code>Help → Report a Bug…</code>، إضافةً إلى تنبيه يظهر عند التشغيل التالي بعد أي تعطّل. يكتب خطّاف الذعر (panic hook) تقرير تعطّل <strong>مُنقّحًا</strong> محليًا (يُحجب مسار المجلد الرئيسي واسم المستخدم قبل أن يلامس الملف القرص)، وتعرض لك نافذة الحوار النص <strong>الحرفي</strong> الذي سيُرسل — إصدار التطبيق ونظام التشغيل فقط — قبل أن تعرض فتح مشكلة على GitHub أو مسودة بريد مُعبّأة مسبقًا. <strong>لا يُرسل أي شيء تلقائيًا</strong>؛ فلا قياس عن بُعد (telemetry) ولا خادم نشغّله. يوجد تدريبان في الإعدادات ← السجلات والتصحيح.","changelog.09c294b4b464":"<strong>[كل المنصّات]</strong> <strong>التحقّق من التحديثات</strong> — أصبحت الإعدادات ← الخصوصية والتحديثات تسأل أداة التحديث بدلًا من فتح صفحة ويب. تُبلغ عن الإصدار الذي تشغّله، وتعرض ملاحظات الإصدار بروابط عاملة، وعند توفّر تحديث تطرح <strong>مربع نعم/لا يسمّي الإصدارين كليهما</strong> قبل تثبيت أي شيء. عند الموافقة تُوقف الخدمة الخلفية للمُفهرِس، وتثبّت، ثم تُغلق؛ وعلى Windows تعرض صفحة الإنهاء في المثبّت تشغيل الإصدار الجديد. ويلتزم الفحص عند التشغيل بإعداد التواتر، ويتنحّى عندما يكون هناك تقرير تعطّل بالانتظار، ويبقى <strong>صامتًا</strong> عندما يكون الجهاز غير متصل بالشبكة.","changelog.59f3ea0ca50a":"<strong>[Windows]</strong> يُبلغ <code>freally-indexd status</code> عمّا إذا كانت الخدمة الخلفية مسجّلة كخدمة، وعن حالتها كما يراها مدير الخدمات. كان التثبيت وإلغاء التثبيت موجودين دون أي وسيلة للسؤال عمّا حدث.","changelog.5b14114e2f2b":"<strong>[التوثيق]</strong> <code>docs/EVERYTHING_MIGRATION_GUIDE.md</code> — ما ينتقل من Everything الخاص بـ voidtools، وما الجديد، والأمور الثلاثة التي ستفاجئك. <code>docs/MENU_REFERENCE.md</code> — عناصر القوائم الـ 112 كلها واختصاراتها، مولَّدة من مواصفات القوائم فلا يمكن أن تتقادم.","changelog.2643567f0f72":"<strong>[التحزيم]</strong> يحمل <code>packaging/</code> ملفات بيان (manifests) لـ winget وChocolatey وHomebrew Cask وFlathub وSnap، يولّدها <code>scripts/gen-packaging.mjs</code> من إصدار منشور، فتكون المجاميع الاختبارية هي نفسها التي يقدّمها GitHub.","changelog.013883122f3c":"<strong>[الإصدار]</strong> يُثبت <code>scripts/verify-updater-chain.mjs</code> أن الإصدار المنشور قابل للتحديث فعلًا: إذ يقارن معرّف المفتاح داخل توقيع كل منصّة بالمفتاح العام المُضمَّن في الملفات التنفيذية. تفشل أداة التحديث بشكل مغلق <strong>وصامت</strong>، لذا لا شيء آخر يكشف إصدارًا موقَّعًا بالمفتاح الخطأ.","changelog.0c8009384b06":"<strong>[كل المنصّات]</strong> أصبح بالإمكان التراجع عن حذف ملف. كان <code>files_delete</code> يرسل الصفوف إلى سلة مهملات نظام التشغيل، وهي قابلة للاستعادة، لكنه لم يكن يسجّل شيئًا — لذا لم يعرض أمر «تراجع» في التطبيق استعادة أي حذف على أي منصّة. أصبح الحذف يُسجَّل الآن، ويستعيد Ctrl+Z من سلة المحذوفات (Windows) أو من سلة مهملات freedesktop (Linux).","changelog.e370b0fcd2c3":"<strong>[macOS فقط]</strong> يُسجَّل الحذف على أنه <strong>غير قابل للتراجع، مع عرض السبب</strong>، لأن Finder هو من يملك ميزة Put Back (الإرجاع) ولا يوفّر لها أي API. أصبح أمر «تراجع» يقول ذلك بدلًا من الصمت: فـ <code>next_undo</code> يرفض، عن حق، تخطّي إدخال غير قابل للتراجع، ما كان يعني أن Ctrl+Z لا يفعل شيئًا على الإطلاق بعد الحذف ولا يشرح السبب أبدًا.","changelog.63589b7d0b3f":"<strong>[كل المنصّات]</strong> تسأل الأوامر المخصّصة مرة واحدة، عبر نافذة حوار أصلية من نظام التشغيل، قبل تشغيل أي برنامج لأول مرة. ترتبط الموافقة بالبرنامج، فلا تؤدي إعادة تسمية الأمر إلى السؤال مجددًا، ويذكر التنبيه الوسائط إلى جانب البرنامج. تُحفظ الموافقات خارج <code>settings.json</code> — فتخزينها فيه سيضع قائمة السماح خلف المسار نفسه القابل للكتابة من الـ webview، وهو ما وُجد التنبيه أصلًا للدفاع عنه. راجع <code>docs/SECURITY.md</code>.","changelog.549a5f40d4d8":"<strong>[كل المنصّات]</strong> يمكن الآن تشغيل مقابض تغيير حجم الأعمدة من لوحة المفاتيح: الأسهم تحرّكها قليلًا، وHome/End تقفز إلى الحدود. كانت من قبل قابلة لتلقّي التركيز ولا تفعل شيئًا، وهذا أسوأ من ألا تكون قابلة لتلقّي التركيز أصلًا.","changelog.2a6141e43be0":"التغييرات","changelog.484caa95cf9c":"<strong>[كل المنصّات]</strong> <strong>أصبح البحث في أسماء الملفات أسرع بكثير للاستعلامات المُصفّاة.</strong> عند القياس على مليون ملف، انخفض <code>ext:json</code> من 229 ms إلى 11 ms (20.7×)، و<code>regex:^report-</code> من 76 ms إلى 9.5 ms (7.9×)، و<code>*.rs</code> من 60 ms إلى 19 ms (3.1×)، و<code>report path:horizon</code> من 31 ms إلى 12 ms (2.6×). كانت عمليات البحث البسيطة بكلمة واحدة سريعة أصلًا ولم تتغيّر. أربعة أمور صنعت الفرق: أصبحت أشكال الاستعلام هذه تُنتج بذرة ثلاثيات (trigram seed) بدلًا من المرور على كل اسم مفهرس؛ وأصبح فهرس الأسماء يحمل امتداد كل صف وحجمه وتاريخه وبتّات سماته، فتُجاب هذه المرشّحات من الذاكرة بدلًا من جلب كل صف مطابق من SQLite؛ وأصبح مسار المجلد يُخزَّن مرة واحدة بدلًا من مرة لكل ملف يحتويه، ما يتيح لـ <code>path:</code> رفض الصفوف قبل جلبها؛ وأصبحت كتابة كلمة أطول تضيّق نتائج ضغطة المفتاح السابقة بدلًا من البدء من جديد. على Linux، مع 200 000 ملف، أصبح كل سيناريو من سيناريوهات قياس الأداء أقل من 8 ms. راجع قسم <strong>أداء البحث (Search performance)</strong> في ملف README للاطلاع على الجداول الكاملة، والجهاز الذي قيست عليه، وسبب اختلاف النتائج على جهازك.","changelog.89b30b76bb7e":"<strong>[كل المنصّات]</strong> <strong>أصبحت عوامل التصفية السريعة تغطّي جزءًا أكبر بكثير من قرصك.</strong> ارتفع «صوت» من 22 امتدادًا إلى 65، و«فيديو» من 23 إلى 79، و«صورة» من 24 إلى 77، و«مستند» من 25 إلى 86، و«أرشيف» من 23 إلى 70. أصبح كل امتداد تحمله عوامل التصفية في Everything نفسه موجودًا هنا — ويتحقق من ذلك اختبار يسمّيها واحدًا واحدًا — فلا يغيب هنا شيء كان يمكنك العثور عليه تحت عامل تصفية في Everything. الإضافات هي الصيغ الأحدث من إعدادات Everything الافتراضية: Opus وAVIF وJXL وHEIC وملفات RAW للكاميرات من كل الشركات المصنّعة الكبرى وzstd وOpenDocument والكتب الإلكترونية وصيغ Apple iWork. يمكنك كتابتها أيضًا بالأسماء البديلة التي تتوقعها — <code>music:</code> و<code>movies:</code> و<code>photos:</code> و<code>docs:</code> و<code>compressed:</code> و<code>zip:</code>. تبقى الشيفرة المصدرية خارج <strong>مستند</strong> (بينما يضمّ Everything إليه <code>c</code>/<code>cpp</code>/<code>h</code>/<code>java</code>)؛ ويعيد لك <code>ext:c;cpp;h</code> المجموعة القديمة.","changelog.170d6493da10":"<strong>[كل المنصّات]</strong> <strong>لم يعد عامل التصفية الذي يغطّي شريحة كبيرة من قرصك بطيئًا.</strong> كان اختيار «صوت» أو «مضغوط» يمرّ على كل صف مفهرس واحدًا تلو الآخر، لأن اتحاد ستين امتدادًا لا يمكنه استخدام فهرس الثلاثيات — فالتضييق على أحدها سيُسقط مطابقات التسعة والخمسين الأخرى. أصبح Freally بدلًا من ذلك يقرأ عمود الامتدادات مباشرةً على طول الذاكرة، أربعة بايتات لكل صف. عند القياس على 2.7 مليون ملف، انتقل عامل تصفية يطابق خُمسها من أبطأ أشكال الاستعلام إلى أسرعها.","changelog.30a936879584":"<strong>[كل المنصّات]</strong> <strong>أصبح عدد النتائج هو عدد المطابقات، لا عدد الصفوف على الشاشة.</strong> عامل التصفية الذي يطابق نصف مليون ملف يقول ذلك، كما يفعل Everything بعبارة «531,129 objects»، مع الاستمرار في جلب الصفحة التي تراها فقط. وعندما يكون الاستعلام واسعًا بما يكفي لبلوغ سقف المرشّحين، يُبلَّغ عن العدد كحدّ أدنى بدلًا من رقم يبدو دقيقًا وهو ليس كذلك.","changelog.6af3be76b723":"<strong>[كل المنصّات]</strong> أصبحت عوامل التصفية السريعة تطابق الامتداد الحقيقي للملف بدلًا من أي شيء يلي النقطة الأخيرة في اسمه. الملف النقطي (dotfile) مثل <code>.jsonrc</code> لا امتداد له، لذا لم يعد يظهر تحت عامل تصفية سريع لـ JSON — وهذا ما كان يفعله <code>ext:json</code> دائمًا، فأصبح الاثنان متفقين الآن.","changelog.d37659a5fceb":"<strong>[كل المنصّات]</strong> <strong>أصبحت فهرسة قرص كبير أسرع بنحو 20×.</strong> كانت كل عملية إيداع (commit) أثناء الفحص تعيد بناء فهرس مرتّب لكل اسم ملف رُصد حتى تلك اللحظة — عند 200 000 ملف كان ذلك يستغرق 1.34 ثانية من إيداع مدته 1.4 ثانية، ويزداد سوءًا كلما تقدّم الفحص. ولم يكن أي شيء يقرأ ما ينتجه. انتقل الفحص الأول لمحرك أقراص يضم ملايين الملفات من ساعات إلى دقائق.","changelog.e2099089ef3b":"<strong>[كل المنصّات]</strong> أصبحت القوائم الفرعية <strong>تُثبَّت بالنقر</strong>. تُبقي النقرة القائمة مفتوحة أينما انتقل المؤشر بعدها، وهذا ما تحتاجه لوحة اللمس وما يتطلبه الاختبار الآلي؛ ولا يزال التمرير فوقها يفتحها.","changelog.fb8d168729ab":"<strong>[كل المنصّات]</strong> أصبح <code>freally index pause</code> و<code>resume</code> يوقفان الفهرسة مؤقتًا ويستأنفانها فعلًا، بضبط <code>monitor_changes</code> على كل وحدة تخزين مكتشفة. كان كلٌّ منهما سابقًا يرسل مفتاح إعدادات واحدًا لا علاقة له بالأمر ويطبع رسالة نجاح.","changelog.1246fc93bca0":"الإصلاحات","changelog.40cc68328345":"<strong>[كل المنصّات]</strong> كانت لوحة «حالة الفهرس» تستنزف الخيط الرئيسي بالكامل وتُغرق الخدمة الخلفية باستدعاءات <code>index_health</code> بأسرع ما يمكنها الإجابة، بدلًا من الاستطلاع كل 2 s. كان <code>$effect</code> الخاص بها يبدأ المستطلِع مباشرةً في موضعه، والمستطلِع يقرأ ويكتب الحالة التي يشترك فيها التأثير بعد ذلك، فكانت كل إجابة تعيد تشغيله. كانت اللوحة غير قابلة للاستخدام، وكان التطبيق يتوقف عن الاستجابة ما دامت مفتوحة. وكان هذا الخلل موجودًا في الإصدارات منذ M13؛ ومواصفة الاختبار الشامل (e2e) التي كانت ستكشفه كانت مُعلَّمة بـ <code>test.fixme</code> لسبب لا علاقة له به.","changelog.3e288bea5aec":"<strong>[كل المنصّات]</strong> كان <code>path:</code> و<code>parent:</code> يخصّصان سلسلة بأحرف صغيرة لكل صف مُحمَّل بالكامل (hydrated)، مع أن <code>path:</code> كانت لديه نسخة مخزّنة مؤقتًا بالفعل.","changelog.760a29ec7c23":"<strong>[كل المنصّات]</strong> كان لنوافذ الحوار نصفا قطر مختلفان للزوايا وثلاثة ظلال، لأن الخاصية المضمّنة <code>style</code> في <code>Modal</code> تتغلّب بصمت على الصنف (class) الخاص بالإطار نفسه. أصبحت الخاصية الآن مقتصرة على المقاسات، ويُبلَّغ في بيئة التطوير عن أي محاولة لتجاوزها.","changelog.adfeb89fa1aa":"<strong>[كل المنصّات]</strong> كان خياران من خيارات <strong>عرض ← تنسيق العرض ← تنسيق الحجم</strong> الستة لا يفعلان شيئًا. يعرض مخطط الإعدادات <code>b | kb | mb | gb | auto_binary | auto_decimal</code>؛ بينما كان <code>formatBytes</code> يقبل مفردات مختلفة من خمس قيم، وكان كل موضع استدعاء يتجاوز عدم التطابق بتحويل النوع (cast)، فكان <code>b</code> و<code>auto_decimal</code> ينتهيان إلى فرع «تلقائي (ثنائي)». أصبحت المفردات واحدة الآن، ويعدّ <code>auto_decimal</code> بالآلاف، وكل خيار مثبَّت باختبار.","changelog.8fe7422dc893":"<strong>[كل المنصّات]</strong> كانت إضافة عمود خصائص ستفشل بصمت في التثبيت الحقيقي. اكتسب <code>ColumnId</code> في TypeScript الصيغة <code>prop:&lt;key&gt;</code>؛ بينما بقي نظيره في Rust تعدادًا (enum) مغلقًا من ستة متغيّرات، فكان <code>settings_set</code> يرفض التعديل بأكمله — لا ذلك العمود فحسب — بالخطأ <code>unknown variant</code>، وكانت الواجهة تسجّل ذلك وتمضي. أصبح جانب Rust الآن يتحقق من <code>prop:&lt;key&gt;</code> مقابل سجلّ الخصائص، ما يُبقي المخطط مغلقًا. اختبار Playwright الذي يضيف عمودًا يعمل مقابل محاكاة لـ IPC وما كان ليكشف ذلك؛ أما الآن فتكشفه ثلاثة اختبارات ذهاب وإياب في <code>settings.rs</code>.","changelog.c4182c80506c":"<strong>[كل المنصّات]</strong> لم يكن من الممكن الوصول إلى أي خاصية نصية أو منطقية عبر نطاق الأسماء <code>property:</code>. كان الفاصل <code>=</code> في القواعد يُمرَّر إلى القيمة، فكان <code>property:camera-make=canon</code> يبحث عن النص الحرفي <code>=canon</code> ولا يُرجع شيئًا، بينما كان <code>property:has-alpha=yes</code> يُصدر خطأ. لم تكن تزيله إلا الأنواع الرقمية وأنواع التاريخ.","changelog.9d558fa75e7e":"<strong>[كل المنصّات]</strong> كانت مطابقة الخصائص النصية حسّاسة لحالة الأحرف في اتجاه واحد لأي قيمة غير ASCII: كان نص البحث يُطوى بـ <code>to_ascii_lowercase</code> وقت التحليل، وقيمة الصف بـ <code>to_lowercase</code> الكاملة لـ Unicode وقت المطابقة، فلم يكن <code>camera-model:MÜLLER</code> يعثر أبدًا على <code>Müller</code>.","changelog.a37ae4d3cefc":"<strong>[كل المنصّات]</strong> كان الترتيب حسب عمود خصائص يضع الصفوف التي <em>لا</em> تملك تلك الخاصية أولًا في الترتيب التنازلي، لا أخيرًا كما هو موثّق — إذ كانت دالة المقارنة تُرجع قيمة ثابتة <code>1</code> يعكس مُضاعِفُ الاتجاه إشارتها بعد ذلك. فظهرت صفحة من الخانات الفارغة حيث كان يجب أن تظهر أكبر القيم.","changelog.1847045d095f":"<strong>[كل المنصّات]</strong> كان النقر على شريحة عامل تصفية النوع يطلب من الخدمة الخلفية مجموعة الأعمدة القديمة: إذ كان التخطيط التلقائي يُطبَّق بعد أن يكون تغيير التحديد قد أطلق البحث بالفعل، فكانت أعمدة الخصائص الجديدة تظهر فارغة حتى تُطلق ضغطة مفتاح لا علاقة لها بحثًا جديدًا.","changelog.39af32b4d343":"<strong>[كل المنصّات]</strong> لم تكن إعدادات عدسة الخصائص تصمد أمام إعادة تشغيل الخدمة الخلفية. لا شيء يُحفظ على جانب الخدمة الخلفية، ولم يكن يدفعها إليها إلا <em>حفظ</em> الإعدادات، فكانت العدسة التي أوقفها المستخدم — أو أوقفها وضع الخصوصية — تعود للعمل عند التشغيل التالي للخدمة الخلفية بينما تُظهرها الواجهة متوقفة. أصبحت الإعدادات المحمَّلة تُعاد إلى الخدمة الخلفية عند بدء التشغيل.","changelog.426b2fbb21fa":"<strong>[كل المنصّات]</strong> كانت قائمة إضافة الأعمدة تُفتح خارج الشاشة. زر <code>+</code> الذي يفتحها مثبَّت على الحافة اليمنى للنافذة، فكان <code>left: clientX</code> غير المقيَّد يدفعها كلها تقريبًا — عدا شريحة رفيعة — إلى ما وراء الحافة دون أي إمكانية للتمرير.","changelog.1be320f46969":"<strong>[كل المنصّات]</strong> كان بإمكان ترويسة صورة تالفة أن تتسبّب في تجاوز سعة <code>i64</code> عند حساب الميغابكسلات — فمربّع <code>0xFFFFFFFF</code> يتخطّى <code>i64::MAX</code> — ما يُحدث ذعرًا (panic) في بناء التصحيح ويعطي بناء الإصدار عددًا سالبًا.","changelog.ffa5958e11a4":"<strong>[كل المنصّات]</strong> كانت القيمة <code>0</code> لـ <code>property_budget_ms</code> عبر قناة الاتصال تحوّل العدسة كلها بصمت إلى عملية بلا أثر: فكل عملية استخراج تبدأ وقد تجاوزت مهلتها، ويعود كل ملف بلا خصائص وبلا خطأ. كان حقل الأرقام في الإعدادات يفرض حدًا أدنى؛ أما قناة الاتصال فلا. أصبحت القيمة تُرفع إلى الحد الأدنى عند وصولها.","changelog.065a03b57ec4":"<strong>[كل المنصّات]</strong> عند إيقاف أي مجموعة خصائص، كانت كل إصابة في الذاكرة المؤقتة تنسخ خريطة الخصائص كاملة نسخًا عميقًا — وهو التخصيص لكل صف الذي وُجد <code>Arc</code> المشترك لتجنّبه، وكان يُدفع ثمنه على كل صف من كل استعلام ما دام الإعداد قائمًا. أصبح العرض المُصفّى يُحفظ (memoized) لكل إدخال ويُستبعد عند تغيّر المجموعة.","changelog.1f99920ac00d":"<strong>[كل المنصّات]</strong> كانت إعادة كتابة <code>length:</code> تمرّ على شجرة AST للاستعلام بكاملها وتنسخها نسخًا عميقًا مع كل ضغطة مفتاح في كل بحث، بما في ذلك عمليات البحث التي لا تحتوي على <code>length:</code> أصلًا، لأن الخدمة الخلفية توصل دائمًا مزوّد خصائص.","changelog.8f6fb4eb7f42":"الأمان","changelog.1a1f843d10c5":"<strong>[Windows]</strong> هدف الاختصار عبارة عن بايتات مأخوذة من ملف غير موثوق، وكانت الإجابة عن <code>broken-link:</code> تعني استدعاء <code>Path::exists</code> عليه. على Windows يسلّم ذلك مسار UNC إلى مُعيد توجيه SMB، الذي يتصل بالمضيف المسمّى ويقدّم بيانات اعتماد NTLM للمستخدم المسجّل دخوله — وهي البدائية الكلاسيكية للمصادقة القسرية عبر روابط الاختصار، وكانت الفهرسة وحدها ستُطلقها، بمصافحة واحدة لكل ملف، دون أي نقرة. كان يكفي إسقاط مجلد من ملفات <code>.lnk</code> تشير إلى <code>\\attacker\\share\\x</code> في أي مجلد مراقَب. أصبحت الأهداف تُفحص الآن بحثًا عن صيغ UNC وURL قبل حلّها، والهدف البعيد يترك <code>broken-link</code> دون تعيين بدلًا من استكشافه. والحماية نفسها تغطّي أهداف الروابط الرمزية، التي تصل بالطريقة نفسها داخل أي أرشيف.","changelog.c599b83df9e1":"<strong>[Windows]</strong> كان التحقق من Authenticode يعمل بـ <code>dwProvFlags: 0</code>. يمنع <code>WTD_REVOKE_NONE</code> استعلامات CRL وOCSP لكنه لا يمنع جلب AIA في محرك السلسلة، فكان ملف تنفيذي موقَّع ذاتيًا تُسمّي شهادته <code>http://attacker/&lt;unique&gt;.cer</code> سيحوّل الفهرسة إلى إشعار قراءة — وصل الملف، من عنوان IP هذا، في هذا الوقت — صادر عن خدمة خلفية تَعِد لوحة الخصوصية فيها بعدم إرسال أي طلب صادر. أصبح الآن مثبَّتًا على <code>WTD_CACHE_ONLY_URL_RETRIEVAL | WTD_REVOCATION_CHECK_NONE</code>.","changelog.4118fb4fed0e":"الإزالات","changelog.7e47a128e1ba":"<strong>[كل المنصّات]</strong> إعداد <strong>إزالة وحدات التخزين غير المتصلة تلقائيًا</strong>. لم يكن يتحكّم في شيء — لم تقرأه أي شيفرة قط — وما كان يصفه هو عكس السلوك الذي صدر: إذ <em>تُحفظ</em> وحدة التخزين المفصولة عمدًا ككتالوج غير متصل كي تبقى صفوفها قابلة للبحث وموسومة بشارة. ولو نُفّذ كما هو مكتوب، مفعّلًا افتراضيًا، لحذف الفهرس الخاص بكل محرك أقراص مفصول.","changelog.706f136720e0":"<span class=\"release__meta\"><span class=\"release__ver\">v0.23.2</span><time class=\"release__date\" datetime=\"2026-08-19\">2026-08-19</time></span><span class=\"release__title\">تدوير مفتاح أداة التحديث وإصلاح CI</span>","changelog.31b4f34d5ada":"التطبيق نفسه الموجود في <code>0.23.1</code>، الذي وُسم لكن إصداره استُبدل بدلًا من نشره. كل ما في قسم <code>0.23.1</code> أدناه يصدر هنا؛ وما يلي هو ما تغيّر فوقه.","changelog.965ce76814aa":"<strong>مفتاح توقيع جديد لأداة التحديث.</strong> كانت الإصدارات حتى <code>0.23.1</code> موقَّعة بـ <code>9F291C936CFA28B7</code>، الذي لم يكن نصفه الخاص موجودًا إلا كسرّ في مستودع GitHub. لا يمكن قراءة أسرار المستودع مجددًا، لذا لم يكن ممكنًا نسخ ذلك المفتاح أو نقله أو استعادته — وقد زال الآن. الإصدارات بدءًا من <code>0.23.2</code> موقَّعة بـ <code>E5035E2194EB7E04</code>، الذي يُحفظ نصفه الخاص وكلمة مروره ونصفه العام معًا خارج GitHub.","changelog.926a99810869":"<strong>هذا يعطّل أداة التحديث في أي تثبيت للإصدار <code>0.23.1</code> أو أقدم</strong>: فالملفات التنفيذية القديمة تتحقق مقابل مفتاح عام لم يعد يوقّع أي شيء، لذا سيفشل التحديث في التحقق من التوقيع بدلًا من أن يُثبَّت. أعد التثبيت من التنزيلات أدناه. لا يُعرف أي تثبيت متأثر — فأعداد التنزيل لكل إصدار سابق تطابقت مع فحص الروابط الروتيني.","changelog.95ee6438be83":"<strong>كان <code>apt-get update</code> قادرًا على تعليق بناء Linux إلى أجل غير مسمّى.</strong> لم تُرجع مرآة Ubuntu التي تفضّلها صور المشغّلات، <code>azure.archive.ubuntu.com</code>، أي شيء لمجموعة فهارس jammy بأكملها لعدة ساعات، ومع عدم ضبط أي مهلة انتظرت الخطوة بدلًا من أن تفشل — حتى ساعة كاملة مقابل خط أساس قدره 72 ثانية، أربع مرات، احتاجت كلٌّ منها إلى إلغاء يدوي. أصبحت عمليات البناء تستخدم <code>archive.ubuntu.com</code>، وتحدّ الخطوة بعشر دقائق، وتعيد المحاولة. وقد استغرقت الخطوة نفسها بعد ذلك 41 ثانية.","changelog.7f5127beca31":"<strong>كان <code>workflow_dispatch</code> في سير عمل الإصدار يبني الشجرة الخطأ.</strong> يأخذ وسمًا كمُدخل وهو الطريقة الموثّقة لإعادة بناء إصدار، لكن خطوة السحب (checkout) فيه لم يكن لها <code>ref</code>، فكان يسحب أي فرع أُطلق منه بينما يسمّي المُخرجات باسم الوسم المُدخل.","changelog.e492554f1e26":"<strong>كانت اختبارات ميزانية الوقت الفعلي تعمل تحت حمل متوازٍ كامل في CI.</strong> كان <code>scripts/ci-local.mjs</code> قد عُدّل لتشغيلها منفردة — لأن نموذج nextest القائم على عملية لكل اختبار يضع الجهاز تحت حمل مستمر فيقيس التأكيد عندها الحملَ نفسه — لكن CI ظل يشغّلها مع كل شيء آخر، فتوقّفت البوابة المحلية عن التنبؤ بنتائج CI تحديدًا في الاختبارات الأصعب إعادةً للإنتاج. أصبح CI الآن يقسّم خطوة nextest بالطريقة نفسها، ووُسّع السقف على المشغّلات المشتركة، حيث يقلّ معنى القياس.","changelog.17a56bd3bbd4":"<strong>خطآن من clippy خاصّان بنظام تشغيل بعينه</strong> في <code>shell_actions/macos.rs</code> و<code>shell_actions/linux.rs</code>، وهما ملفان لا يُصرّفهما أي بناء على Windows، وقد بلغتهما بوابة الفحص (lint) الخاصة بـ <code>src-tauri</code> لأول مرة في هذه الجولة.","changelog.c205924de0fe":"التوثيق","changelog.9c50b38011d4":"كان <code>README.md</code> يعلن عن <code>v0.19.84</code> بوصفه الإصدار الأول المرتقب، بعد أربعة إصدارات من صدوره فعلًا، وكان يربط بخمسة مستندات ليست جزءًا من هذا المستودع.","changelog.4395f6d7c73f":"كانت أحجام التنزيل على الموقع هي أحجام <code>0.23.0</code>، منقولةً مع الروابط.","changelog.b2bfece1a5c5":"<span class=\"release__meta\"><span class=\"release__ver\">v0.23.1</span><time class=\"release__date\" datetime=\"2026-08-19\">2026-08-19</time></span><span class=\"release__title\">الأعمال التمهيدية للبناء 4 · إغلاق ما سُلّم من البناء 3</span>","changelog.957188896a81":"الأعمال التمهيدية للبناء 4 — إغلاق ما سُلّم من البناء 3","changelog.4dce861a35f4":"كل ما تركه التسليم السابق مفتوحًا بعد v0.23.0، إضافةً إلى ثلاثة أخطاء اكتُشفت أثناء العمل عليه. لا ميزات جديدة؛ هذه جولة التنظيف التي يقوم عليها عمل عدسة الخصائص في البناء 4.","changelog.116b07733767":"<strong>لم تكن قائمة <code>Search →</code> تفعل شيئًا.</strong> أرسل SRC-M23 أعلام أوضاع المطابقة السبعة كلها من <code>query.ts</code> وعلّم <code>QueryRunParams</code> في الخدمة الخلفية قراءتها جميعًا — لكن أمر Tauri الواقع بينهما لم يُعلن أيًّا منها، وTauri يُسقط بصمت وسائط الاستدعاء التي لا يسمّيها الأمر. فكان كل علم يصل إلى المنفّذ بقيمته الافتراضية في <code>serde</code>، وكان كلٌّ من «مطابقة حالة الأحرف» و«مطابقة الكلمة بالكامل» و«مطابقة المسار» و«مطابقة التشكيل» و«مطابقة صوتيات CJK» و«تجاهل علامات الترقيم» و«تجاهل المسافات» يحرّك علامة اختيار ولا يغيّر شيئًا آخر. أصبح في <code>commands/query.rs</code> الآن موضع استقبال هو <code>QuerySearchOpts</code>، ويثبّت <code>tests/unit/query_wire.test.ts</code> أسماء الوسائط على الجانبين.","changelog.3258356b0cdb":"<strong>كانت «مطابقة حالة الأحرف» خاطئة في الاتجاهين.</strong> عند تفعيلها، كان الاستعلام بأحرف كبيرة لا يُرجع <em>شيئًا</em>، بينما ظل الاستعلام بأحرف صغيرة يطابق دون مراعاة لحالة الأحرف. يخزّن فهرس الأسماء مفاتيح بأحرف صغيرة، فلم يكن لدى المرشّح المسبق للمرشّحين نص بحالة أحرفه الأصلية ليختبره، فكان يرفض كل صف قبل أن يتمكّن التحميل الكامل (hydration) من النظر في الاسم الحقيقي. كان هذا معروفًا ومؤجَّلًا — إذ كان اختبارٌ يؤكّد السلوك المعطوب ويحيل إلى تغيير في الفهرس مقرّر للمرحلة 13. لكنه لم يكن بحاجة إلى ذلك: أصبحت «مطابقة حالة الأحرف» تتخطّى المرشّح المسبق، تمامًا كما كانت تفعل «مطابقة المسار»، ويعمل الشرط على الاسم الحقيقي للصف. ولا تزال بذرة الثلاثيات مطبّقة، لأنها مبنية من نص البحث بأحرف صغيرة فتنتقي مجموعةً شاملة للإجابة الحسّاسة لحالة الأحرف، ما يعني أن الكلفة تحميل كامل للصفوف لا فحص شامل. ووُجّهت <code>child:</code> و<code>name^:</code> و<code>name$:</code> بالطريقة نفسها.","changelog.3fdb374f585c":"<strong>لم يكن أي إعداد يُحفظ.</strong> كان لـ <code>custom_commands</code> قيمة افتراضية ولوحة كاملة في الإعدادات ← أوامر مخصّصة، لكنه كان غائبًا عن <code>ALLOWED_PATCH_KEYS</code>. يرفض <code>settings_set</code> التعديل عند أول مفتاح علوي غير معروف فيه، و<code>flush()</code> في الواجهة يرسل الحالة كاملة — وهي تحتوي دائمًا على <code>custom_commands</code> — فكانت كل عملية حفظ تفشل وتنتهي بتحذير في وحدة التحكم. أصبحت قائمة السماح الآن مشتقّة من المخطط (<code>allowed_patch_keys()</code>)، وهكذا ظهرت هذه الثغرة.","changelog.be64658b8045":"<strong>كانت <code>child:</code> / <code>name^:</code> / <code>name$:</code> تُجيب إجابات مختلفة بحسب بقية الاستعلام.</strong> كانت مرحلة فهرس الأسماء تمرّرها عبر سلّم التطبيع الكامل بينما كانت مرحلة التحميل الكامل تقارن السلاسل الخام، والمرحلتان تعملان في كل استعلام — فكانت إضافة أي مُعدِّل يفرض التحميل الكامل تسلّم القرار إلى المرحلة الأكثر صرامة. كان <code>name^:cafe</code> وحده يعثر على <code>café-notes.txt</code>، ثم يتوقف عن العثور عليه بمجرد إضافة <code>size:</code>.","changelog.35d326e420f1":"<strong>لم يكن Escape يُغلق أي نافذة حوار.</strong> كان المعالج مثبّتًا على الخلفية، وهي عنصر div بـ <code>role=&quot;presentation&quot;</code> بلا tabindex، فلم يكن بإمكانه تلقّي حدث keydown — وكانت اللوحة توقف انتشار الحدث على أي حال. أصبح الآن على <code>window</code>، داخل <code>&lt;Modal&gt;</code> المشترك.","changelog.4f4a3883a9bb":"<strong>كان الترتيب الطبيعي على جانب العميل فقط.</strong> كانت القيمة الافتراضية لـ <code>SortSpec.natural</code> هي <code>true</code> ولم يكن أي شيء يضبطها، فكان إيقاف الإعدادات ← النتائج ← <em>ترتيب طبيعي</em> يعطّل دالة المقارنة في الواجهة فقط ويترك <code>freally search --json</code> مرتّبًا ترتيبًا طبيعيًا في كل الأحوال. أصبح الإعداد الآن يعبر قناة الاتصال.","changelog.1eb006c07967":"<strong>لم يكن <code>src-tauri</code> يخضع للفحص (lint).</strong> إنه مستبعَد من مساحة العمل، فلم يكن <code>cargo clippy --workspace</code> يراه أبدًا، وكانت ثلاثة أخطاء تفشل بصمت. أصبح لـ CI الآن خطوة خاصة بهذا البيان (manifest). وحُذف الأمر الميت <code>log_event</code> — الذي كان موثّقًا بوصفه جسر التصحيح TS→Rust لكنه لم يُسجَّل قط، فكان أي استدعاء له يفشل.","changelog.17d4993eb122":"<strong>أصبحت الأوامر المخصّصة محدودة ومفحوصة البنية.</strong> <code>custom_commands</code> هو الإعداد الوحيد الذي تسمّي قيمته <em>برنامجًا يُشغَّل</em>، وكان يصل إلى <code>settings_set</code> دون أي تحقق على الإطلاق — لأنه حتى هذا البناء لم يكن يصل إلى <code>settings_set</code> أصلًا (انظر أعلاه). أصبحت له الآن الحدود نفسها التي لكل حقل آخر غير محدود — على عدد الأوامر، وعلى طول <code>id</code>/<code>name</code>/<code>program</code>، وعلى قائمتي السلاسل كلتيهما، <code>args</code> و<code>extensions</code>.","changelog.efc94af8b3c4":"<strong>لم يعد استيراد ملف إعدادات يثبّت مُشغِّلات بصمت.</strong> يقرأ الإعدادات ← النسخ الاحتياطي ← <em>استيراد الإعدادات</em> ملف JSON يقدّمه المستخدم مباشرةً إلى مخزن الإعدادات. لذا كان بإمكان «إعداد Freally مسبق» متداول أن يضيف أمرًا مخصّصًا — برنامجًا يُشغَّل — إلى قائمة السياق لكل نتيجة، تحت تسمية اختارها مؤلفه، دون أي تنبيه. أصبح الاستيراد الآن يسمّي البرامج ويسأل؛ والرفض يستورد كل ما عداها. ويذكر <code>docs/SECURITY.md</code> الحدّ المتبقي بوضوح: أي شيء يستطيع كتابة الإعدادات يستطيع تسمية برنامج.","changelog.442aded87a55":"الأداء","changelog.ee0c64c3999a":"<strong>لم يعد «تجاهل علامات الترقيم» / «تجاهل المسافات» يفحصان الفهرس فحصًا شاملًا.</strong> يعيد هذان الوضعان كتابة النص قبل المقارنة، فتتوقف ثلاثيات الاسم الخام عن وصف نص البحث، فيلجأ المنفّذ إلى المرور على كل اسم. أصبح الآن يستمدّ بذرته من مجموعة موازية من قوائم الإحالة (postings) مبنية على أسماء مجرّدة من علامات الترقيم والمسافات. تُبنى بشكل كسول عند أول استخدام ثم تُصان تدريجيًا بعد ذلك، فلا يدفع ثمنها مستخدم لا يفعّل أيًّا من الوضعين أبدًا.","changelog.2bfd60f4ad05":"<strong>سلّم تطبيع واحد بدلًا من ثلاثة.</strong> كانت كلٌّ من <code>substring_match</code> و<code>anchored_match</code> و<code>literal_match</code> تمرّ بمراحل طيّ حالة الأحرف ← إزالة التشكيل ← إزالة المُتجاهَل، وكانت قد تباعدت بالفعل. أصبحت الآن تتشارك <code>normalized</code>، التي تستعير بدلًا من أن تخصّص عندما لا يكون لدى إحدى الدرجات ما تفعله — فالحالة الشائعة، أي اسم ASCII بأحرف صغيرة في الوضع الافتراضي، لم تعد تخصّص أي شيء لكل صف.","changelog.40253ba25a46":"<strong>يُطبَّع نص البحث مرة واحدة لكل استعلام، لا مرة لكل صف مرشّح.</strong>","changelog.23f1c76bd888":"أصبح توزيع الشكل الموجي على الدلاء يحمل حدّ الدلو بدلًا من القسمة لكل إطار مفكوك (~8 M عملية قسمة على مقطع ستيريو مدته ثلاث دقائق)؛ وأصبح دفتر الأذونات يزيل التكرار عبر <code>HashSet</code> بدلًا من الفحص الخطّي؛ وتوقّف تسجيل عملية بحث حديثة عن نشر جذر الإعدادات ذي المفاتيح الـ ~180 وإعادة تعيينه مع كل ضغطة مفتاح.","changelog.64ff3a4bbdfd":"<strong>أُزيل Freally Central</strong> — الشجرة المضمّنة في المستودع (vendored)، ومقطع <code>.gitmodules</code> الذي يسمّي وحدة فرعية لم يسجّلها git قط، وجزيرة React واعتمادياتها الخمس، ونافذة الحوار <em>المزيد من تطبيقات Freally</em> وعنصر القائمة الخاص بها، وسلاسلها المترجمة، ومُدخلاتها في موقع التوثيق.","changelog.36e12a600874":"<strong><code>&lt;Modal&gt;</code> مشترك</strong> يحلّ محلّ رقصة الخلفية / اللوحة / Escape / <code>tabindex</code> التي أعادت كتابتها سبع نوافذ حوار كلٌّ على حدة، ويزيل التحذيرات الستة المعلّقة كلها من نوع <code>a11y_interactive_supports_focus</code>. تحتفظ <code>HitViewer</code> و<code>QuickLook</code> و<code>RegexBuilder</code> ومعالج التشغيل الأول بأطرها الخاصة عمدًا — فالخلفية الشقيقة، والتنقّل بمفاتيح الأسهم، والنافذة المنبثقة، والبوابة غير القابلة للصرف ليست المكوّن نفسه.","changelog.05849c3f2c94":"تحلّ <code>portable::open_log</code> و<code>service::scan</code> و<code>app_data_root</code> و<code>resultsStore.hitById</code> محلّ نسخها المكرّرة.","changelog.fe8ee15bb86d":"التكامل المستمر (CI)","changelog.44ad89dc0cf1":"يحلّ <code>cargo nextest</code> محلّ <code>cargo test</code>: فمعظم الاختبارات الـ 760 تبني فهرس Tantivy خاصًا بها، وتخصيص عملية لكل اختبار يُبعد بعضها عن أقفال بعض. بالقياس على جهاز التطوير مع ذاكرة مؤقتة دافئة: من 100s إلى 37s.","changelog.2892b412468b":"تحدّ مجموعة اختبارات في nextest الحزمَ التي تبني الفهارس بأربع عمليات متزامنة. فبدونها، حوّل التزامن الإضافي حالة السباق المعروفة بين Windows Defender وTantivy <code>Access is denied (os error 5)</code> من عارضة إلى قابلة لإعادة الإنتاج — إذ فشل تشغيلان متتاليان في ثلاثة اختبارات مختلفة. يكلّف هذا الحدّ ~2s، ولا تزال المجموعة تعمل في خُمس الوقت الذي يستغرقه <code>cargo test</code>.","changelog.f600da3213ca":"تُلغى عمليات التشغيل على الفرع التي حلّت محلّها عمليات أحدث؛ ويُستثنى <code>main</code> كي يواصل تعبئة الذاكرة المؤقتة التي تستعيد منها كل الفروع.","changelog.6811b6eaa5cb":"<code>CARGO_INCREMENTAL=0</code>، وذاكرة مؤقتة لا تُكتب إلا من <code>main</code>، و<code>--locked</code> في كل مكان، وتثبيت pnpm مُجمَّد، والبوابات المستقلة عن نظام التشغيل (<code>i18n-lint</code>، واختبارات التوثيق doctests) على مشغّل واحد بدلًا من ثلاثة.","changelog.8266aee5f502":"اكتسب <code>scripts/ci-local.mjs</code> بوابة <code>src-tauri</code> التي كانت تنقصه، وأصبح يشغّل مساري Rust والواجهة بالتزامن: 133s من العمل في 89s.","changelog.b9b12625c2fd":"<span class=\"release__meta\"><span class=\"release__ver\">v0.23.0</span><time class=\"release__date\" datetime=\"2026-08-03\">2026-08-03</time></span><span class=\"release__title\">البناء 3 · بوابة الاستقرار للميزات الأساسية (Must-Have)، الشريحة 3 من 3</span>","changelog.c5819508ac2c":"آخر عمليات البناء الثلاث للميزات الأساسية: SRC-M17 … SRC-M24. يصدر بوصفه v0.23.0، وهو الوسم <strong>المستقر</strong>.","changelog.7c2c8aacfd91":"<strong>SRC-M17 — الوضع المحمول.</strong> يُبقي <code>freally --portable</code>، أو ملف <code>portable.flag</code> فارغ بجوار الملف التنفيذي، الفهرسَ والإعدادات والإشارات المرجعية ومؤشرات سجل التغييرات والسجلات في مجلد <code>Data/</code> بجوار الملف التنفيذي، ويمنع التطبيق من تسجيل أي شيء لدى نظام التشغيل. تقبل الملفات التنفيذية الثلاثة هذا المفتاح؛ وملف العلم هو ما يجعل أرشيف zip أو AppImage يُشغَّل بنقرة مزدوجة محمولًا دون أي سطر أوامر على الإطلاق.","changelog.c081711c3fde":"يوجد هذا التخطيط في <code>freally_rpc::portable</code> — الحزمة الوحيدة التي يعتمد عليها بالفعل كلٌّ من غلاف Tauri والخدمة الخلفية وواجهة سطر الأوامر (CLI).","changelog.260a841f6090":"ما <em>لا</em> يفعله الوضع المحمول عمدًا، ولكلٍّ منها سبب ملموس لا مجرد الترتيب:","changelog.e53f7037be43":"<strong>لا خدمة، ولا ملف launchd plist، ولا وحدة systemd.</strong> ترفض <code>freally-indexd install</code> / <code>uninstall</code> / <code>service</code> كلها العمل في الوضع المحمول. فكلٌّ منها يكتب تسجيلًا يبقى بعد نزع وحدة USB ويشير إلى مسار لن يكون موجودًا عند الإقلاع التالي. ويُرفض <code>uninstall</code> للسبب المعاكس: فالنسخة المحمولة لم تسجّل أي شيء قط، والسماح به سيلغي تسجيل النسخة <em>المثبّتة</em> على الجهاز المضيف.","changelog.d1f534b3e627":"<strong>لا تسجيل لمخطط <code>freally://</code>.</strong> فهو يكتب معالجًا على مستوى الجهاز يشير إلى المسار الحالي للملف التنفيذي؛ انزع وحدة USB فيصبح كل رابط <code>freally://</code> على ذلك الجهاز معلّقًا بلا وجهة. لا يزال المستمع داخل العملية يعمل، فتعالج النسخة المحمولة عناوين URL التي تُسلَّم إليها — لكنها لا تطالب بالمخطط فحسب.","changelog.6320d3fbbef5":"<strong>لا تحديث تلقائي.</strong> تطبّق أداة التحديث <em>مثبّتًا</em>. وتوجيهها إلى وحدة USB سيثبّت التطبيق على الجهاز المضيف، وهذا تحديدًا ما يتجنّبه مستخدم الوضع المحمول. تُحدَّث النسخ المحمولة باستبدال المجلد.","changelog.01ed92501ea3":"<strong>لا تبنّي لخدمة Windows.</strong> تملك الخدمة الفهرس المثبّت تحت <code>%PROGRAMDATA%</code>؛ والتشغيل المحمول الذي يتصل بها سيبحث بصمت في فهرس الجهاز المضيف ويكتب نشاط وحدة USB فيه.","changelog.9f519044c9bf":"<strong>لا <code>taskkill</code> عابر للنسخ.</strong> يُنهي فرض النسخة الواحدة العملياتِ حسب اسم الصورة. فوحدة USB موصولة بجهاز يشغّل Freally أصلًا كانت ستُسقط التطبيق الذي يستخدمه المستخدم في تلك اللحظة.","changelog.f0f408322071":"احتاج جزآن من الحالة إلى إعادة توجيه صريحة لأنهما لا يتفرّعان من جذر الفهرس:","changelog.ada349238a7a":"<strong>مؤشرات سجل التغييرات.</strong> يستخدم كل مشترك في نظام التشغيل افتراضيًا مجلده الخاص لكل مستخدم، فكانت النسخة المحمولة ستترك مؤشرات خلفها على كل جهاز توصَل به. أصبحت الآن تُكتب في <code>Data/cursors</code>.","changelog.8ea42f81060c":"<strong>مقبس RPC، الذي يبقى عمدًا خارج وحدة USB.</strong> تكون وحدة USB عادةً بنظام FAT32 أو exFAT — وهي أنظمة ملفات لا يمكنها احتواء مقبس نطاق Unix على الإطلاق، ولا تملك بتّات أذونات للفحص 0600 + uid الطرف المقابل الذي تعتمد عليه طبقة النقل. يوجد المقبس في المجلد المؤقت للجهاز المضيف باسم مشتقّ من الجذر المحمول، فلا تتصادم نسخة محمولة أبدًا مع نسخة مثبّتة أو مع وحدة USB ثانية، وتبقى آلية المصادقة دون تغيير.","changelog.f576d6d3c2e0":"تنتقل السجلات لأن الملف التنفيذي الذي يُشغَّل بنقرة مزدوجة لا يملك وحدة تحكم يرثها: تكتب العمليتان كلتاهما في <code>Data/logs/</code>، وتعودان إلى وحدة التحكم إن تعذّر فتح ذلك الملف بدلًا من فقدان التشخيصات التي كانت ستشرح السبب.","changelog.2af97df221d3":"على macOS يوضع <code>Data/</code> بجوار <code>Freally.app</code> لا داخله — فكتابة بيانات المستخدم داخل الحزمة تكسر توقيع الشيفرة وتفشل تمامًا على نقطة تركيب للقراءة فقط.","changelog.8b231cae5059":"<strong>وفي هذا التغيير أيضًا: كانت لوحة «حول» تُبلغ عن إصدار خاطئ.</strong> كانت تحمل القيمة المثبّتة في الشيفرة <code>0.19.84</code> وقد تأخّرت ثلاثة إصدارات عمّا صدر فعلًا. أصبحت الآن تقرأ الإصدار من العملية الجارية عبر أمر جديد هو <code>app_environment</code>، الذي يُبلغ أيضًا عمّا إذا كان هذا تثبيتًا محمولًا وعن المجلد الذي يكتب إليه — فيستطيع المستخدم الذي يصل وحدة USB بجهاز شخص آخر أن يتأكد من داخل التطبيق أن لا شيء يُكتب على الجهاز المضيف.","changelog.9ee660246eb6":"اختبار الدخان: يجهّز <code>tests/smoke/build_03_portable.rs</code> نسخة من الملف التنفيذي الحقيقي للخدمة الخلفية في مجلد مؤقت (فالوضع المحمول مُعرَّف نسبةً إلى الملف التنفيذي، واختباره في مكانه سيجعل كل ملف تنفيذي آخر في مساحة العمل محمولًا لبقية التشغيل)، ويُثبت عمل ملف العلم، والمفتاح، وحالات رفض التسجيل الثلاث، وأن الخدمة الخلفية المحمولة تكتب فهرسها وسجلها في <code>Data/</code> ولا مكان آخر.","changelog.b20d6ec3f044":"<strong>SRC-M24 — الترتيب الطبيعي.</strong> تُقرأ سلاسل الأرقام داخل الاسم كأعداد، فيأتي <code>file2</code> قبل <code>file10</code> و<code>v1.9</code> قبل <code>v1.10</code>. مفعّل افتراضيًا، مع إمكانية إيقافه من الإعدادات ← النتائج ← <em>ترتيب طبيعي</em>.","changelog.88d62d00604a":"ينطبق على كل عمود نصي — الاسم والمسار والنوع والامتداد — لا على الاسم وحده، فلا تعني عبارة «رتّب ترتيبًا طبيعيًا» ضمنًا «رتّب عمود الاسم ترتيبًا طبيعيًا».","changelog.52f34cd037df":"هناك دالتا مقارنة لأن هناك عمليتي ترتيب: الخدمة الخلفية ترتّب ما تُرجعه (<code>crates/freally-query/src/natural.rs</code>)، وقائمة النتائج تعيد الترتيب على جانب العميل (<code>apps/freally-ui/src/lib/util/natural.ts</code>). وهما ليستا متطابقتين عمدًا — فالواجهة تمرّر المقاطع غير الرقمية عبر <code>localeCompare</code> كي تواصل علامات التشكيل وحالة الأحرف السلوك الذي كانت عليه، بينما لا ترى الخدمة الخلفية إلا اسمًا بأحرف صغيرة — لذا تثبّت مجموعة حالات مشتركة السلوكَ الرقمي الذي يجب أن تتفقا عليه، ويُتحقق منها من الجانبين.","changelog.4ac049addd1f":"تفاصيل تستحق الذكر، لأن كلًّا منها طريقة للوقوع في الخطأ:","changelog.7548bb140901":"<strong>تُقارَن سلاسل الأرقام دون تحليلها إلى أعداد.</strong> فالتحليل محدود بـ <code>u64</code> (أو 2^53 في JS)؛ وسلسلة من 30 رقمًا في اسم ملف أمر غير مألوف لكنه ليس غير صالح، وعندها ستتساوى في المقارنة سلسلتان طويلتان مختلفتان. أما مقارنة عدد الأرقام المعنوية ثم الأرقام نفسها فدقيقة مهما بلغ الطول.","changelog.b4e5975dde5b":"<strong>الحشو بالأصفار هو الملاذ الأخير لفضّ التعادل.</strong> <code>file07</code> و<code>file7</code> يمثّلان العدد نفسه، لذا لا يحسم الحشو إلا حين لا يحسم شيء آخر — فالحسم به لحظة ظهوره سيجعل <code>file07b</code> يسبق <code>file7a</code>.","changelog.b682aa249886":"<strong>تقارن الواجهة المقطع غير الرقمي فقط بقدر ما يملكه الجانبان كلاهما.</strong> فقد ينقطع المقطع برقم في جانب دون الآخر — مقارنة <code>img.png</code> بـ <code>img1.png</code> تعطي مقطعين طولهما 7 و3 — ومقارنتهما كاملين تحسم بالطول بدلًا من <code>.</code> مقابل <code>1</code>، ما كان يضع <code>img.png</code> في آخر الترتيب. كشفته مجموعة الحالات المشتركة.","changelog.efabda690420":"<strong>لا تزال السلاسل الخالية من الأرقام تمرّ عبر <code>localeCompare</code> كاملة</strong>، فتحتفظ الحالة الشائعة بالضبط بقواعد الترتيب التي كانت لها.","changelog.e3d8b9588796":"<strong>عمود المسار هو الموضع الوحيد الذي يغيّر فيه المفتاح أكثر من الأرقام.</strong> عند إيقاف الترتيب الطبيعي يبقى <code>PathBuf::cmp</code>، الذي يرتّب حسب المكوّنات لا حسب البايتات؛ أما الترتيب الطبيعي فعليه قراءة المسار كنص كي يرى سلاسل الأرقام أصلًا.","changelog.52750ba0909a":"<strong>لا تزال الملفات بلا امتداد تأتي أولًا في الترتيب</strong>، كما كان يفعل <code>Option::cmp</code>.","changelog.67df3bc8e4ae":"يطلب سطر الميزة أن «تحترم فهارسُ الترتيب السريع» هذا الترتيب. لكن لا توجد فهارس كهذه لتحترمه: فالترتيب يحدث في <code>sort_rows</code> على الصفوف المرشّحة التي جسّدها المنفّذ بالفعل، ولا يوجد اليوم في المخزن أي فهرس لتسريع الترتيب. وبناء واحد منها عمل بحجم بنود SRC-N، لذا يُذكر هذا صراحةً بدلًا من تخطّيه بصمت.","changelog.bd0993897678":"اختبار الدخان: يفهرس <code>tests/smoke/build_03_natural_sort.rs</code> أسماءً يختلف فيها ترتيب البايتات عن الترتيب الطبيعي في كل إدخال، ويثبّت القيمة الافتراضية، وخيار الإيقاف، والترتيب التنازلي، وعمود المسار، وأن العمود الرقمي يُترك على حاله.","changelog.b190e0af1450":"<strong>SRC-M23 — تجاهل علامات الترقيم، وتجاهل المسافات، والمطابقة المُرسّاة.</strong> مفتاحا تبديل جديدان تحت <code>Search →</code> (<code>Ignore Punctuation</code>، <code>Ignore Whitespace</code>) ومُعدِّلان جديدان في لغة الاستعلام، <code>name^:report</code> (يبدأ بـ) و<code>name$:final</code> (ينتهي بـ).","changelog.e35e30b09372":"<strong>أصبحت مفاتيح المطابقة الأربعة الموجودة تفعل شيئًا حقًا.</strong> حتى البناء 2، لم يكن يعبر قناة الاتصال إلا <code>match_phonetic</code>: كانت <code>Match Case</code> و<code>Match Whole Word</code> و<code>Match Path</code> و<code>Match Diacritics</code> تحرّك علامة اختيار ولا تغيّر شيئًا، لأن <code>query.run</code> كان يرسل ذلك العلم الوحيد فقط وكانت الخدمة الخلفية تبني <code>MatchMode</code> من <code>Default</code>. وكان المنفّذ يحترم الخمسة كلها طوال الوقت. أصبحت المجموعة الكاملة تُرسل وتُقرأ الآن.","changelog.827fa9647b52":"<strong>خلل ذو صلة اكتُشف أثناء التوصيل: لم يكن <code>Match CJK Phonetics</code> يُحفظ أبدًا.</strong> يعيد <code>settings_set</code> تسلسل بنية الإعدادات ثم يحلّل النتيجة من جديد، ولم يكن في <code>SearchOpts</code> في Rust حقل <code>match_phonetic</code> — فكان العلم يسقط مع <em>كل كتابة للإعدادات</em>. أضافه البناء 2 إلى جانب TypeScript فقط. أصبحت الأعلام الثلاثة الجديدة كلها في بنية Rust أيضًا.","changelog.32c9128fe95e":"ملاحظات التنفيذ:","changelog.c4202016a76a":"<strong>يُجرَّد الجانبان كلاهما، لا الهدف وحده.</strong> فتجريد الاسم وحده سيجعل <code>foobar</code> يعثر على <code>foo-bar</code> بينما لا يستطيع <code>foo-bar</code> العثور على <code>foobar</code> — وهذا يبدو خللًا لا وضع مطابقة.","changelog.09e51f90e5b3":"<strong>تُسقَط بذرة الثلاثيات عندما يعيد وضعٌ ما كتابة النص.</strong> يفهرس <code>foo-bar</code> الثلاثيات <code>foo</code> و<code>oo-</code> و<code>o-b</code> و<code>-ba</code> و<code>bar</code>؛ أما نص البحث <code>foobar</code> فيطلب <code>oob</code> و<code>oba</code>، وهما غير موجودتين في ذلك الصف، فكان البذر سيُرجع <em>لا شيء على الإطلاق</em>، بصمت. يعود المنفّذ إلى الفحص الشامل، وهي المقايضة نفسها التي يقوم بها <code>match_path</code> أصلًا. والأعلام معطّلة افتراضيًا، فلا يدفع أحد الثمن دون أن يطلب.","changelog.24e406c88eff":"<strong>يُتجاهَل خيار الكلمة بالكامل ما دام أحد وضعي التجريد مفعّلًا</strong>، لأن إزالة الفواصل تزيل حدود الكلمات التي تعرّفه.","changelog.c0189eb66ffc":"<strong>يتصرّف <code>name:foo-bar</code> مثل المصطلح المجرّد <code>foo-bar</code>.</strong> فهما الاستعلام نفسه مكتوبًا بطريقتين، لذا يحترم مسار <code>name:</code>/<code>child:</code> وضعي التجريد أيضًا، لا مسار المصطلح الحرفي وحده.","changelog.5d357f0cb708":"<strong>علامات الترقيم هي ما يعرّفه Unicode، لا قائمة ASCII</strong>، لذا تُسقَط <code>’</code> و<code>–</code> إلى جانب <code>'</code> و<code>-</code>.","changelog.8b12742c48b5":"بالنسبة إلى المُعدِّلات المُرسّاة، يُسمح بـ <code>^</code> و<code>$</code> لمفتاحين بعينهما فقط بدلًا من إضافتهما إلى مجموعة أحرف المفاتيح العامة — وهي الآلية نفسها التي تستخدمها المفاتيح الموصولة بشرطة، وللسبب نفسه المتعلق بالقاعدة الدائمة #8: فتوسيع مجموعة الأحرف سيحوّل <code>x^2:3</code> و<code>total$:5</code> من مصطلحات حرفية إلى أخطاء تحليل صريحة. ويُرفض كلاهما تحت <code>--strict-everything</code>، إذ لا يملك Everything من voidtools صيغة مُرسّاة. يرسو <code>name$:</code> على الاسم الكامل بما فيه الامتداد، لذا لا يطابق <code>name$:report</code> الملف <code>report.txt</code>.","changelog.573c5bc71314":"تسجيل مُعدِّل جديد يمسّ أكثر من المحلّل، وإغفال أيٍّ من المواضع يتركه يعمل نصف عمل: متغيّر AST، وأربعة مواضع للمخطِّط/المقيِّم في <code>exec.rs</code>، و<code>optimizer::selectivity_rank</code> (فالمطابقة المُرسّاة أضيق من السلسلة الفرعية التي تتضمنها، لذا تتقدّم على <code>child:</code> في الترتيب)، وقائمة الوضع الصارم في <em>موضعين</em>، ومجموعة أحرف المفاتيح المكرّرة في <code>report.rs</code> — أغفِل هذه فيعمل الاستعلام بشكل صحيح بينما يلوّنه شريط البحث كنص حرفي — إضافةً إلى <code>modifier_name</code> و<code>ModifierDetail</code> وجدول <code>MODIFIER_KEYS</code> المُعلَن الذي تقرؤه إكمالات CLI.","changelog.5b298995d56c":"وكان في الأخير ثغرة جديرة بالملاحظة: ما كان <code>every_advertised_modifier_is_known_to_the_parser</code> ليكشف مفتاحًا ذا رمز (sigil) مفقودًا، لأن المفتاح الواقع خارج مجموعة الأحرف يتدهور إلى <em>نص حرفي</em> لا إلى <code>UnknownModifier</code>، فينجح الاختبار في الحالتين. أُضيف تأكيد إيجابي.","changelog.7cd3e842fd15":"<strong>SRC-M20 — منشئ التعابير النمطية ومختبِرها الحي.</strong> نافذة منبثقة بجوار مفتاح جديد للتعابير النمطية في شريط البحث: حقل للنمط، وخطأ التصريف الصادر عن المحرّك نفسه، وورقة مرجعية بصياغة Rust، وإبراز حيّ لما يطابقه النمط عبر أسماء أول 50 نتيجة حالية، مع عدّاد من قبيل «يطابق 3 من 50». يؤدي اعتماد النمط إلى إعادة كتابة الاستعلام بصيغة <code>regex:&lt;pattern&gt;</code> وتفعيل «تفعيل التعبير النمطي»، فلا تخالف القائمة أبدًا ما يفعله الاستعلام.","changelog.fc32c438e9b3":"كانت شارة خطأ التحليل وتلميح AST عند التمرير يتحققان بالفعل من استعلام <em>كتبته</em>؛ لكن لا شيء كان يساعدك على كتابة النمط. وهنا يضيع الوقت — تكتب شيئًا، وتشغّله، فلا تحصل على شيء، ولا تستطيع أن تعرف هل النمط خاطئ أم أن الملفات غير موجودة ببساطة. تعرض النافذة المنبثقة الإجابتين معًا.","changelog.8f5e99706420":"<strong>يجري الاختبار في Rust عن قصد.</strong> التنفيذ البديهي يتحقق مقابل <code>RegExp</code> الخاص بالـ webview، وسيكون خاطئًا تحديدًا في الحالات التي يصادفها من يصوغ نمطًا: فمنفّذ الاستعلامات يشغّل حزمة <code>regex</code>، التي لا تدعم المراجع الخلفية ولا النظر الأمامي أو الخلفي، وتعامل <code>\\d</code> بوعي لـ Unicode، وتأخذ <code>(?i)</code> ضمن النمط لا كعلم لاحق. والمنشئ المعتمد على <code>RegExp</code> يقبل <code>(?&lt;=foo)bar</code> بكل سرور ثم يفشل عند تشغيل الاستعلام. أما <code>regex_test</code> فيصرّف بالمحرّك نفسه، فتعني «يطابق هنا» أنه «سيطابق هناك» — وهناك اختبار وحدة يؤكّد رفض النظر الأمامي/الخلفي، لهذا السبب بالذات.","changelog.6e60e7b42f67":"قرارات أصغر، كلٌّ منها يحمي شيئًا حقيقيًا: تُعاد المقاطع كإزاحات بـ<strong>الأحرف</strong>، لأن الواجهة تقتطعها بفهارس سلاسل JavaScript، والإزاحة بالبايتات ستشطر اسمًا متعدد البايتات إلى نصفين؛ وتُسقَط المطابقات ذات العرض الصفري، لأن <code>a*</code> يطابق في كل موضع، وإبراز لا شيء في كل موضع مجرد ضجيج؛ ولا يُبلغ النمط الفارغ عن أي خطأ بدلًا من إظهار خطأ عند أول ضغطة مفتاح؛ ويُثبَّت حدّ حجم الآلة المصرَّفة عند 256 KB بدلًا من القيمة الافتراضية للحزمة البالغة 10 MB. المحرّك قائم على الآلات المنتهية (finite automata)، فلا يستطيع نمط عدائي أن يتراجع تراجعًا أُسّيًا — وحدّ الحجم هو الرافعة الوحيدة المهمة، وقد ضُبط.","changelog.11270a28687b":"<strong>SRC-M19 — «نظرة سريعة» بمفتاح المسافة.</strong> يفتح الضغط على المسافة فوق نتيجةٍ معاينةً كبيرة في نافذة مشروطة؛ وتتنقّل مفاتيح الأسهم بين النتائج وهي لا تزال مفتوحة، وتُغلقها المسافة أو Escape. يعرض الرأس «7 من 50» لتعرف موقعك في المجموعة.","changelog.d3e1342a48af":"إنها ليست تنفيذًا ثانيًا للمعاينة — فهي تستدعي <code>files_preview</code> نفسه الذي يستدعيه الجزء المثبّت، فأي صيغة تُعرض في أحدهما تُعرض في الآخر. ما تضيفه هو الحجم وتدفّق العمل بلوحة المفاتيح: الجزء المثبّت لوحة تلقي عليها نظرة، وهذه هي إيماءة «ما <em>هو</em> هذا الملف؟»، والمقصود أن يديك لا تغادران لوحة المفاتيح أبدًا.","changelog.273a049cb91a":"<strong>تُعالَج المسافة في رابط المفاتيح العام، لا في المكوّن</strong>، وهي الحالة الحسّاسة: فالمسافة حرف أيضًا، لذا تُتجاهل كلما كان مؤشر الكتابة داخل input أو textarea أو select أو عنصر contenteditable. والخطأ في ذلك يعني أن مربع البحث يتوقف عن قبول المسافات — وهو خلل أسوأ بكثير من اختصار مفقود.","changelog.ca26390b3e56":"يتبع التنقّل الترتيب الذي <em>تُعرض</em> به القائمة فعلًا (الدفعات بترتيب العدسات، مع تطبيق مخزن الترتيب داخل كلٍّ منها، باستثناء دفعات مجموعات التكرار حيث رتّبت الخدمة الخلفية الصفوف بالفعل وإعادة الترتيب ستفكّك المجموعات). واتباع أي ترتيب آخر يجعل مفاتيح الأسهم تبدو كأنها تقفز عشوائيًا. يتوقف التنقّل عند الطرفين بدلًا من الالتفاف، لأن الالتفاف من الصف الأخير إلى الأول يبدو خللًا عند إبقاء المفتاح مضغوطًا، ويستبدل التحديد بدلًا من توسيعه.","changelog.f6f10923fe43":"<strong>انحراف عن سطر الميزة، مُعلَن لا مُموَّه.</strong> يطلب السطر QuickLook الأصلي على macOS ومضيف Freally الخاص في غيره. لكن <code>qlmanage -p</code> يفتح <em>نافذة مستقلة لنظام التشغيل</em> لا تستطيع معالجة المفاتيح في Freally التحكم بها، فجعله الخيار الافتراضي على macOS سيكسر تدفّق مفاتيح الأسهم الذي هو جوهر الميزة كلها. لذلك فالنافذة المشروطة داخل التطبيق هي الواجهة على المنصّات الثلاث — وهذا أيضًا ما يجعل السلوك قابلًا للاختبار ومتطابقًا في كل مكان — ويحصل macOS إضافةً إلى ذلك على زر صريح «افتح في نظرة سريعة من macOS» للصيغ التي يستطيع النظام عرضها ولا يستطيع مضيف المعاينة في Freally عرضها. يمرّ المسار عبر بوابة <code>KnownPaths</code> نفسها التي يمرّ بها كل أمر ملفات آخر، ويُمرَّر كوسيط لـ <code>Command</code>، لا عبر صدفة (shell) أبدًا.","changelog.6fba87d13646":"<strong>SRC-M22 — شريط جانبي للإشارات المرجعية وعوامل التصفية.</strong> عمود أيسر اختياري (عرض ← الشريط الجانبي، معطّل افتراضيًا) من أربعة أقسام: الإشارات المرجعية مع إعادة الترتيب بالسحب، وعوامل تصفية الأنواع السبعة، ووحدات التخزين المفهرسة، وعمليات البحث الأخيرة. كانت الأربعة كلها موجودة أصلًا خلف ثلاث قوائم منسدلة مختلفة وقائمة، فكان تحديد نطاق البحث يعني معرفة أيّ الأماكن الأربعة تبحث فيه؛ وهذا يضعها في عمود واحد من العُقد القابلة للنقر.","changelog.2af93b3b0eaf":"<strong>احتاجت «عمليات البحث الأخيرة» إلى ابتكار، لأن البحث هنا حيّ.</strong> يُطلَق <code>run()</code> مع كل ضغطة مفتاح، فتسجيل كل تشغيل حرفيًا سيُنتج <code>r</code> و<code>re</code> و<code>rep</code> و<code>repo</code> و<code>repor</code> و<code>report</code> ويدفن الإدخال الوحيد الذي يريده أي أحد. قاعدتان تحلّان ذلك دون إيماءة اعتماد صريحة لا تملكها الواجهة: الاستعلام الجديد يطرد أي إدخال موجود يكون بادئةً له (ضغطات المفاتيح في الطريق إليه)، والاستعلام الذي يكون هو نفسه بادئةً لأحدث إدخال لا يُسجَّل (فهذا حذف بمفتاح Backspace). كتابة «report» ثم «invoice» تترك بالضبط <code>[&quot;invoice&quot;, &quot;report&quot;]</code>.","changelog.97fe3ffe9b63":"تحترم القائمة <strong>وضع الخصوصية ومفتاح سجل البحث</strong> — فكلاهما يعني أصلًا «لا تحتفظ بسجل لما بحثت عنه»، وقسم الشريط الجانبي هو بالضبط سجل كهذا، لذا لا يحتفظ بنسخته الخاصة خفيةً.","changelog.736397e92eea":"يُخزَّن ترتيب السحب كقائمة من معرّفات الإشارات المرجعية في الإعدادات بدلًا من سجلات الإشارات المرجعية نفسها، فلا تحتاج إعادة الترتيب إلى مسار كتابة جديد عبر IPC الخاص بالإشارات المرجعية. تُتجاهل معرّفات الإشارات المحذوفة بدلًا من ترك فجوة، وتُلحق الإشارة المرجعية المضافة منذ آخر سحب بنهاية القائمة بدلًا من إسقاطها.","changelog.bb58e9012e27":"تُصدر عُقد وحدات التخزين <code>volume:&quot;&lt;label&gt;&quot;</code> <strong>بين علامتي اقتباس</strong>، لأن التسمية كثيرًا ما تحتوي على مسافات (<code>Orange WD 4TB</code>)، ودون اقتباس ستُحلَّل كمصطلحين.","changelog.3ce317440cef":"يُعرض الشريط الجانبي داخل <code>.result-area</code>، متشاركًا صف flex واحدًا مع قائمة النتائج وجزء المعاينة، فلا يُخلّ تبديله بإطار القائمة / البحث / الحالة أعلاه وأسفله.","changelog.d5f690fcafa4":"<strong>تكرار اكتُشف أثناء توصيل هذا</strong>، يستحق التسجيل لأنه كان خاطئًا أصلًا: كان التنقّل في «نظرة سريعة» المضاف في SRC-M19 يمرّ على <code>resultsStore.batches</code> مباشرةً. تُخزَّن الدفعات بترتيب <em>وصولها</em> وتحمل نتائج من عدسات أوقفها المستخدم وصفوفًا استبعدها التضييق — بينما تُعرض القائمة عبر <code>viewForLens</code> بترتيب ثابت للعدسات. وكان <code>resultsStore.visibleHits</code> موجودًا بالفعل ويفعل ذلك بشكل صحيح. أصبح مساعد التنقّل الآن مبنيًا على <code>viewForLens</code> نفسه، فتمرّ مفاتيح الأسهم على ما يظهر على الشاشة لا على ما صادف أن أرسلته الخدمة الخلفية أولًا.","changelog.357a743ccb54":"<strong>SRC-M21 — تقرير حالة الأذونات + معالج «الوصول الكامل إلى القرص» على macOS.</strong> أدوات ← حالة الأذونات، إضافةً إلى شارة في شريط الحالة لا تظهر إلا حين يكون هناك ما يُقال، تفتح عرضًا تفصيليًا للمجلدات التي تعذّر على الفاحص قراءتها، وعلى أي وحدة تخزين، ولأي سبب — مع الإصلاح الموجَّه للمنصّة التي يعمل عليها <em>الفهرس</em>.","changelog.b5aa6e1796c3":"<strong>الشارة التي يطلب سطر الميزة توسيعها لم تكن موجودة.</strong> لم يكن هناك «تُخطّي n مسارًا (أذونات)» في أي مكان: فالمجلد الذي يتعذّر على الفاحص فتحه كان يُنتج سطر <code>warn!</code> واحدًا لا أكثر، فبدت الشجرة الفرعية غير القابلة للقراءة مطابقة تمامًا لشجرة فرعية فارغة. كان لا بد من بناء الدفتر (<code>crates/freally-indexd/src/permissions.rs</code>) أولًا. وهذه هي المرة الرابعة في جولة بوابة الاستقرار هذه التي يتبيّن فيها أن نقطة البداية المذكورة لإحدى الميزات الأساسية غير موجودة.","changelog.62ca3f92cd3e":"ما يسجّله الدفتر ولماذا:","changelog.d8706bc2b337":"<strong>الجذور لا الملفات.</strong> يُبلغ <code>walkdir</code> عن خطأ واحد للمجلد الذي لا يستطيع فتحه ولا ينزل داخله، فما يصل إلى الدفتر هو بطبيعة الحال جذر كل شجرة فرعية غير قابلة للقراءة. وهذه أيضًا الإجابة المفيدة: «امنح الوصول إلى هذا المجلد»، لا عشرة آلاف اسم ملف.","changelog.0917b96f248e":"<strong>المسار الذي اختفى ليس عطلًا.</strong> يُسقَط <code>NotFound</code> كليًا — فحذف ملف أثناء الفحص أمر طبيعي في نظام ملفات حي، وعدّه سيجعل كل تقرير على جهاز مشغول يبدو مقلقًا.","changelog.4df4fedc30d4":"<strong>بحدّ أقصى 2,000 إدخال، مع عدّ الفائض.</strong> تُحفظ هذه القائمة في الذاكرة وتُسلسَل وتُرسل عبر IPC؛ وبعد بضعة آلاف تتوقف عن كونها تقريرًا يقرؤه إنسان. تقول الواجهة «و12,043 أخرى» بدلًا من الإيحاء بأن القائمة كاملة.","changelog.45a8fa9b22b3":"<strong>تمسح إعادة الفحص إدخالات ذلك الجذر أولًا</strong>، فيتوقف الإبلاغ عن إذن أصلحه المستخدم فعلًا. ودون ذلك لن يفعل التقرير سوى أن يكبر.","changelog.8c83c3941420":"<strong>يُحفظ</strong> في <code>config/permissions.json</code>، لأن «الملفات التي تعذّرت فهرستها» يجب أن تصمد أمام إعادة التشغيل لتكون ذات قيمة.","changelog.2272ff2f607f":"تُحدَّد الإرشادات <strong>على جانب الخدمة الخلفية</strong>، لا من وكيل المستخدم (user-agent) في المتصفح: فقد يكون الفهرس على جهاز غير الجهاز الذي تعرض نافذته التقرير كلما وُجّه عميلٌ إلى نقطة نهاية بعيدة، والإصلاح يخصّ الجهاز الذي تعذّر عليه قراءة المجلد.","changelog.7bd109d95768":"على macOS <strong>يكتشف التقرير «الوصول الكامل إلى القرص»</strong> بقراءة مجلد محمي بـ TCC: النجاح يعني أنه ممنوح، و<code>PermissionDenied</code> يعني أنه غير ممنوح. وأي خطأ آخر يُبلَّغ عنه على أنه <em>غير محدَّد</em> لا «غير ممنوح» — فأن تطلب من شخص إصلاح إعداد صحيح أصلًا أسوأ من ألا تقول شيئًا. وحين لا يكون ممنوحًا، يفتح زرٌّ لوحة «الوصول الكامل إلى القرص» مباشرةً.","changelog.bea94a4860c8":"اختبار الدخان: يُثبت <code>tests/smoke/build_03_permissions.rs</code> أن الفاحص يمسك بالدفتر فعلًا — فالشجرة السليمة تتركه فارغًا، والفحص الحقيقي يُسقط إدخالات المرور السابق لذلك الجذر ويترك الجذور الأخرى على حالها. ولا يحاول عمدًا إنشاء مجلد مرفوض الوصول: فهذا غير قابل للنقل بين الأنظمة (<code>chmod 000</code> لا أثر له على المستخدم root، وWindows سيتطلب جراحة في قوائم ACL)، لذا تُختبر مسارات الرفض باختبارات وحدة تبني <code>io::Error</code> مباشرةً بدلًا من طلبه من نظام التشغيل.","changelog.a0e48a175453":"<strong>SRC-M18 — تشغيل الصوت والفيديو مباشرةً في جزء المعاينة.</strong> أزرار التحكم (تشغيل/إيقاف مؤقت، والانتقال، والتكرار)، ومنزلق لمستوى الصوت، وشكل موجي معروض يمكنك النقر عليه للتنقّل، مع شارات المرمّز / معدّل العيّنات / القنوات / LUFS فوقه. لم يعد الاستماع إلى نتيجة <code>lufs:&lt;-14</code> يعني مغادرة Freally، وهذا هو سير العمل الذي وُجدت عدسة الصوت لإبقائك داخله.","changelog.5677c3279dd5":"<strong>لا يكلّف الشكل الموجي أي فكّ ترميز إضافي.</strong> يرافق <code>PeakCollector</code> مرحلة التحليل الموجودة في <code>freally-audio</code>: فالإطارات المتشابكة نفسها التي تغذّي مُراكِمات شدة الصوت والصمت تغذّيه، فلا يؤدي فتح مقطع في جزء يُعاد فتحه مع كل ضغطة سهم إلى فكّ ترميز الملف مرة ثانية لمجرد رسم صورة له. الدلاء ثابتة العدد لا لكل ثانية لأن لوحة الرسم ذات عرض ثابت — وإعادة تشكيل غلاف لكل ثانية ليناسبها تتخلّص تحديدًا من القمم التي تجعل الشكل مقروءًا — وتأخذ الدلاء القمة عبر القنوات، لأن الشكل الموجي يُظهر أعلى ما يحدث في تلك اللحظة، لا رأي القناة اليسرى فيه.","changelog.cdfeb4ff1549":"<strong>تمرّ البايتات عبر IPC، لا عبر بروتوكول الأصول — عمدًا.</strong> الطريقة المعتادة لتغذية عنصر وسائط هي بروتوكول الأصول (asset protocol) في Tauri، وقد رُفضت: فتفعيله يعني الإعلان عن نطاق في نظام الملفات يحقّ للـ <em>webview</em> قراءته مباشرةً، وأي نطاق واسع بما يكفي ليغطي «أينما توجد وسائط المستخدم» واسع بما يكفي لإبطال بوابة <code>KnownPaths</code> التي قوّاها البناء 1 — أي الخاصية التي تضمن ألا تصل اعتمادية مخترَقة في الواجهة الأمامية إلى ملف لم تُرجعه الخدمة الخلفية قط. وتوجيه البايتات عبر أمر يُبقي كل قراءة خلف الفحص نفسه الذي تخضع له كل عملية ملفات أخرى.","changelog.92840d3c1b10":"الثمن أن التشغيل مُخزَّن مؤقتًا لا متدفق، فهناك سقف قدره 192 MB — مذكور في الواجهة، التي تعرض فتح ما يتجاوزه في مشغّل النظام، بدلًا من الفشل بصمت. تُعاد البايتات كـ <code>tauri::ipc::Response</code> خام بدلًا من عنوان بيانات base64، الذي كان سيضخّم الحمولة بمقدار الثلث ويكلّف إعادة ترميز كاملة على الجانبين.","changelog.712f85c29448":"أمران أصغر كان كلٌّ منهما سيكون خللًا حقيقيًا: يُلغى عنوان URL الخاص بالكائن عند تغيّر التحديد (ودون ذلك، تُسرّب كل ضغطة سهم ملفًا مفكوكًا بأكمله)، وتُعرض شدة الصوت المتكاملة غير المنتهية على أنها <em>بلا شارة</em> لا على أنها <code>-inf LUFS</code> — فالمقطع الأقصر من كتلة بوابية واحدة (gating block) لا قيمة متكاملة ذات معنى له.","changelog.d91a498a29f7":"تتحدد قابلية التشغيل من امتداد النتيجة، لا من حمولة المعاينة: فحمولة ملف الوسائط هي <code>unsupported</code>، وهذه تحديدًا الحالة التي تستحق التشغيل.","changelog.7c9e53ab0e65":"ختام البناء 3 — ما غيّرته جولات المراجعة","changelog.4519ec9bebde":"شغّل <code>/simplify</code> أربعة مراجعين على الفرق الكامل للبناء. أشار ثلاثة منهم بشكل مستقل إلى الأمر نفسه، وكانت نتيجتان منها عيوبًا حقيقية لا مسائل أسلوب:","changelog.8ce21698a623":"<strong>كان الشريط الجانبي يُسقط عوامل التصفية المحفوظة في الإشارة المرجعية.</strong> أعاد <code>applyBookmark</code> تنفيذ تدفّق التحميل الخاص بالقائمة المنسدلة وأغفل <code>typeFilterStore.setFromIds(...)</code>، فكان فتح إشارة مرجعية من الشريط الجانبي يركّب بادئة عدسة مختلفة عن فتح الإشارة نفسها من القائمة المنسدلة. أصبح كلاهما يستدعي <code>bookmarksStore.apply</code> واحدًا.","changelog.eac5108065c7":"<strong>كان <code>visibleHits</code> موجودًا مرتين، بإجابتين مختلفتين.</strong> كانت نسخة «نظرة سريعة» ترتّب؛ أما <code>resultsStore.visibleHits</code> — الذي يقرؤه التصدير وتحديد الكل وعدّاد شريط الحالة — فلا. فاختلف الاثنان لحظة تفعيل الترتيب حسب عمود. انتقل الترتيب إلى دالة الجلب (getter) في المخزن وأُزيلت النسخة، ما يجعل أيضًا تعليق تلك الدالة «الإجابة الوحيدة عمّا ينظر إليه المستخدم» صحيحًا لا مجرد طموح.","changelog.c773525b8054":"<strong>كانت قائمتا الوضع الصارم المتزامنتان يدويًا قد تباعدتا بالفعل.</strong> كانت قائمة المحلّل للمُعدِّلات الخاصة بـ Freally تتضمن <code>volume:</code> بينما لم تتضمنه نسخة <code>report.rs</code>، فكان المحلّل يرفض استعلام strict-everything يستخدم <code>volume:</code> بينما كان التقرير الذي يعرض منه شريط البحث يعدّه سليمًا. أصبحت هناك الآن <code>is_freally_only_modifier</code> واحدة.","changelog.67e8b82d717f":"نتائج أداء تستحق التسجيل، كلها في مسارات أضافها هذا البناء:","changelog.193b3787c53e":"كان تأثير شارة الأذونات يُعاد إطلاقه مع كل استطلاع لحالة الفهرس — إذ يعيد <code>indexStateStore</code> تعيين كائن الحالة كله، فتُبطَل «قراءة <code>phase</code>» سواء تغيّر <code>phase</code> أم لا. كان يُصدر رحلة ذهاب وإياب عبر IPC كل خمس ثوانٍ إلى ما لا نهاية، تنسخ كلٌّ منها الدفتر بأكمله تحت قفل mutex. أصبح محميًا بمقارنة مع آخر مرحلة جرى استطلاعها.","changelog.25ff7799a027":"كانت دالة مقارنة الترتيب الطبيعي تشغّل تعبيرًا نمطيًا لكل <em>حرف</em> وتبني مُرتِّبًا (collator) جديدًا لكل مقطع. أصبحت الآن اختبارًا لنقطة الترميز و<code>Intl.Collator</code> واحدًا مشتركًا.","changelog.282cbf6f5b04":"كان الترتيب حسب المسار يحوّل كلا <code>PathBuf</code> في كل مقارنة — أي O(n log n) من عمليات فحص WTF-8. أصبح الآن بأسلوب التزيين-الترتيب-إزالة التزيين (decorate-sort-undecorate)، بتحويل واحد لكل صف.","changelog.fa6395a85e8e":"كان مشغّل الوسائط يحمّل البايتات والشكل الموجي بالتتابع مع أنهما مستقلان؛ وجعل أعمدة الشكل الموجي الـ ~800 كلها معتمدة على تقدّم التشغيل، فكان كل <code>timeupdate</code> يعيد تقييم 800 تعبير. أصبح الآن تداخلًا على نمط <code>Promise.all</code> وطبقة <code>--progress</code> واحدة فوقها.","changelog.1a1162f4da54":"وأيضًا: أصبح <code>AnalysisOpts::peak_buckets</code> خاصًا، لأنه كحقل <code>pub</code> كان بإمكان المستدعي ضبطه عند استدعاء <code>analyze_with_opts</code>، الذي لا مكان لديه لإرجاع القمم فكان سيتجاهلها بصمت؛ وأصبح <code>media.rs</code> يستدعي <code>files::verify_readable</code> المشتركة بدلًا من نسخته الخاصة، فيتحدد مستوى المصدر (provenance) للقراءات التي تؤكدها الواجهة الأمامية في موضع واحد بالضبط.","changelog.c70a3b9f1590":"ختام البناء 3 — ما غيّرته <code>/security-review</code>","changelog.ccce544a9b0c":"نتيجتان بدرجة HIGH (عالية)، أدخلهما هذا البناء كلتيهما، وأُصلحتا كلتاهما.","changelog.de5618b9e06c":"<strong>كان <code>media_bytes</code> محميًا بالمستوى الذي تستطيع الواجهة الأمامية أن تمنحه لنفسها.</strong> إنه يُرجع المحتوى <em>الكامل</em> لملف مسمّى إلى الـ webview، وكان يستخدم <code>Provenance::FrontendAsserted</code> — المستوى الذي يمنحه <code>files_whitelist_user_chosen</code> لأي سلسلة تطلبها طبقة JS. كان بإمكان اعتمادية مخترَقة في الواجهة الأمامية أن تضيف <code>~/.ssh/id_ed25519</code> إلى القائمة البيضاء ثم تقرأه، دون أي نافذة حوار ودون تدخّل الخدمة الخلفية. كان الأمران الآخران اللذان يُرجعان محتويات الملفات، <code>content_document</code> و<code>copy_file_contents</code>، يتطلبان <code>QueryHit</code> بالفعل؛ وأصبح هذان يتطلبانه الآن أيضًا. يأتي الاستدعاء المشروع انطلاقًا من صفوف النتائج، التي تحمل ذلك المستوى أصلًا، فلا يتغيّر شيء مما يراه المستخدم.","changelog.ec04c33c4cd8":"<strong>كان مقبس الوضع المحمول موضوعًا مباشرةً في المجلد المؤقت المشترك.</strong> <code>/tmp</code> بالوضع 1777، وكان الاسم تجزئة FNV لمسار يمكن تخمينه، فكان بإمكان أي حساب محلي أن يربطه أولًا. تُصادق طبقة النقل <em>الطرفَ المقابل</em> لمستمع تملكه؛ أما العميل المتصل للخارج فلم يكن يفحص شيئًا، فكان الاستيلاء المسبق على ذلك المسار انتحالًا كاملًا لشخصية الخدمة الخلفية — ويحوّل <code>register_hit_paths</code> أي شيء يصل في <code>query:batch</code> إلى <code>Provenance::QueryHit</code>، وهي البوابة التي تحمي الحذف وإعادة التسمية وكل أمر تدميري آخر. ثلاثة تغييرات:","changelog.7cf7132d7226":"انتقل المقبس إلى مجلد خاص بكل مستخدم — <code>$XDG_RUNTIME_DIR</code> حيث يوجد، وإلا فمجلد فرعي موسوم بـ uid تنشئه هذه العملية وتضبط أذوناته على 0700 عبر chmod، وترفضه رفضًا قاطعًا إن تبيّن أنه مملوك لشخص آخر.","changelog.aadc9d78386e":"أصبح <code>transport::unix::connect</code> يرفض أي مقبس لا يملكه هذا المستخدم، أو يسمح وضعه بوصول الآخرين إليه. ويستخدم <code>symlink_metadata</code>، فلا يجتاز الفحصَ رابطٌ رمزي يشير إلى مقبس نملكه فعلًا. وهذا هو النظير الذي كان مفقودًا لفحص uid الطرف المقابل في المستمع.","changelog.0ed10670ac32":"لم يعد <code>listen</code> يفشل فشلًا قاطعًا عندما لا يستطيع تشديد أذونات المجلد الأب للمقبس. يُرجع <code>chmod 0700 /tmp</code> الخطأ <code>EPERM</code> لكل مستخدم غير root، لذا <strong>لم يكن الوضع المحمول قادرًا على تشغيل خدمته الخلفية على Linux إطلاقًا</strong> — فخطوة التقوية كانت تُسقط الشيء الذي وُجدت لحمايته. أصبح يسجّل ذلك ويعتمد بدلًا منه على الوضع 0600 الخاص بالمقبس نفسه.","changelog.d3ce18a2d574":"<span class=\"release__meta\"><span class=\"release__ver\">v0.22.0</span><time class=\"release__date\" datetime=\"2026-08-02\">2026-08-02</time></span><span class=\"release__title\">البناء 2 · بوابة الاستقرار للميزات الأساسية (Must-Have)، الشريحة 2 من 3</span>","changelog.9bd054757229":"ثاني عمليات البناء الثلاث للميزات الأساسية: SRC-M09 … SRC-M16. متعدد المنصّات ما لم تذكر ملاحظة خاصة بنظام تشغيل خلاف ذلك. التوثيق الكامل للميزات موجود في <code>docs/documentation.html</code>.","changelog.d9bb66b60223":"<strong>SRC-M09 — مخرجات CLI قابلة للقراءة آليًا.</strong> يكتسب <code>freally search</code> الخيارات <code>--json</code> و<code>--ndjson</code> (كائن لكل نتيجة، بالتدفق) و<code>--csv</code> و<code>--fields</code> لاختيار الأعمدة و<code>-0</code> لـ <code>xargs -0</code> و<code>--limit</code> / <code>--offset</code>، ورموز خروج ذات معنى (0 عُثر على نتائج، 1 لا شيء، 2 خطأ).","changelog.758c601a0121":"<strong>SRC-M10 — إكمالات الصدفة (shell).</strong> يطبع <code>freally completions &lt;shell&gt;</code> إكمالات لـ bash وzsh وfish وPowerShell، تغطي الأوامر الفرعية والخيارات، و— ديناميكيًا — الكلمات المفتاحية للمُعدِّلات وأسماء عمليات البحث المحفوظة.","changelog.88b57e0c662b":"<strong>SRC-M11 — «هل تقصد» المتسامح مع الأخطاء الإملائية.</strong> عندما لا تُرجع عدسة أسماء الملفات شيئًا، يُعاد ترتيب مرشّحي التشابه حسب مسافة Damerau-Levenshtein المحدودة، ويُعرض الأقرب كتصحيح بنقرة واحدة.","changelog.651b223b2f18":"<strong>SRC-M12 — المطابقة الصوتية لـ CJK.</strong> كتابة <code>wenjian</code> أو <code>wj</code> تطابق <code>文件</code>؛ والروماجي يطابق الكانا؛ وحروف الجامو الأولى تطابق الهانغول. تُفهرس القراءات كمفاتيح أسماء مساعدة، وتُفعَّل اختياريًا عبر <strong>بحث ← مطابقة صوتيات CJK</strong>. كل تحويل هو بحث في جدول أو عملية حسابية — فتفكيك الهانغول حساب خالص على كتلة المقاطع في Unicode، والكانا جدول داخل الشجرة، وقراءات الهان تأتي من حزمة <code>pinyin</code>.","changelog.1bd2b09ee538":"<strong>تسجيل التغييرات الحي.</strong> أصبح الفهرس يتحدّث مع تغيّر الملفات، لا عند تشغيل الفحص فقط. كان كل مشترك في نظام التشغيل يطبّق <code>subscribe()</code> بالفعل، وكان <code>freally-index</code> يوفّر <code>EventQueue</code> المحدودة بالفعل، لكن لا شيء كان يربطهما قط: إذ لم يكن الوصول إلى <code>Index::apply</code> و<code>EventQueue</code> ممكنًا إلا من اختبارات قياس الأداء واختبار وحدة واحد. <code>freally-indexd::watcher</code> هو خط المعالجة ذاك — خيط منتج يفرّغ تدفق تغييرات نظام التشغيل في الطابور، ومستهلك يطبّق الدفعات ويودعها. على Windows يكون سجل USN لكل وحدة تخزين، فتندمج المجلدات الموجودة على محرك واحد في مراقب واحد يصفّي حسب بادئة المسار؛ أما FSEvents وinotify فيراقبان شجرة فرعية مباشرةً.","changelog.eaa3eb8d8d9f":"<em>لماذا يُسقط المنتج الأحداث بدلًا من الحجب:</em> الحجب لن ينقذ الأحداث — فالمخزن المؤقت على جانب نظام التشغيل يواصل الامتلاء بينما ننتظر، وعندما يفيض تضيع الأحداث دون أي سجل. أما الإسقاط عند حدودنا نحن فيفقد الأحداث نفسها لكنه يترك دفترًا معدودًا ومختومًا بالوقت، وهو ما يُبلغ عنه المستشار أدناه.","changelog.71e6a83277bd":"<strong>SRC-M13 — لوحة «حالة الفهرس» + مستشار إعادة البناء.</strong> تُبلغ <strong>أدوات ← صيانة الفهرس ← حالة الفهرس</strong>، لكل موقع مراقَب، عن التأخر بين الحدث وظهوره في الاستعلامات، ودفتر الأحداث المُسقطة، وآخر تغيير رُصد، وعمق الطابور، إضافةً إلى نصائح قائمة على قواعد مع إعادة بناء بنقرة واحدة حيث تكون إعادة البناء هي الحل. ويُبلَّغ عن تراكم استخراج المحتوى على أنه <em>غير متتبَّع</em> لا على أنه صفر — فالخدمة الخلفية لا تشغّل أي عامل للاستخراج المسبق، و«0» سيُفهم على أنه «خامل».","changelog.946db255ad4d":"<strong>SRC-M14 — كتالوجات غير متصلة لوحدات التخزين القابلة للإزالة.</strong> يُبقي فصلُ محرك الأقراص ملفاتِه قابلة للبحث، وتحمل النتائج القادمة من جهاز مفصول شارة <em>غير متصل — Orange WD 4TB</em>. يصفّي <code>volume:</code> حسب الاسم الذي تعرف به المحرك، أو حسب معرّف وحدة التخزين. والمحرك الذي يعود بحرف مختلف أو نقطة تركيب مختلفة يُتعرَّف عليه على أنه الكتالوج نفسه.","changelog.f637da61fd70":"<em>تحت الغطاء:</em> صدر عمود <code>volume</code> وفهرسه في SQLite وحقل Tantivy كلها في المرحلة 4، لكن مُنشئ الصفوف الوحيد في مسار الاستيعاب كان يثبّت في الشيفرة سلسلة فارغة، فكان العمود كله ميتًا. أصبحت الصفوف الآن تُوسَم بمطابقة أطول بادئة على جدول التركيب الحقيقي، وهو الشيء الوحيد القادر على التمييز بين نقطة تركيب ومجلد عادي.","changelog.4ec8be883d22":"<strong>SRC-M15 — إعادة التسمية الجماعية.</strong> حدّد أي عدد من النتائج، واضغط <code>F2</code>، وصِف التغيير مرة واحدة: بحث/استبدال حرفي أو بتعبير نمطي مع مجموعات التقاط، وعدّادات <code>{n}</code> / <code>{n:03}</code>، وتحويلات حالة الأحرف، والاختيار بين إعادة تسمية الاسم دون الامتداد أو الاسم كاملًا. يعرض جدول حيّ كل زوج قبل/بعد، ويميّز الصفوف التي ستتصادم فيما بينها، أو تستبدل ملفًا موجودًا، أو تُنتج اسمًا لن يقبله النظام. الدفعة كلٌّ لا يتجزأ، والفشل في منتصفها يتراجع عن كل شيء.","changelog.46851cce7744":"<em>ملاحظة:</em> سجّلت خارطة الطريق إعادة تسمية الملف الواحد على أنها صادرة بالفعل. لم تكن كذلك — إذ لم تكن موجودة إلا إعادة تسمية <em>الإشارات المرجعية</em> — لذا يضيف هذا البناء عملية إعادة التسمية الأساسية إلى جانب الطبقة الجماعية فوقها.","changelog.3fc85f03e023":"<strong>SRC-M16 — التراجع/الإعادة لعمليات الملفات.</strong> يعكس <code>Ctrl+Z</code> إعادة تسمية أو إعادة تسمية جماعية، ويعيد <code>Ctrl+Shift+Z</code> تنفيذها، وتحفظ الخدمة الخلفية سجل العمليات فتصمد آخر 50 عملية أمام إعادة التشغيل. تُفكّ الدفعة بترتيب معكوس، فيُتراجع عن إعادة التسمية المتسلسلة (<code>a→b</code>، <code>b→c</code>) دون أن تتصادم مع نفسها.","changelog.51f9c128a973":"<em>استثناء موثّق:</em> تُسجَّل عمليات الحذف في السجل لكن لا تراجع عنها. يحذف Freally إلى سلة مهملات نظام التشغيل، وواجهة API الوحيدة متعددة المنصّات للاستعادة (<code>trash::os_limited</code>) مطبّقة لـ Windows ولـ Linux المتوافق مع freedesktop لكن <strong>ليس لـ macOS</strong>. وبدلًا من تقديم زر يفشل بعد الضغط عليه، يحمل الحذف سببًا يوضح أن الاستعادة من مهام نظام التشغيل. ولا تُسجَّل عمليتا النسخ إلى مجلد والنقل إلى مجلد لأنهما لا تُجريان نسخًا أو نقلًا بعد.","changelog.c75a49fc28b8":"<strong>البنية الأمنية لأوامر جانب الكتابة.</strong> لإعادة التسمية وجهة، وخلافًا للمصدر لم تكن الوجهة في أي مجموعة نتائج قط — لذا، وفقًا لقاعدة البناء 1 التي تقضي بألا يقبل IPC جانب الكتابة مسارات يختارها المستدعي، لا ترسل الواجهة الأمامية وجهة أبدًا. بل ترسل المسارات المحدّدة و<em>القاعدة</em>؛ وتشتقّ الواجهة الخلفية كل اسم بنفسها وتعيد اشتقاقه وقت التطبيق بدلًا من الوثوق بالمعاينة، فلا يغيّر جدول معاينة معبوث به أي شيء. تُرفض الأسماء المشتقّة إن احتوت على فاصل مسار، أو كانت <code>.</code> أو <code>..</code>، أو تضمّنت حرفًا لا تقبله أي منصّة، أو كان Windows سيعيد كتابتها بصمت (نقطة أو مسافة في النهاية، ما سيجعل الاسم المطبّق مختلفًا عن الاسم المعتمد)، أو طابقت اسم جهاز محجوزًا. ثم يُعاد بناء الوجهة من المجلد الأب للمصدر نفسه.","changelog.b2289135440f":"<strong>الاختبارات.</strong> تحرس <code>tests/smoke/build_02_index_health.rs</code> و<code>build_02_volume_catalogs.rs</code> و<code>build_02_rename_undo.rs</code> الواجهات الجديدة بشكل مستقل عن نظام التشغيل؛ وتغطي اختبارات الوحدة محرّك إعادة التسمية، وسجل العمليات، وقواعد المستشار، ودمج الأحداث، وحساب التأخر، وخريطة وحدات التخزين، وسجلّ الكتالوجات. ويغطي <code>apps/freally-ui/tests/unit/build_02.test.ts</code> توصيلات الواجهة الأمامية.","changelog.b1d319c1818b":"<strong>التدويل (i18n).</strong> 68 مفتاحًا جديدًا في اللغات الـ 18 كلها (782 إجمالًا)؛ و<code>xtask i18n-lint</code> ناجح.","changelog.7d87f19cc769":"<code>volume:</code> مُعدِّل خاص بـ Freally، لذا يُرفض في وضع Everything الصارم إلى جانب <code>similar:</code> وعائلة مُعدِّلات الصوت.","changelog.7df7bfeaffe7":"يوفّر <code>freally-journal</code> بنية <code>JournalPosition</code> مستقلة عن نظام التشغيل (<code>generation</code> + <code>offset</code>) في المشتركين الثلاثة كلهم، فتستطيع الخدمة الخلفية اكتشاف تدفق تغييرات التفّ أو أُعيد إنشاؤه دون معرفة نوع المؤشر الخاص بكل نظام تشغيل.","changelog.f787e991d5ac":"نواقص معروفة","changelog.cea8b98efa00":"يبقى <code>auto_remove_offline</code> بلا أثر. فتنفيذه حرفيًا يعني محو صفوف جهاز غير متصل من الفهرس؛ وهذا تدميري، وخارج نطاق SRC-M14، وقيمته الافتراضية <code>true</code> كانت ستُطبَّق على كل تثبيت قائم بصمت. الاحتفاظ هو ما تريده الميزة وما كانت الخدمة الخلفية تفعله أصلًا.","changelog.8d7633d7bfb2":"لا تزال مفاتيح أوضاع المطابقة الأربعة الموجودة (حالة الأحرف، والكلمة بالكامل، والمسار، والتشكيل) مقتصرة على الواجهة — إذ تبني الخدمة الخلفية <code>ExecOpts::default()</code> ولا يعبر قناة الاتصال إلا العلم الصوتي الخاص بـ SRC-M12. هذا سابق للبناء 2؛ وتوصيلها سيغيّر ما تُرجعه الاستعلامات القائمة.","changelog.61109f3e67da":"<span class=\"release__meta\"><span class=\"release__ver\">v0.21.0</span><time class=\"release__date\" datetime=\"2026-07-31\">2026-07-31</time></span><span class=\"release__title\">البناء 1 · بوابة الاستقرار للميزات الأساسية (Must-Have)، الشريحة 1 من 3</span>","changelog.d178abfc569c":"أولى عمليات البناء الثلاث للميزات الأساسية: SRC-M01 … SRC-M08. متعدد المنصّات ما لم تذكر ملاحظة خاصة بنظام تشغيل خلاف ذلك. التوثيق الكامل للميزات موجود في <code>docs/documentation.html</code>.","changelog.8290eb7e3829":"<strong>SRC-M01 — عارض المحتوى مع التطابقات في سياقها.</strong> عرض للمستند كاملًا لأي ملف يستطيع خط المُستخرِجات قراءته: كل تطابق مُبرَز، وأسطر مرقّمة، وشارة بعدد التطابقات، والتنقّل بين التطابقات بـ <code>F3</code> / <code>Shift+F3</code>، والانتقال إلى أول تطابق عند الفتح. يُوصل إليه من قائمة النقر بالزر الأيمن الجديدة على النتائج. المصطلحات المُبرَزة هي الذرّات الحرفية والمقتبسة في الاستعلام إضافةً إلى أي شرائح تضييق نشطة. محدود بـ 20,000 سطر، ويقول ذلك صراحةً.","changelog.90356999c878":"<strong>SRC-M02 — البحث داخل النتائج.</strong> يفتح <code>Ctrl+Shift+F</code> مربعًا في مرحلة ثانية يضيّق المجموعة الظاهرة على الشاشة بالفعل بدلًا من إعادة تشغيل الاستعلام. يصبح كل مصطلح شريحة قابلة للإزالة، فيكلّف التجاوز نقرة واحدة بدلًا من إعادة الكتابة. المصطلح الذي يحتوي على فاصل مسار يطابق المسار الكامل، وإلا فاسم الملف. يقرأ التصدير و«تحديد الكل» المجموعة المضيَّقة، فلا يعملان أبدًا على صفوف أزاحتها شريحة. <em>(ينتقل «تنظيم عوامل التصفية» إلى <code>Ctrl+Shift+O</code>.)</em>","changelog.e01ea66e064f":"<strong>SRC-M03 — الاستيراد/التصدير المتوافق مع Everything.</strong> يختار <code>File → Export Results…</code> صيغته من الامتداد المختار في نافذة الحفظ: <code>.efu</code> و<code>.csv</code> و<code>.txt</code> و<code>.m3u</code> / <code>.m3u8</code> و<code>.ndjson</code> و<code>.json</code>. صيغة <code>.efu</code> متوافقة على مستوى البايت مع Everything من voidtools — الترويسة الحرفية <code>Filename,Size,Date Modified,Date Created,Attributes</code>، وصفوف CRLF، والاقتباس وفق RFC-4180، ونبضات Windows FILETIME المحوّلة عند الحدود، فتُحمَّل القائمة المكتوبة على Linux أو macOS في Everything على Windows دون تغيير. تقتصر صادرات قوائم التشغيل على الصوت وتذكر كم صفًا كُتب من أصل كم. يحمّل <code>File → Open File List…</code> قائمةً ويبحث فيها <em>بدلًا من</em> الفهرس الحي — وهذا جواب سؤال «على أي محرك كان ذلك الملف؟» لوحدة تخزين مفصولة. المطابقة على قائمة محمَّلة هي مطابقة سلسلة فرعية في الاسم أو المسار، لا لغة الاستعلام.","changelog.d5c8d8b6e6ed":"<strong>SRC-M04 — فتح باستخدام…</strong> تعداد خاص بكل نظام تشغيل للتطبيقات المسجّلة لنوع النتيجة: <code>SHAssocEnumHandlers</code> على Windows (المصدر الذي يستخدمه Explorer نفسه)، ومطابقة <code>MimeType=</code> في ملفات <code>.desktop</code> مع قاعدة بيانات MIME المشتركة على Linux، وأنواع المستندات المُعلنة في الحزم إضافةً إلى <code>/usr/bin/open -a</code> على macOS.","changelog.00c9693a1527":"<strong>SRC-M05 — أفعال نسخ متقدمة.</strong> انسخ <em>محتويات</em> ملف نصي؛ وانسخ الملفات نفسها ككائنات ملفات في حافظة نظام التشغيل (<code>CF_HDROP</code>، وعناوين URL للملفات في <code>NSPasteboard</code>، و<code>x-special/gnome-copied-files</code>)؛ وانسخ تحديدًا متعددًا كقائمة مسارات بأربعة أنماط اقتباس.","changelog.678cdb17b71c":"<em>استثناء موثّق خاص بنظام تشغيل:</em> لا يملك Linux حافظة داخل العملية تبقى بعد خروج العملية الكاتبة، لذا يتطلب نسخ كائنات الملفات <code>wl-clipboard</code> أو <code>xclip</code>، ويقول ذلك حين لا يكون أيٌّ منهما مثبّتًا.","changelog.c00e9441825d":"<strong>SRC-M06 — الطرفية هنا والأوامر المخصّصة.</strong> يُطلق «فتح طرفية هنا» طرفية المنصّة في مجلد النتيجة. توجد الأوامر التي يعرّفها المستخدم في <strong>الإعدادات ← عام ← أوامر مخصّصة</strong> مع العناصر النائبة <code>{path}</code> / <code>{dir}</code> / <code>{name}</code> / <code>{stem}</code> / <code>{ext}</code> وتحديد نطاق اختياري لكل امتداد. يصبح كل توسيع خانة واحدة في <code>argv</code>.","changelog.561fa38bf46d":"<strong>SRC-M07 — عائلة <code>dupe:</code> تعمل فعليًا.</strong> أصبحت <code>dupe:</code> (الاسم نفسه <em>والحجم</em> نفسه)، و<code>name-dupe:</code> / <code>dupe:name</code>، و<code>size-dupe:</code> / <code>dupe:size</code> تُنفَّذ بدلًا من أن تُحلَّل إلى <code>ModifierKind::Reserved</code>. يجري الاكتشاف مباشرةً من الفهرس — دون تجزئة، فتلك مهمة SRC-N22. تتجمّع الصفوف المطابقة تحت رأس مجموعة. ولا تدخل المجلدات أي مجموعة أبدًا. ومثل <code>similar:</code>، لا تُقبل هذه العائلة إلا في موضع الجذر.","changelog.0610973d550f":"<em>ملاحظة القاعدة الدائمة #8:</em> كان <code>dupe:foo</code> يُحلَّل ثم يفشل وقت التنفيذ. أصبح الآن يفشل وقت <em>التحليل</em> بـ <code>InvalidModifierValue</code> — الترقية نفسها التي حظيت بها مُعدِّلات الصوت في المرحلة 9. لم يتغيّر سلوك أي استعلام كان يُرجع نتائج في أي وقت.","changelog.761324a5cfcc":"<strong>SRC-M08 — مُعدِّلات الفراغ.</strong> <code>empty:</code> (مجرّدًا، أو محدّد النطاق بـ <code>empty:file</code> / <code>empty:folder</code> / <code>empty:roots</code>)، و<code>child-count:</code> و<code>descendant-count:</code>، وتُجاب من بيانات الفهرس دون المرور على نظام الملفات. يُبلغ <code>empty:roots</code> عن <em>قمة</em> كل سلسلة مجلدات لا تحتوي على ملفات في أي عمق؛ أما مُعدِّلات العدّ فلا تطابق إلا المجلدات. تشتقّ البنية الجديدة <code>freally_index::DirStats</code> شكل المجلدات في الفهرس في مرور واحد على <code>files.db</code>، مع حفظ النتيجة (memoized) مقابل عدّاد الأحداث المطبَّقة.","changelog.b3468cd50e03":"<strong>واجهة داعمة.</strong> قائمة نقر بالزر الأيمن على النتائج، وسطح للإشعارات المنبثقة (toast) في النافذة الرئيسية، وشريط التضييق — وكلها قابلة للوصول بلوحة المفاتيح.","changelog.53d34aa4b652":"<strong>الاختبارات.</strong> تحرس <code>tests/smoke/build_01_dsl.rs</code> و<code>build_01_interop.rs</code> عائلتي المُعدِّلات وصيغة <code>.efu</code> المتبادلة؛ وتغطي اختبارات الوحدة <code>DirStats</code>، والمرمِّزات، والاقتباس، وتوسيع العناصر النائبة، وتحليل <code>.desktop</code>، وتحديد مواضع التطابقات، وبوابة المصدر، والتزامن الصارم للجداول عبر الحزم؛ ويغطي <code>tests/unit/build_01.test.ts</code> مخازن الواجهة الأمامية.","changelog.73bc8a5d676f":"<strong>التدويل (i18n).</strong> 55 مفتاحًا جديدًا في اللغات الـ 18 كلها؛ و<code>xtask i18n-lint</code> ناجح.","changelog.f56c4fe5f08d":"<strong>[كل المنصّات]</strong> لم يكن لـ <code>KnownPaths</code> أي كاتب. نقلت المرحلة 12 نتائج الاستعلام إلى إشعارات الخدمة الخلفية ولم يتولَّ أي شيء تسجيلها، فكانت كل عملية ملفات محمية ترفض كل صف من صفوف النتائج. أصبح <code>daemon.rs</code> يسجّلها أثناء مرور <code>query:batch</code>.","changelog.fe76b18c0f5e":"<strong>[كل المنصّات]</strong> لم يكن <code>finalize_bootstrap</code> يزيد <code>applied_events</code>، فكانت <code>DirStats</code> المشتقّة في منتصف الفحص تبقى مخزّنة مؤقتًا مقابل الفهرس المكتمل — ما جعل <code>empty:folder</code> يطابق كل مجلد حتى الدفعة التالية من سجل التغييرات.","changelog.83072c3967c3":"<strong>[كل المنصّات]</strong> كان <code>dupe:</code> الواقع في موضع غير مدعوم يُزال بصمت كلما وُجد آخر في المستوى الأعلى (<code>dupe:name !size-dupe:</code> كان يُرجع صفر نتائج دون أي خطأ). أصبح حارس الموضع يعدّ العُقد بدلًا من التحقق من الغياب.","changelog.abf1376b827c":"<strong>[كل المنصّات]</strong> لم يكن <code>empty:roots</code> يُبلغ عن شيء عندما تكون الشجرة الممسوحة كلها خالية من الملفات: فكل صف يولّد إدخال عدّ لمجلده الأب، فبدا الأب الخاص بجذر الفحص نفسه مفهرسًا.","changelog.24ee98d1fa85":"<strong>[كل المنصّات]</strong> كان نفي شرط لا يستطيع فهرس الأسماء الحسم فيه (<code>!empty:file</code>، <code>!size:&gt;1mb</code>) يُرجع صفر صفوف — إذ ينقلب عُرف مرحلة الأسماء «دَعه يمرّ» إلى رفض تحت <code>NOT</code>. الخلل قديم؛ لكن البناء 1 جعله بارزًا.","changelog.8d60d2e391a7":"<strong>[كل المنصّات]</strong> كان عارض التطابقات يحدّد مواضع التطابقات في <em>نسخة</em> بأحرف صغيرة من كل سطر بينما كانت الواجهة تقتطع من الأصل، فتنزاح كل الإبرازات في أي سطر يحتوي على <code>İ</code>. أصبحت الإزاحات الآن تشير إلى النص الأصلي، ويُطوى نص البحث والنص المبحوث فيه بالطريقة نفسها.","changelog.83b5581b542c":"<strong>[Linux]</strong> كان <code>wl-copy</code> الفاشل (عند العمل تحت X11) يُبلغ عن نجاح، فكان «النسخ كملف» يدّعي أنه يعمل، ويترك الحافظة دون مساس، ولا يلجأ أبدًا إلى <code>xclip</code>.","changelog.4695c56f4771":"<strong>[Windows]</strong> كان حارس COM يستدعي <code>CoUninitialize</code> حتى عندما يُرجع <code>CoInitializeEx</code> القيمة <code>RPC_E_CHANGED_MODE</code> — فيهدم COM من تحت الجهة التي هيّأت ذلك الخيط فعلًا.","changelog.e39b26f32960":"<strong>[CI]</strong> كان <code>vendor/freally-central</code> (لوحة «المزيد من تطبيقات Freally») وحدة فرعية تشير إلى مستودع لم يعد موجودًا، فكان كل تشغيل على كل نظام تشغيل يفشل عند <em>السحب (checkout)</em>. أصبحت اللوحة مضمّنة كشيفرة مصدرية عادية، ويضبط سيرا العمل كلاهما <code>submodules: false</code>، فيُبنى المستودع من نسخة مستنسخة دون الحاجة إلى أي شيء آخر.","changelog.0cb6b784b78e":"<strong>[كل المنصّات]</strong> ترقية <code>wasmtime</code> من 44.0.1 إلى 47.0.3 في مضيف المُستخرِجات المخصّصة، لإغلاق <strong>RUSTSEC-2026-0222</strong> (يمكن أن تختلط فهارس الأنواع بين المحرّكات). لا يمكن الوصول إلى الثغرة إلا عبر مُستخرِج WASM يثبّته المستخدم، لكن <code>cargo-deny</code> يحرس البناء بناءً عليها في كل الأحوال.","changelog.e131be0feec2":"<strong>[كل المنصّات]</strong> أصبح تصدير قوائم الملفات واستيرادها يفتحان نوافذ حوار نظام التشغيل <strong>في Rust</strong> ويعملان على المسار الذي يقرآنه منها. فتوجيه الوجهة عبر الـ webview كان يعني أن <code>file_list_export</code> — أول أمر من جانب <em>الكتابة</em> في البناء 1 — سيستبدل أي مسار تسمّيه الواجهة الأمامية، وكان إدخال السجلّ الذي يتحقق منه إدخالًا تستطيع الواجهة الأمامية إنشاءه. واكتسب <code>KnownPaths</code> أيضًا بُعد <code>Provenance</code> كي لا يمنح أي تفويض يمكن للواجهة الأمامية بلوغه إذنًا بالكتابة أبدًا.","changelog.d1a9848c839b":"<strong>[كل المنصّات]</strong> أصبح <code>run_custom_command</code> يأخذ <strong>معرّف</strong> الأمر ويحلّه مقابل الإعدادات المحفوظة في الواجهة الخلفية. فقبول الحقل <code>program</code> عبر IPC كان يجعله بدائية لتنفيذ عمليات عشوائية: تمرير الوسائط عبر <code>Command::arg</code> لا يحمي شيئًا حين يختار المستدعي الملف التنفيذي أيضًا.","changelog.ed41b394f8fd":"راجع <code>docs/SECURITY.md</code> للاطلاع على الفرق الكامل في نموذج التهديدات.","changelog.c99d8fed1d7c":"<span class=\"release__meta\"><span class=\"release__ver\">v0.20.1</span><time class=\"release__date\" datetime=\"2026-07-10\">2026-07-10</time></span>","changelog.2cd4002ecd32":"إصدار تصحيحي بلا ميزات جديدة. سبب وجوده أن v0.20.0 لا يستطيع إصلاح نفسه: فنقطة نهاية أداة التحديث مُصرَّفة داخل الملف التنفيذي المنشور، فكل تثبيت يتحقق من مستودع غير موجود ولن يُعرض عليه أي تحديث أبدًا. هذا هو البناء الذي يصلح ذلك، ويحمل ترقيات الأمان الأحدث من v0.20.0.","changelog.4bffda6c3827":"<strong>[كل المنصّات]</strong> ترقية <code>quick-xml</code> من 0.39.4 إلى 0.41.0، لإغلاق <strong>RUSTSEC-2026-0194</strong> (زمن تشغيل تربيعي عند فحص وسم البداية بحثًا عن أسماء سمات مكرّرة) و<strong>RUSTSEC-2026-0195</strong> (تخصيص غير محدود لتصريحات نطاقات الأسماء في <code>NsReader</code>، ما يسبّب حجب خدمة باستنزاف الذاكرة). كلتاهما قابلتان للوصول: فمُستخرِجا docx وpptx في <code>freally-extractors</code> يغذّيان <code>quick_xml::Reader</code> بملفات Office XML غير موثوقة مباشرةً. كان بإمكان مستند عدائي أن يعطّل مضيف المُستخرِجات أو يستنزفه. الترخيص دون تغيير (MIT).","changelog.68001f921152":"<strong>[كل المنصّات]</strong> ترقية <code>calamine</code> من 0.34.0 إلى 0.36.0 — وهو أول إصدار يقبل <code>quick-xml ^0.41</code>، فهو إذن متطلّب لما سبق لا تغيير قائم بذاته. الترخيص دون تغيير (MIT). وتنتقل اعتماديته غير المباشرة <code>zip</code> من 7 إلى 8؛ بينما تبقى <code>zip</code> الخاصة بمساحة العمل مثبّتة على 5.","changelog.d7a4cb594270":"<strong>[كل المنصّات]</strong> ترقية <code>crossbeam-epoch</code> من 0.9.18 إلى 0.9.20، لإغلاق <strong>RUSTSEC-2026-0204</strong> (إلغاء مرجعية مؤشر غير صالح في تنفيذ <code>fmt::Pointer</code> لـ <code>Atomic</code> و<code>Shared</code> عندما يكون المؤشر الأساسي غير صالح). اعتمادية غير مباشرة ومتوافقة وفق semver. الترخيص دون تغيير (MIT OR Apache-2.0).","changelog.4aabc8b9de68":"أُصلحت الثلاث كلها بالترقية. لم يُضف أي تنبيه أمني إلى قائمة التجاهل في <code>deny.toml</code>.","changelog.6fd7a68afb1a":"<strong>[كل المنصّات]</strong> أصبحت أداة التحديث التلقائي تشير إلى المستودع الذي يوجد فيه هذا المشروع فعلًا. كان <code>tauri.conf.json</code> يسمّي <code>MikesRuthless12/Freally</code>، وهو غير موجود، فكان <code>latest.json</code> يُحَلّ إلى 404، و<strong>لم يعمل التحديث التلقائي قط في أي بناء منشور</strong>. ولأن نقطة النهاية مدمجة في الملف التنفيذي، يواصل v0.19.84 وv0.20.0 استطلاع العنوان الميت؛ ولا تستطيع العثور على تحديث إلا تثبيتات هذا الإصدار أو ما بعده.","changelog.4a77c5b010f4":"<span class=\"release__meta\"><span class=\"release__ver\">v0.20.0</span><time class=\"release__date\" datetime=\"2026-07-01\">2026-07-01</time></span>","changelog.ff6c265c78c6":"لم تُكتب أي ملاحظات لهذا الإصدار. ما غيّره لا يمكن استرجاعه إلا من نطاق الإيداعات بين <code>v0.19.84</code> و<code>v0.20.0</code>؛ ويُسجَّل هنا على أنه غائب بدلًا من إعادة بنائه، لأن ملخصًا معقولًا يُكتب بعد خمسة أشهر تخمينٌ يرتدي تنسيق الحقيقة نفسه. والأمر الوحيد المعروف عنه يقينًا موجود في <code>[0.20.1]</code> أدناه: كانت نقطة نهاية أداة التحديث فيه تسمّي مستودعًا غير موجود، ولم يكن قادرًا على إصلاح نفسه.","changelog.648e810f75b8":"<span class=\"release__meta\"><span class=\"release__ver\">v0.19.84</span><time class=\"release__date\" datetime=\"2026-06-21\">2026-06-21</time></span><span class=\"release__title\">المراحل 0–12 · أول بناء عام</span>","changelog.abfb5e516e09":"بقيت هذه الملاحظات تحت <code>## [Unreleased]</code> من 2026-05-11 حتى 2026-08-21، عبر خمسة إصدارات موسومة. وهي ليست عملًا غير مُصدَر ولم تكن كذلك قط — فإدخال المرحلة 0 أدناه ينتهي بعبارة «سيكون أول وسم عام <strong>v0.19.84</strong>»، وهو ما يوثّقه هذا القسم. أُنشئ الوسم في 2026-06-21 دون أن يعيد أحد تسمية العنوان، فورث كل إصدار بعده الكتلة نفسها.","changelog.c8dfea56f286":"كان ذلك خطرًا قائمًا، لا مجرد فوضى. فسير عمل الإصدار يبني ملاحظاته المنشورة بإعادة تسمية <code>## [Unreleased]</code> إلى الإصدار الجاري إنشاؤه، فكان الإصدار التالي سينشر 533 سطرًا من عمل المراحل 0–12 — عمرها خمسة أشهر، وموجودة بالفعل في كل تثبيت — كأنها جديدة. وهو مؤرَّخ بالوسم الذي صدر فيه بدلًا من تقسيمه بين <code>v0.19.84</code> و<code>v0.20.0</code>، لأن كل إدخال فيه أقدم من كليهما.","changelog.14161839f591":"كل ما يلي أقدم من إصدارات البناء 1–3 ولم يُرفع قط إلى قسم إصدار. ويُترك هنا دون مساس بدلًا من إعادة توزيعه على <code>0.21.0</code>–<code>0.23.0</code> بالتخمين؛ فترتيبه جولة عمل مستقلة بذاتها.","changelog.f1873f116239":"TASK-098 — تدويل Fluent كامل من الطرف إلى الطرف عبر اللغات الـ 18 كلها (2026-05-11)","changelog.495b18f2f513":"أصبح مُحمِّل Fluent للغات الـ 18 موصولًا. يؤدي تبديل اللغة في الإعدادات ← اللغة والمنطقة (أو في معالج التشغيل الأول) إلى إعادة عرض كل سلسلة مترجمة في الواجهة — القوائم وشريط الحالة ولوحات الإعدادات ونوافذ الحوار والمعالج — دون إعادة تشغيل.","changelog.78760917c35b":"<strong>المُحمِّل.</strong>","changelog.5f1a08de08be":"يستبدل <code>apps/freally-ui/src/lib/i18n/bundle.ts</code> السلسلة المضمّنة <code>EN_FTL</code> من المرحلة 11 بـ <code>import.meta.glob(&quot;../../../../../locales/*/freally.ftl&quot;, { query: &quot;?raw&quot;, eager: true })</code>. تُضمَّن ملفات <code>.ftl</code> الـ 18 كلها وقت البناء؛ ويضع كل <code>FluentBundle</code> اللغة <code>en</code> تحته كمورد احتياطي، فيظهر أي مفتاح مفقود شارد بالإنجليزية بدلًا من سلسلة مفتاح خام.","changelog.a9d6f49ee814":"يوسّع <code>vite.config.ts</code> الإعداد <code>server.fs.allow</code> ليشمل جذر مساحة العمل، كي يستطيع وضع التطوير قراءة شجرة اللغات الموجودة خارج جذر الحزمة.","changelog.d354155cedc1":"يصدّر <code>bundle.ts</code> الدالة <code>loadedLocales()</code> كي تتحقق مجموعة الاختبارات من أن النمط (glob) التقط فعلًا الملفات الـ 18 كلها.","changelog.50aa545a0dff":"<strong>بيانات الترجمة — التزامن الصارم وفق القاعدة الدائمة #4.</strong>","changelog.c8b21089e4f2":"نما <code>en/freally.ftl</code> من 314 إلى 557 مفتاحًا. تغطي الإضافات الـ 243 تحسينات المعالج (التلميحات، والعناصر النائبة، و«الخطوة N من N»)، ومقاطع شريط الحالة، وسلاسل العدسات / المعاينة / الإشارات المرجعية، ونافذتي «حول» / «اتصال»، وكل تلميح وعنوان قسم وإشعار منبثق في لوحات الواجهة/الرئيسية/النسخ الاحتياطي/لوحة المفاتيح/السجل/اللغة والمنطقة/المجلدات/وحدات التخزين، وشريط القوائم الكامل وفق PRD §8.28 (كل تسمية في ملف/تحرير/عرض/بحث/الإشارات المرجعية/أدوات/مساعدة + كل عنوان قائمة فرعية + كل تلميح عند التمرير).","changelog.8f7a7778b776":"نُسخت المفاتيح الـ 243 نفسها إلى اللغات الـ 17 الأخرى كلها بالتوازي (es، de، fr، it، nl، pl، pt-BR، tr، vi، id، ru، uk، ar، hi، ja، ko، zh-CN). أصبح كل ملف <code>.ftl</code> يحلّ المفاتيح الـ 557 نفسها؛ ويتحقق اختبار التزامن الجديد <code>tests/unit/i18n.test.ts</code> من ذلك في كل تشغيل لـ CI.","changelog.3b3366de3c39":"<strong>تحويل المكوّنات.</strong>","changelog.c65098e5c147":"يكتسب <code>menu_spec.ts</code> مفتاح <code>l10n</code> في كل <code>MenuItemSpec</code> و<code>MenuSubmenu</code>، إضافةً إلى <code>hintL10n</code> لتلميحات التمرير في شريط الحالة. ويحلّها <code>MenuBar.svelte</code> عبر الدالتين المساعدتين <code>labelOf(spec)</code> / <code>hintOf(spec)</code> اللتين تعودان إلى <code>label</code>/<code>hint</code> الحرفيين حين لا يوجد مفتاح ترجمة.","changelog.ef3a0f5b03d9":"يعرض FirstRunWizard عنوانه، وعدد الخطوات، وعنوان كل خطوة + تلميحها، وبطاقات السمات، وأزرار رجوع/التالي/إنهاء عبر <code>t()</code>. كانت خطوة مفتاح الاختصار قد أُزيلت بالفعل في جولة سابقة على المعالج؛ وتبقى تهيئة مفتاح الاختصار في الإعدادات ← لوحة المفاتيح.","changelog.4124e2c07aee":"يستخدم StatusBar الدالة <code>t()</code> لمقطع مرحلة الفهرس («تمت الفهرسة (N ملف)» / «جارٍ الفهرسة… N/M» / «متوقّف مؤقتًا» / «خطأ»)، وصيغ الجمع لعدد النتائج (<code>status-result-count-one</code> مقابل <code>…-many</code>)، وشارة حجم المحدّد، وتوقيت الاستعلام، وشارات توقيت العدسات، ومقطع قاعدة البيانات المحلية / نقطة النهاية البعيدة. وأصبحت <code>aria-label</code> لزر تدوير السمات وتلميح مفتاح الاختصار عند التمرير قابلين للترجمة.","changelog.a3b5fe09b103":"نافذة الإعدادات — <code>SettingsDialog.svelte</code> و<code>SettingsTreeNav.svelte</code> و<code>SettingsButtonBar.svelte</code> و<code>LocalePanel.svelte</code>، إضافةً إلى اللوحات في مجموعات الفهارس والعدسات والشبكة ومتفرقات (الواجهة / الرئيسية / البحث / النتائج / العرض / قائمة السياق / الخطوط والألوان / لوحة المفاتيح / الفهارس-المستوى الأعلى / وحدات التخزين / المجلدات / قوائم الملفات / الاستبعاد / اسم الملف / المحتوى / الصوت / التشابه / مخصّص / HTTPS / ETP / السجل / الخصوصية / السجلات / النسخ الاحتياطي / حول).","changelog.f3afe9f2e294":"الإشارات المرجعية، وجزء المعاينة، وعناصر التحكم في الحالة الفارغة / الطيّ في <code>LensSection</code>.","changelog.7ad5ec734228":"<strong>أصبح الاتجاه من اليمين إلى اليسار (RTL) تلقائيًا، لا مربع اختيار.</strong>","changelog.adaca56bf336":"أُزيل مربع الاختيار «معاينة من اليمين إلى اليسار» من الإعدادات ← اللغة والمنطقة. يُطبَّق RTL تلقائيًا للغات التي يُكتب نصها الأصلي من اليمين إلى اليسار — وحاليًا <code>ar</code> هي اللغة الوحيدة بين لغات الإصدار في هذه الفئة. يرجع <code>applyRtlForLocale</code> إلى قائمة السماح الداخلية <code>RTL_LOCALES</code>؛ ويبقى الحقل <code>locale_settings.rtl_preview</code> في <code>bootstrap.ts</code> ضمن الحالة المحفوظة للتوافق مع الإصدارات السابقة، لكن الواجهة لم تعد تعرضه.","changelog.b2a93dfa6039":"<strong>الاختبارات.</strong>","changelog.cd3c3612b144":"يغطي الملف الجديد <code>tests/unit/i18n.test.ts</code>: (a) أن النمط (glob) حمّل فعلًا اللغات الـ 18 كلها، (b) أن <code>bundleFor(code)</code> يُرجع حزمة تحلّ مفتاحًا اختباريًا (canary) لكل لغة، (c) أن اللغات الـ 18 في تزامن تام في مجموعة المفاتيح، (d) أن تبديل <code>settingsStore.state.locale</code> يغيّر ما تُرجعه <code>t()</code>، (e) أن اللغة غير المعروفة تعود إلى <code>en</code> بدلًا من سلسلة المفتاح الخام، (f) أن المفتاح غير المعروف يُرجع المفتاح نفسه.","changelog.82baaedc9013":"جولة تحسين المرحلة 12 — تجربة المستخدم، والموثوقية، والتطبيق الفوري (2026-05-11)","changelog.2907b565b163":"جولة سلوكية كبرى خلال جلسة تصحيح طويلة. معظم الإصلاحات مكاسب مباشرة في التكافؤ مع voidtools-Everything، إضافةً إلى أعمال الموثوقية الأساسية التي تجعل تشغيل تطبيق سطح المكتب مرارًا أثناء التطوير أمرًا مريحًا.","changelog.f8b766536c97":"<strong>نسخة واحدة + إقلاع غير حاجب للخدمة الخلفية.</strong>","changelog.e7d0360bc90d":"يعمل <code>kill_other_freally_instances()</code> في بداية <code>run()</code> على Windows (أمر taskkill <code>/F /T</code> على <code>freally-ui.exe</code> + <code>freally-indexd.exe</code>، مع تصفية معرّفات العمليات PID ≠ العملية الحالية) فتبدأ إعادة تشغيل التطبيق دائمًا من صفحة نظيفة دون إنهاء العمليات يدويًا. ونسخة بديلة فارغة (stub) لـ macOS / Linux من أجل التكافؤ.","changelog.a731267547b9":"أصبح <code>Daemon::boot</code> يُنشئ خيطًا مخصّصًا <code>freally-daemon-boot</code> داخل <code>tauri::Builder::setup</code>؛ فيعود خطّاف الإعداد فورًا وتظهر النافذة على الفور. في السابق كانت إعادة تشغيل المخزن المرجعي قادرة على حجب خيط الواجهة الرسومية لمدة 10-15 s، فيُطلق ذلك مراقب Windows للنوافذ غير المستجيبة وتُهدم العملية قبل وجود أي HWND.","changelog.59d90e38c9ea":"يُغلَّف <code>Client::connect</code> بحلقة إعادة محاولة 500 × 40 ms على جانب المستهلك، كي لا يخسر إقلاع بطيء للخدمة الخلفية أمام سباق اتصال واحد.","changelog.2f85875a08d3":"<strong>شرائح عوامل التصفية + قائمة البحث — تحديد متعدد مع تركيب بـ OR.</strong>","changelog.9f34cca2f956":"يحتفظ الملف الجديد <code>lib/stores/type_filter.svelte.ts</code> بـ <code>Set&lt;TypeFilterId&gt;</code>؛ والقيمة الافتراضية هي المجموعة الكاملة (وضع «الكل»). يُصدر <code>toQueryFragment()</code> مجموعة <code>(audio: OR video: OR …)</code> على مستوى المحلّل للتحديدات الجزئية، وسلسلة فارغة لـ «الكل» أو «لا شيء»، فتزول مشكلة AND بين البادئات على جانب الخدمة الخلفية.","changelog.8adb4f889882":"تبدّل شرائح <code>QuickFiltersPalette.svelte</code> المخزن مباشرةً؛ وتتحوّل عناصر القائمة في <code>Search → …</code> من <code>radio</code> إلى <code>checkable</code>، مع قراءة <code>MenuBar.isItemChecked</code> للمخزن. تُشتقّ «الكل» من <code>selected.size === ALL.length</code> — والنقر على أي شريحة منفردة يُطفئ تلك الشريحة و«الكل» معًا، ويُبقي الأخرى.","changelog.5246ff18704a":"يحفظ <code>bookmarks.add</code> مجموعة عوامل التصفية النشطة إلى جانب نص البحث؛ ويكتسب كائن نقل البيانات <code>Bookmark</code> في Rust الحقل <code>filters: Vec&lt;String&gt;</code> مع <code>#[serde(default)]</code> كي تستمر ملفات <code>bookmarks.json</code> القائمة في إلغاء التسلسل. والنقر على إشارة مرجعية يستعيد محتوى مربع النص (عبر <code>queryStore.setSource</code>) وتحديد الشرائح (عبر <code>typeFilterStore.setFromIds</code>) كليهما.","changelog.942a0601c778":"أُصلح رمز «أرشيف»: <code>compressed: &quot;zip:&quot;</code> → <code>&quot;archive:&quot;</code> (الاسم البديل الحقيقي لـ <code>QuickFilter::Archive</code> من <code>freally-query::quick_filters</code>). كان <code>zip:</code> القديم مجرد امتداد ضمن المجموعة، فلم يكن «أرشيف» يطابق أي شيء.","changelog.6de9bf011469":"<strong>استعلام «الكل» الأولي + التكافؤ في وضع «الكل».</strong>","changelog.29e61abbcb91":"يُطلَق <code>runInitialEverythingQuery()</code> في <code>bootstrap.ts</code> مرة واحدة بعد التحميل الأولي (hydrate) ويستطلع <code>resultsStore.batches.length</code> لمدة تصل إلى 60 × 800 ms، ولا يطلق استدعاءات <code>run()</code> جديدة إلا حين لا يكون هناك شيء قيد التنفيذ، كي لا يُلغي الإطلاق التلقائي استعلاماته هو. أصبح أول رسم بعد التشغيل يعرض النتائج فورًا بدلًا من «اكتب استعلامًا للبدء.»","changelog.c323e4a1d454":"عندما تكون مجموعة عوامل تصفية الأنواع محدّدة بالكامل ومربع البحث فارغًا، يركّب <code>resultsStore.run()</code> حرف بدل مجرّدًا <code>*</code> فتسرد عدسة أسماء الملفات كل إدخال مفهرس (تكافؤ مع voidtools-Everything).","changelog.2c27ce8face6":"حُدّثت بوابة العنصر النائب في <code>ResultList.svelte</code>: لا تعرض «اكتب استعلامًا للبدء» إلا حين يكون المصدر فارغًا ولا يكون أي عامل تصفية للأنواع محدّدًا (أي أن المستخدم ألغى تحديد كل الشرائح صراحةً).","changelog.28ad0f2414d6":"<strong>فهرسة المجلدات.</strong>","changelog.c21ab8d7106b":"أصبح <code>crates/freally-indexd/src/scanner.rs::scan_folder</code> يفهرس المجلدات إلى جانب الملفات؛ ويصفّي مسار walkdir على <code>is_file() || is_dir()</code> ويختم <code>FILE_ATTRIBUTE_DIRECTORY (0x10)</code> في حقل <code>attrs</code> لحدث سجل التغييرات.","changelog.799bfffa54d6":"لم يعد مسار التمهيد من MFT في <code>crates/freally-journal-win/src/subscriber.rs</code> يتخطّى سجلات المجلدات — فهي تمرّ الآن مع قناع البتّات الحقيقي <code>file_attributes</code> الخاص بها سليمًا.","changelog.709c7429febd":"يكتسب <code>QueryHit</code> (كائن نقل البيانات في Rust + واجهة TS المقابلة) الحقل <code>attrs: u32 #[serde(default)]</code> الذي تملؤه الخدمة الخلفية من <code>FileRow.attrs</code>. وتميّز الواجهة بين الملف والمجلد عبر البتّ <code>0x10</code>.","changelog.694ce7c4310f":"<strong>أيقونات صدفة Windows الحقيقية + العرض لكل صف.</strong>","changelog.4479cd257069":"ملف جديد <code>apps/freally-ui/src-tauri/src/commands/icons.rs</code> — أمر Tauri غير متزامن <code>icon_for_ext(ext, is_dir) -&gt; Option&lt;String&gt;</code> يشغّل <code>SHGetFileInfoW</code> من Win32 مع <code>SHGFI_USEFILEATTRIBUTES</code> (فيحلّ مسارٌ وهمي مثل <code>_.xml</code> أيقونةَ المعالج المسجَّل دون أن يكون الملف موجودًا فعلًا على القرص)، ثم <code>GetIconInfo</code>، ثم BGRA بعمق 32 بت عبر <code>GetDIBits</code>، ثم تبديل القنوات BGRA→RGBA، ثم PNG عبر حزمة <code>image</code>، ثم عنوان بيانات base64. يُرجع <code>None</code> على macOS / Linux في الوقت الحالي.","changelog.6794e87b4eb5":"<code>src-tauri/Cargo.toml</code>: يضيف <code>image = &quot;0.25&quot; --no-default-features --features png</code> و<code>base64 = &quot;0.22&quot;</code> ومجموعة الميزات المعنية من <code>windows = &quot;0.59&quot;</code> تحت <code>cfg(windows)</code>.","changelog.9e73805e7e38":"ملف جديد <code>lib/stores/icon_store.svelte.ts</code> — ذاكرة مؤقتة <code>Map&lt;(ext, is_dir), Promise&lt;dataUrl | null&gt;&gt;</code> فتُطلق 200 صف من النتائج استدعاء IPC واحدًا لكل امتداد فريد، لا لكل صف. وحقل تفاعلي <code>tick</code> يزداد مع كل حلّ كي يُعاد عرض المستهلكين عبر $derived.","changelog.872e5a605907":"يعرض عمود الاسم في <code>ResultRow.svelte</code> العنصر <code>&lt;img class=&quot;row-icon&quot; src=…&gt;</code> المأخوذ من <code>iconStore.get(hit.ext, isDir)</code>، مع رمز تعبيري احتياطي (<code>📁</code> / <code>📄</code>) أثناء تحميل عنوان البيانات.","changelog.eb2ed58a295d":"<strong>بيانات وصفية حقيقية في التمهيد من MFT.</strong>","changelog.392710a87044":"تحمل سجلات USN معرّف FRN + السمات + طابعًا زمنيًا واحدًا لكن دون حجم الملف، فكان المسار السريع عبر MFT يكتب <code>size: 0</code> وطابعًا زمنيًا مأخوذًا من USN فقط في الفهرس. أصبح <code>subscriber.rs</code> يجري <code>std::fs::metadata(&amp;full)</code> لكل حدث صادر لملء القيم الحقيقية <code>len</code> و<code>modified</code> و<code>created</code>. هذا أبطأ من المرور الخالص على USN لكنه صحيح — فأخيرًا يعرض عمودا «الحجم» و«آخر تعديل» قيمًا غير صفرية دون فرض اللجوء إلى walkdir.","changelog.693e07211105":"<strong>مظهر مربع البحث + صفوف النتائج.</strong>","changelog.660ce86cdba0":"أصبح <code>SearchBar.svelte</code> يربط <code>&lt;input value={queryStore.source}&gt;</code> فتنعكس التحديثات البرمجية (النقر على إشارة مرجعية، والمسح بـ Escape، والروابط العميقة مستقبلًا) في مربع النص. وأُسقطت أيضًا القاعدة المعطوبة <code>color: transparent</code> على <code>.raw</code> (لم تكن طبقة «المرآة» لتلوين الصيغة متحاذية، فكان النص المكتوب غير مرئي فعليًا في الوضع الداكن) — أصبح حقل الإدخال يعرض نصه بنفسه والمرآة مخفية.","changelog.40ca8d425ec9":"أصبحت أنماط CSS للصفوف في <code>ResultRow.svelte</code> تقرأ <code>--row-{state}-fg/bg/weight/style</code>، فتعمل عناصر التحكم لكل حالة في لوحة «الخطوط والألوان» مباشرةً. الحالات الموصولة: normal، وhighlighted (التمرير)، وselected، وselected_highlighted.","changelog.5442f7a05dd7":"أُصلح خلل في أولوية المحددات (specificity) بين الصفوف المتناوبة والتمرير كان يجعل الصف المحدّد يبدو غير محدّد حين تتفوّق قاعدته <code>:nth-child(even)</code> على <code>.row.selected</code>. أصبح لكلا المحددين <code>:not(.selected)</code>، فيحتفظ الصف المحدّد بصبغته السماوية بغض النظر عن ترتيبه أو التمرير فوقه.","changelog.1e3c5fb60489":"<strong>التطبيق الفوري والحفظ لـ «الخطوط والألوان».</strong>","changelog.99c1c70df3e3":"تكتب الدالة الجديدة <code>lib/stores/fonts_apply.svelte.ts::applyFontsAndColors()</code> خصائص CSS مخصّصة على <code>&lt;html&gt;</code> من <code>settings.fonts_and_colors</code>: <code>--font-ui</code> (مع سلسلة خطوط احتياطية عبر أنظمة التشغيل)، و<code>--app-font-size</code>، و<code>--row-…-fg/bg/weight/style</code> لكل حالة، وتجاوزات <code>--lens-…</code> لكل عدسة. تُستدعى مرة عند الإقلاع (بعد التحميل الأولي) ومرة أخرى مع كل تعديل في اللوحة — فتُستعاد عبر مرات التشغيل وتُطبَّق فورًا عند التغيير.","changelog.bd2af6cb049b":"تحوّل حقل إدخال الخط في <code>FontsAndColorsPanel.svelte</code> إلى قائمة منسدلة <code>&lt;select&gt;</code> تُملأ عبر <code>window.queryLocalFonts()</code> (واجهة Local Font Access API التي يدعمها وقت تشغيل WebView2 في Tauri 2 على Windows) مع قائمة احتياطية منتقاة من 25 عائلة خطوط لمحرّكات webview غير المبنية على Chromium. يُعرض كل خيار بخطه الخاص كمعاينة مرئية.","changelog.0f1775f6dcaa":"تستدعي القائمة المنسدلة للسمة في UIPanel الدالة <code>themeStore.set(value)</code> إلى جانب تعديل الإعدادات، فيُطبَّق التبديل بين الفاتح والداكن فور الاختيار — دون حاجة إلى «تطبيق» أو إعادة تشغيل.","changelog.e689bf04af40":"<strong>توصيل مفاتيح التبديل في لوحة «العرض».</strong>","changelog.af26fe7a3745":"يعكس $effect في App.svelte إعدادات منتقاة على سمات <code>&lt;body data-*&gt;</code>؛ وتتفاعل معها قواعد CSS جديدة في <code>app.css</code>: <code>data-alternate-rows</code>، و<code>data-row-mouseover</code> (يجعل <code>.row:hover</code> بلا أثر حين تكون قيمته false)، و<code>data-show-tooltips</code>، و<code>data-show-lufs-badges</code>، و<code>data-show-similarity-score</code>.","changelog.ba63c32bf658":"أصبح <code>title={hit.path}</code> في صف <code>ResultRow</code> مشروطًا بإعداد «إظهار التلميحات».","changelog.be551e42463a":"يحترم <code>formatBytes</code> إعداد «تنسيق الحجم» (<code>auto_binary</code> | <code>bytes</code> | <code>kb</code> | <code>mb</code> | <code>gb</code>).","changelog.eb09c95dc5e6":"<strong>عناصر التحكم في النافذة — البقاء في المقدّمة، والحجم، والتكبير.</strong>","changelog.f6f1716eda05":"يضيف <code>capabilities/default.json</code> التصاريح المفقودة <code>core:window:allow-set-size</code> و<code>core:window:allow-set-always-on-top</code> و<code>core:window:allow-set-resizable</code> و<code>core:window:allow-inner-size</code> و<code>core:window:allow-outer-size</code>. فبدونها كانت بوابة أذونات IPC في Tauri ترفض بصمت كل استدعاء لـ <code>setSize</code> / <code>setAlwaysOnTop</code>.","changelog.b60bdf35fa6a":"يكتسب App.svelte تأثير <code>$effect</code> يترجم <code>settings.on_top</code> + <code>queryStore.source</code> إلى استدعاءات <code>setAlwaysOnTop(...)</code>: أوضاع «أبدًا» / «دائمًا» / «أثناء البحث» تعمل كلها، ويُعاد تطبيقها مع كل تغيير في الإعدادات ومع كل ضغطة مفتاح. وتُستعاد عند التشغيل.","changelog.1f927e0b3720":"أُصلح استيراد <code>setWindowSize</code>: يأتي <code>LogicalSize</code> من <code>@tauri-apps/api/window</code>، لا من <code>@tauri-apps/api/dpi</code> غير الموجود. والحجم المختار يكتب أيضًا <code>settings.window_size = { w, h }</code> (المسموح به في <code>ALLOWED_PATCH_KEYS</code>)، ويستعيد الإقلاع الحجم المحفوظ عند التشغيل التالي.","changelog.293b3c2deb7d":"انتقل <code>zoomStore</code> من <code>document.documentElement.style.fontSize</code> إلى خاصية CSS <code>zoom</code> في WebView، فأصبح Ctrl+= / Ctrl+- يعيدان تحجيم الواجهة (المبنية بوحدات px) فعلًا. بوضوح تام في كل المعاملات.","changelog.7e52e273d7e8":"<strong>معاينة الصور.</strong>","changelog.6aa7a3ed566b":"يُرجع <code>preview/windows_host.rs::preview</code> عناوين بيانات حقيقية للصور بصيغ PNG وJPG/JPEG/JFIF وGIF وWEBP وBMP وSVG وICO وAVIF: يقرأ الملف (بحدّ أقصى 4 MiB)، ويرمّزه عبر <code>commands::files::base64_encode</code>، ويُرجع <code>PreviewPayload { kind: Image, data_url: &quot;data:image/…;base64,…&quot; }</code>. ولا تزال الامتدادات غير الصورية تُرجع <code>None</code> فتعالج الملفاتَ النصية آليةُ عرض بداية النص الاحتياطية.","changelog.d2769be53d10":"أصبحت <code>files_preview</code> و<code>files_thumbnail</code> و<code>icon_for_ext</code> دوال <code>async fn</code> تُحيل العمل الفعلي إلى <code>tokio::task::spawn_blocking</code>. كانت النسخ المتزامنة تحجب خيط توزيع IPC في Tauri لثوانٍ أثناء استخراج أيقونات الصدفة + ترميز base64 لعدة ميغابايتات، ما كان يجمّد الواجهة بأكملها.","changelog.2e8adf41da90":"أُصلح استدعاء <code>PreviewPane.svelte</code> لدالة مفقودة هي <code>files.whitelistUserChosen</code> — كانت الدالة المساعدة موجودة في <code>ipc/bookmarks.ts</code> بينما يستورد الجزء <code>* as files from &quot;ipc/files&quot;</code>. أُعيد تصدير <code>whitelistUserChosen</code> من <code>ipc/files.ts</code> كي يُحَلّ الاستدعاء؛ فقد كان <code>TypeError</code> المتزامن يترك <code>loading = true</code> إلى الأبد ويحجب $effect الخاص بالمعاينة.","changelog.932173fca555":"أُضيفت جولة تتبّع (tracing) في Rust على مسارات المعاينة / الأيقونات، إضافةً إلى أمر Tauri باسم <code>log_event</code> لتمرير أحداث وحدة تحكم TS إلى سجل التطوير في cargo، و<code>std::panic::set_hook</code> يُظهر حالات الذعر (panic) في Rust في وحدة التحكم.","changelog.6ef1e2ccf454":"<strong>نقطة نهاية FTP + أمر «قطع الاتصال» المعطّل بالرمادي.</strong>","changelog.5b6f4670d959":"ملف جديد <code>ConnectEndpointDialog.svelte</code> على غرار نافذة الحوار في voidtools: المضيف (مطلوب)، والمنفذ (افتراضيًا 21)، واسم المستخدم، وكلمة المرور، وقائمة منسدلة لنوع الاتصال. عند الضغط على «موافق» يكتب <code>settings.endpoint = { name: host, kind: &quot;ftp&quot; }</code>.","changelog.93d8e6c9ea7d":"يُرجع <code>MenuBar.isItemEnabled</code> القيمة <code>false</code> لـ <code>tools.disconnect_endpoint</code> عندما يكون <code>settings.endpoint.kind === &quot;local&quot;</code>؛ ويضيف CSS نمطًا رماديًا <code>.item.disabled</code> مع <code>pointer-events: none</code>.","changelog.dc6508212cbc":"أصبح <code>View → Filters</code> يحدّد لوحة <code>indexes.exclude</code> مسبقًا قبل فتح نافذة الإعدادات (تكافؤ مع voidtools-Everything).","changelog.8886320c4765":"<strong>الاستبعادات — فئات امتدادات قابلة للتبديل + إزالة التكرار.</strong>","changelog.66be911445f7":"أصبحت أزرار فئات الامتدادات في <code>ExcludePanel.svelte</code> (فيديو / صوت / صورة / أرشيف / ملف تنفيذي) قابلة للتبديل: النقر يضيف أنماط glob الخاصة بالفئة ويُبرز الزر؛ والنقر مجددًا يزيلها ويلغي الإبراز. وتُحسب حالة «نشط» على أنها «كل نمط glob في الفئة موجود حاليًا في مجموعة الملفات المستبعدة»، فيعكس الإبراز الحالة الحقيقية لا مجرد آخر نقرة.","changelog.b4936ee1d7c7":"يزيل كلٌّ من <code>Add Folder…</code> و<code>Apply OS-recommended excludes</code> التكرار، فلا يُضاف الإدخال نفسه مرتين أبدًا.","changelog.fd67542ffabe":"<strong>موثوقية الإشارات المرجعية.</strong>","changelog.07a8ba50f22e":"لم يعد <code>bookmarks.add</code> يتطلب استعلامًا غير فارغ — فالإشارات المرجعية ذات الاستعلام الفارغ مسموح بها (بالاسم «Bookmark N» كي يستطيع المستخدم إعادة تسميتها في نافذة التنظيم). أصبح مفتاح إزالة التكرار الآن (الاسم، الاستعلام، مجموعة عوامل التصفية).","changelog.eccef664591a":"يعيد <code>bookmarksStore.hydrate()</code> المحاولة كل 500 ms لمدة تصل إلى ~10 s، كي لا يفقد التحميل الأولي قائمة الإشارات المرجعية بسبب خطأ IPC ناتج عن عدم جاهزية الخدمة الخلفية خلال فترة الإقلاع في الخلفية.","changelog.002b1009c89f":"يعيد <code>bookmarks.organize</code> التحميل قبل فتح نافذة «تنظيم الإشارات المرجعية»، كي لا تعرض قائمة منسدلة قديمة «لا توجد إشارات مرجعية بعد.» بينما توجد إشارات مرجعية على القرص.","changelog.c399ec40a64b":"<strong>متفرقات.</strong>","changelog.0437b05ad147":"رُفع المرشّح الافتراضي لـ <code>tracing_subscriber</code> إلى <code>warn,freally=info,freally_ui_lib=info,freally_indexd=info</code> كي تظهر أدوات القياس دون فرض <code>RUST_LOG</code>.","changelog.64b28a5c4c3d":"أصبحت <code>markDirty</code> في نافذة الإعدادات تستدعي أيضًا <code>applyFontsAndColors()</code> داخل مسار تعديل لوحة «الخطوط والألوان»، فتكون المعاينة فورية.","changelog.1f355d627a40":"يكتسب <code>ipc/types.ts::QueryHit</code> الحقل <code>attrs?: number</code>؛ ويكتسب <code>Bookmark</code> الحقل <code>filters?: string[]</code>. وكلاهما اختياري للتوافق مع الإصدارات اللاحقة.","changelog.3df684c915d5":"<strong>[كل المنصّات]</strong> المرحلة 12: نافذة الإعدادات + IPC حقيقي مع الخدمة الخلفية + إطار عمل المُستخرِجات المخصّصة + التدويل. تستبدل طبقة IPC الوهمية من المرحلة 11 بطبقة نقل JSON-RPC حقيقية مسبوقة بالطول عبر <code>freally-rpc</code> فوق مقبس Unix / أنبوب مسمّى (named pipe) لكل مستخدم، وتُدخل نافذة الإعدادات الكاملة وفق PRD §8.1-§8.27 إضافةً إلى مضيف المُستخرِجات المخصّصة المعزول في بيئة Wasm.","changelog.cbb79fe44d28":"<strong>حزمة جديدة <code>freally-rpc</code></strong> (تحت <code>crates/freally-rpc/</code>) — الأساس الذي يتيح لواجهة Tauri ولواجهة سطر الأوامر الجديدة <code>freally</code> التحدث بالبروتوكول نفسه مع نسخة واحدة من <code>freally-indexd</code>.","changelog.b4d3e8bb408c":"<code>frame.rs</code>: تأطير مسبوق بالطول بصيغة u32-BE مع حدّ أقصى صارم للحمولة قدره 16-MiB، كي لا يستطيع طرف عدائي استنزاف ذاكرة الخادم (OOM) ببادئة طول واحدة قدرها 4-GiB.","changelog.9eee30718562":"<code>jsonrpc.rs</code>: أغلفة JSON-RPC 2.0 للطلب / الاستجابة / الإشعار؛ ويميّز التعداد غير الموسوم <code>ResponseEnvelope</code> الإطار الواحد على أنه إما استجابة وإما إشعار يدفعه الخادم.","changelog.3cae329c5ea1":"<code>service.rs</code>: السمة (trait) <code>Service</code> التي يطبّقها <code>freally-indexd</code>؛ ويتيح <code>NotificationSink</code> لمعالج الأسلوب دفع إشعارات غير متزامنة عبر الاتصال نفسه.","changelog.a60b3df0f5d6":"<code>server.rs</code>: حلقة قبول لكل اتصال مع طابور صادر محدود (<code>PER_CONN_OUT_QUEUE = 256</code>)؛ تُنشئ مهمة كتابة لكل اتصال ومهمة تجميع للإشعارات تمرّر كائنات <code>Notification</code> إلى طابور الكاتب. ويعرض <code>handle_connection_for_tests</code> جسم الحلقة نفسه فوق <code>tokio::io::duplex</code> لاختبارات تكامل تستغرق أقل من ثانية.","changelog.829538dc4efb":"<code>client.rs</code>: استدعاء محدّد النوع <code>ClientHandle::call()</code> مع قناة رد أحادية الاستخدام (oneshot) لكل استدعاء؛ ويُرجع <code>notifications()</code> اشتراك بثّ في tokio. وتُنهي مهمة القارئ المستدعين المعلّقين بشكل نظيف <code>transport closed</code> عند EOF.","changelog.91eab238f9d7":"<code>transport/unix.rs</code>: يقرأ <code>UnixListener::accept_authenticated()</code> بيانات اعتماد الطرف المقابل عبر <code>tokio::net::UnixStream::peer_cred()</code> ويرفض أي طرف لا يطابق UID الخاص به العملية الحالية — ومع وضع الملف 0600 المضبوط في <code>listen()</code>، يعني هذا أن مستخدمًا غريبًا على الجهاز نفسه لا يستطيع الاتصال حتى لو عرف المسار. وتُضبط أذونات المجلد الأب على 0700 عبر chmod كاحتياط إضافي.","changelog.fcfcdf081a40":"<code>transport/windows.rs</code>: <code>ServerOptions::create_with_security_attributes_raw</code> مع SECURITY_DESCRIPTOR مولَّد من سلسلة SDDL بالصيغة <code>D:(A;;GA;;;&lt;userSid&gt;)(A;;GA;;;SY)</code> — فلا يملك مدخل Access-Allowed ACE إلا المستخدم الحالي (المُحدَّد عبر <code>OpenProcessToken</code> + <code>GetTokenInformation(TokenUser)</code> + <code>ConvertSidToStringSidW</code>) وSYSTEM. لا <code>Everyone</code> ولا <code>Authenticated Users</code>. ويحجب <code>reject_remote_clients(true)</code> الوصول إلى الأنبوب عبر الشبكة. ويُغلَّف <code>LocalFree</code> بحارس RAII هو <code>SdDrop</code> فيُحرَّر واصف الأمان حتى في مسارات الخطأ ذات العودة المبكرة.","changelog.336f8a676048":"<code>path.rs</code>: المسار الافتراضي المتعارف عليه للمقبس / الأنبوب لكل نظام تشغيل. macOS: <code>~/Library/Application Support/freally/indexd.sock</code>. Linux: <code>$XDG_RUNTIME_DIR/freally/indexd.sock</code> مع <code>~/.local/share/freally/indexd.sock</code> كبديل احتياطي. Windows: <code>\\\\.\\pipe\\freally-indexd-&lt;userSid&gt;</code> (موسوم بالمعرّف SID كي يحصل مستخدمان على مضيف Windows نفسه على أنبوبين منفصلين).","changelog.81b6aadfed10":"<code>dto.rs</code>: كائنات نقل بيانات (DTO) عبر serde تطابق <code>apps/freally-ui/src/lib/ipc/types.ts</code> بايتًا ببايت — متغيّرات التعداد نفسها <code>serde(rename_all = &quot;lowercase&quot;)</code>، و<code>serde(rename = &quot;type&quot;)</code> نفسه لمفتاح JSON المسمّى <code>kind</code>، وأشكال الحقول نفسها. ويؤكّد تدقيق التكافؤ في المرحلة 12 ثبات مخرجات JSON على مستوى البايت مقابل بيانات اختبار محفوظة في المستودع.","changelog.022aca1457de":"<strong>حزمة جديدة <code>freally-extractor-host</code></strong> (تحت <code>crates/freally-extractor-host/</code>) — إطار عمل المُستخرِجات المخصّصة المعزولة في بيئة Wasm. غير موثوقة افتراضيًا وفق نموذج الثقة في المرحلة 12.","changelog.9b6d93374feb":"<code>manifest.rs</code>: مخطط TOML يتضمن <code>id</code> و<code>display_name</code> و<code>version</code> و<code>formats: Vec&lt;String&gt;</code> و<code>magic: Vec&lt;String&gt;</code> الاختياري (مواصفات بايتات ست عشرية فقط مثل <code>&quot;0x23 0x20&quot;</code>) و<code>sidecar</code> (مسار الملف الثنائي <code>*.wasm</code>، ويُتحقق من وجوده وقت التحميل) و<code>time_budget_ms</code> (افتراضيًا 1000) و<code>memory_budget_mb</code> (افتراضيًا 64). تُرفض مواصفات البايتات السحرية (magic) غير الصالحة وقت التحميل.","changelog.bca0da3b05e5":"<code>registry.rs</code>: فاحص لـ <code>&lt;index_root&gt;/extractors/</code> يحمّل <code>manifest.toml</code> من كل مجلد فرعي. يسجّل <code>registry.toml</code> حالة الثقة التي حدّدها المستخدم لكل مُستخرِج، وتجزئات blake3 لكشف العبث، وعدّاد تعطّلات يعطّل تلقائيًا أي مُستخرِج يتعطّل 3 مرات متتالية أو أكثر حتى يمنحه المستخدم الثقة مجددًا. يجري الحفظ بالكتابة في ملف مؤقت ثم إعادة التسمية عبر <code>toml::to_string_pretty</code>. ويمسح <code>set_trusted</code> عدّاد التعطّلات عند إعادة منح الثقة.","changelog.b8bcebf716a9":"<code>sandbox.rs</code>: مضيف <code>wasmtime</code> بضمانات صارمة — يفرض <code>Config::consume_fuel(true)</code> ميزانية معالج لكل استدعاء (<code>fuel = time_budget_ms × 1_000_000</code>)؛ ويفرض فحص <code>Memory::data_size</code> بعد الاستدعاء ميزانية الذاكرة لكل استدعاء. لا يرى الضيف إلا دالتين من دوال المضيف: <code>host_log(ptr: i32, len: i32)</code> (تسجيل للتصحيح، يُقتطع عند 4 KiB) و<code>host_now_ms() -&gt; i64</code> (يحقنها المضيف، وتطابق <code>now_ms</code> الخاص بالطلب كي لا يستطيع الضيف رصد الوقت الفعلي بشكل مستقل). لا <code>wasi:sockets</code>، ولا <code>wasi:filesystem-write</code>، ولا <code>wasi:clocks</code>. يصدّر الضيف <code>alloc(size) -&gt; i32</code> و<code>extract(ptr, len) -&gt; i64</code> (البتّات الـ 32 العليا = مؤشر النتيجة، والبتّات الـ 32 الدنيا = طول النتيجة). وحدّ أقصى قدره 16-MiB لطول النتيجة كي لا يستطيع ملف مرافق (sidecar) عدائي إرجاع كتلة بحجم 4-GiB.","changelog.c9d6d857a602":"<strong>إعادة هيكلة <code>freally-indexd</code> إلى مكتبة + ملف تنفيذي.</strong> يصبح الملف التنفيذي الخاص بالخدمة فقط من المراحل 1-3 مكتبةً + غلافًا رقيقًا. تعرض المكتبة <code>DaemonState</code> (حاوية الحالة المشتركة التي تحمل <code>Arc&lt;Index&gt;</code> و<code>Arc&lt;AudioCache&gt;</code> و<code>Pipeline</code> و<code>Registry</code>، إضافةً إلى إعدادات <code>volumes / folders / excludes / network / history</code> المحفوظة في <code>&lt;index_root&gt;/config/</code> كملفات TOML) و<code>IndexdService</code> (تنفيذ <code>Service</code> الذي يوزّع كل أسلوب مذكور في PRD §8.30). وحدات جديدة:","changelog.2d2defa4d194":"<code>service.rs</code>: توزيع محدّد النوع لـ <code>query.run</code> / <code>query.cancel</code> / <code>query.lens_timings</code> / <code>index.state</code> / <code>index.verify</code> / <code>index.compact</code> / <code>index.rebuild</code> / <code>extractors.list</code> / <code>extractors.set_mode</code> / <code>volumes.list</code> / <code>volumes.update</code> / <code>volumes.recreate_journal</code> / <code>volumes.reset_stream</code> / <code>volumes.upgrade_fanotify</code> / <code>volumes.remove</code> / <code>folders.list</code> / <code>folders.add</code> / <code>folders.remove</code> / <code>folders.update</code> / <code>folders.rescan</code> / <code>folders.rescan_all</code> / <code>excludes.get</code> / <code>excludes.set</code> / <code>network.status</code> / <code>network.start_https</code> / <code>network.stop_https</code> / <code>network.regen_token</code> / <code>network.start_api</code> / <code>network.stop_api</code> / <code>custom_extractors.list</code> / <code>custom_extractors.set_trusted</code> / <code>custom_extractors.refresh_hashes</code> / <code>history.get</code> / <code>history.set</code> / <code>history.clear</code> / <code>preview.text_head</code> / <code>preview.thumbnail</code> / <code>settings.apply</code> / <code>daemon.shutdown</code>. يبثّ <code>query.run</code> إشعارات <code>query:batch</code> / <code>query:done</code> إلى العميل (ويعيد جانب Tauri إصدارها كأحداث Tauri تستهلكها مخازن Svelte).","changelog.d58ec7a0cdfb":"<code>state.rs</code>: يفتح <code>DaemonState::open(opts)</code> الفهرس وذاكرة الصوت المؤقتة وسجلّ المُستخرِجات المخصّصة، ويقرأ ملفات TOML المحفوظة للإعدادات. ويكتبها <code>DaemonState::persist()</code> كلها مجددًا بشكل ذري. وتتولّى الأنواع <code>VolumesConfig</code> و<code>VolumeOverride</code> و<code>NetworkState</code> و<code>HistoryConfig</code> حفظ كل جزء.","changelog.089d7c21d524":"<code>volumes.rs</code>: اكتشاف وحدات التخزين عبر أنظمة التشغيل — على Windows يمرّ على <code>GetLogicalDrives</code> + <code>GetVolumeInformationW</code> + <code>GetDiskFreeSpaceExW</code> ويُصدر صفوف NTFS / ReFS / exFAT / FAT32؛ وعلى macOS يفحص <code>/Volumes</code> + <code>statvfs</code>؛ وعلى Linux يقرأ <code>/proc/mounts</code> (متخطيًا أنظمة الملفات الزائفة) + <code>statvfs</code>. يحمل كل صف معرّفًا ثابتًا <code>id</code> (مثل <code>win-C</code> و<code>lin-_home</code> و<code>mac-Macintosh_HD</code>) كي تصمد تجاوزات كل وحدة تخزين في رحلة الذهاب والإياب.","changelog.60cb08f577a8":"<code>settings.rs</code>: حمولة محدّدة النوع <code>SettingsApply</code> لاستدعاء <code>settings.apply</code> عبر IPC؛ تعدّل الخدمة الخلفية الحالة المعنية وتحفظها. ويُنتج <code>random_token_fingerprint()</code> البصمة القصيرة غير السرية المعروضة في لوحة «الشبكة».","changelog.17b91de7bef9":"<code>history.rs</code>: حمولة محدّدة النوع <code>HistoryUpdate</code> + خطّاف <code>take_clear</code> المعدّ للمرحلة 13 مستقبلًا لمسح السجل على جانب الخدمة الخلفية.","changelog.b566f0999042":"<strong>يصبح <code>apps/freally-ui/src-tauri</code> عميل RPC.</strong>","changelog.b3d45fd8ffa1":"حُذف <code>commands/canned.rs</code> (مجموعة البيانات الوهمية من المرحلة 11). ويحرس اختبار الدخان في المرحلة 12 <code>tests/smoke/phase_12_indexd_client.rs::no_canned_rs_in_tree</code> هذا الحذف من الانحدار.","changelog.a467ed4a6368":"ملف جديد <code>daemon.rs</code>: يُقلع نسخة <code>freally-indexd</code> داخل العملية على المسار الافتراضي للمقبس الخاص بكل نظام تشغيل (مع متغيّر البيئة <code>FREALLY_RPC_SOCKET</code> لتجاوزه في الاختبارات)، ويفتح عميل <code>freally-rpc</code>، ويُنشئ مهمة لإعادة إصدار الإشعارات تحوّل كل إشعار يدفعه الخادم إلى حدث Tauri عبر <code>app.emit(method, payload)</code>. ينسخ <code>Daemon::call/call_void</code> العميل ويشغّل الـ future على وقت تشغيل tokio الخاص بالخدمة الخلفية، متفاديًا تعارض النقل/الاستعارة الذي كان <code>Arc&lt;Daemon&gt;::block_on(async move {…})</code> سيُدخله.","changelog.2b8987c2135e":"<code>commands/query.rs</code> و<code>commands/index_state.rs</code> و<code>commands/extractors.rs</code>، إضافةً إلى الملفات الجديدة <code>commands/volumes.rs / folders.rs / excludes.rs / network.rs / custom_extractors.rs / history.rs</code> — أصبح جسم كل أمر Tauri يمرّ عبر الخدمة الخلفية. و<code>query_parse</code> هو الاستثناء الوحيد داخل العملية — فالتقطيع إلى رموز بمعدّل ضغطات المفاتيح لا يحتمل رحلة الذهاب والإياب إلى الخدمة الخلفية.","changelog.6a7142ad49d6":"يحتفظ <code>commands/files.rs</code> ببوابة المسارات المعروفة <code>verify_path</code> على جانب الواجهة، لكن <code>files_thumbnail</code> / <code>files_preview</code> أصبحا يفوّضان الوحدة الجديدة <code>preview</code> التي توزّع العمل على مضيفي المعاينة الأصليين لنظام التشغيل.","changelog.b19dfedad0ec":"يحتفظ <code>commands/settings.rs</code> بالحفظ المحلي المعتمد على JSON ويكتسب جدول HashMap باسم <code>#[serde(flatten)] extras</code> يلتقط الحقول العلوية للمرحلة 12 التي تزيد على 70 حقلًا دون تضخيم واجهة القيم محدّدة النوع؛ ويتوسّع <code>ALLOWED_PATCH_KEYS</code> ليغطي كل مفتاح جديد وفق عقد قائمة السماح الخاص بمراجعة الأمان؛ ويملأ <code>phase_12_default_extras()</code> القيم الافتراضية للمرحلة 12 فيأتي <code>settings.json</code> في التثبيت الجديد بكل الحقول. ولم يتغيّر عقد TS في <code>lib/ipc/types.ts</code>.","changelog.1469ccfaba03":"<strong>مضيفو المعاينة الأصليون لنظام التشغيل</strong> (<code>apps/freally-ui/src-tauri/src/preview/</code>). بنية وحدات المنصّات جاهزة؛ ويُفعَّل التكامل الكامل لكل مضيف تدريجيًا كتحسين لجودة تجربة المستخدم لا يغيّر عقد عناوين البيانات (data URL).","changelog.b4df5b094937":"<code>preview/macos.rs</code> — جسر QuickLook (<code>QLPreviewPanel</code> للمعاينة الكاملة، و<code>QLThumbnailGenerator</code> للصور المصغّرة). تشحن المرحلة 12 واجهة الوحدة والفحص وقت التشغيل؛ وتصل سلسلة استدعاءات <code>objc2</code> الكاملة كتحسين في جولة التحسين.","changelog.7c608576f7b1":"<code>preview/windows_host.rs</code> — معالجات المعاينة في الصدفة (<code>IPreviewHandler</code> + <code>IThumbnailProvider</code> عبر windows-rs). الموقف نفسه — الواجهة جاهزة، وجسر COM يُشحن تدريجيًا.","changelog.2350b7e13cc7":"<code>preview/linux.rs</code> — GNOME Sushi عبر DBus عند توفّره، وKDE KIO عبر استدعاء عملية فرعية عند توفّره. الاكتشاف فحص <code>gdbus introspect</code> / <code>kioclient5 --version</code> مخزّن مؤقتًا عبر <code>OnceLock</code>، فتكون كلفة كل معاينة صفرًا بعد الاستدعاء الأول.","changelog.94e452c9cf02":"<code>preview/fallback.rs</code> — بديل احتياطي لأنظمة Unix النادرة. يُرجع None دائمًا فينتقل المستدعي إلى المسار العام لعرض بداية النص + الأيقونة حسب النوع.","changelog.3c9eec3f6c4b":"<code>preview/mod.rs</code> — توزيع المضيفين + <code>text_head_fallback</code> (يقرأ حتى 4 KiB، ويصنّف المحتوى نصًا إذا وفقط إذا لم توجد بايتات NUL وكانت نسبة أحرف الاستبدال ≤ 1%).","changelog.67698e29fe12":"<strong>نافذة الإعدادات</strong> (<code>apps/freally-ui/src/components/settings/</code>) — كل عنصر تحكم وفق PRD §8.2-§8.27 موصول دون أي بدائل فارغة.","changelog.a3361a51edd5":"<code>SettingsDialog.svelte</code>: نافذة مشروطة قابلة لتغيير الحجم (الحد الأدنى 800×620، والافتراضي 960×720)، بتخطيط من شجرة تنقّل يسرى + جزء تفاصيل أيمن + شريط أزرار سفلي. تحفظ آخر عقدة محدّدة + موضع التمرير لكل جزء عبر localStorage، فيعود فتح النافذة مجددًا إلى اللوحة التي كان المستخدم فيها آخر مرة.","changelog.24b28d6fc11f":"<code>SettingsTreeNav.svelte</code>: الشجرة الكاملة وفق PRD §8.1.1 (عام / السجل / الفهارس / العدسات / الشبكة / الخصوصية والتحديثات / السجلات والتصحيح / النسخ الاحتياطي والتصدير وإعادة التعيين / اللغة والمنطقة / حول). ويصفّي مربع البحث في الخيارات العُقدَ حسب التسمية ومجموعة الكلمات المفتاحية لكل عقدة. وتحمل اللوحات المعدَّلة علامة <code>•</code> بنفسجية كي يرى المستخدم أيّها فيه تغييرات غير محفوظة.","changelog.4f8f836e7ec7":"<code>SettingsButtonBar.svelte</code>: «استعادة الإعدادات الافتراضية» (يسارًا، لكل لوحة)، و«موافق» / «إلغاء» / «تطبيق» (يمينًا). لا يُفعَّل «تطبيق» إلا عند <code>settingsDialog.dirty</code>؛ و«موافق» يطبّق ثم يُغلق؛ و«إلغاء» يتراجع عبر <code>SettingsDialogModel.cancel()</code> (تُؤخذ لقطة <code>snapshot()</code> لكل مخزن عند فتح النافذة، ويستعيدها <code>rollback()</code>)؛ و«استعادة الإعدادات الافتراضية» تعيد تعيين اللوحة النشطة عبر <code>SettingsDialogModel.resetPanel(panelId)</code>.","changelog.57b1a742578b":"26 مكوّن لوحة، واحد لكل قسم من أقسام PRD §8.2-§8.27. أبرزها:","changelog.66c58219af20":"<strong>عام ← الواجهة</strong>: منتقي السمة (يبدّل فورًا)، ومفاتيح شريط المهام، وأنماط النقرة الواحدة، وكثافة الصفوف، والتلاشي المتحرّك بين السمات.","changelog.cfe484eb7c32":"<strong>عام ← الرئيسية</strong>: ثلاثيات «استخدام آخر قيمة | تشغيل | إيقاف» لكل قيمة مطابقة افتراضية؛ وقوائم منسدلة للتصفية / الترتيب / العرض / مصدر الفهرس؛ والظهور الافتراضي للعدسات + حدود النتائج لكل عدسة.","changelog.434f9ca58ddb":"<strong>عام ← البحث</strong>: كل مفاتيح سلوك لغة الاستعلام في voidtools-Everything إضافةً إلى إضافات Freally (وضع Everything الصارم، والكشف التلقائي عن التعبير النمطي، وإكمال المُعدِّلات، وإظهار شجرة التحليل عند التمرير).","changelog.1d3e0b8951a4":"<strong>عام ← النتائج</strong>: كل خيارات السلوك + قوائم أولوية التحميل المنسدلة + التجميع حسب العدسة.","changelog.66559820d7a5":"<strong>عام ← العرض</strong>: كل مفاتيح العرض المعلَّمة بـ (E) + شارات الصوت/التشابه في Freally + موضع جزء المعاينة.","changelog.abfacc1cecb2":"<strong>عام ← قائمة السياق</strong>: «إظهار» / «الإظهار فقط عند الضغط على Shift» / «إخفاء» لكل أمر + سلسلة ماكرو لكل الإدخالات العشرة.","changelog.bcfbad5112f2":"<strong>عام ← الخطوط والألوان</strong>: الخط + الحجم + لون المقدّمة/الخلفية لكل حالة (مع <code>&lt;input type=&quot;color&quot;&gt;</code>) + عريض + مائل لكل حالات العناصر الثماني + لون مميّز لكل عدسة + مفتاح وراثة السمة.","changelog.e1ece0afb46b":"<strong>عام ← لوحة المفاتيح</strong>: مفتاح اختصار عام + مفاتيح اختصار لكل نافذة + سجلّ تسلسلات المفاتيح (صفوف إضافة/إزالة لأزواج الأمر+الربط).","changelog.3ae2a3be31d0":"<strong>السجل</strong>: مفاتيح سجل البحث/التشغيل + أيام الاحتفاظ + زر «مسح الآن» + وضع الخصوصية + مفاتيح السجل لكل عدسة.","changelog.04aa58c3b95c":"<strong>الفهارس (المستوى الأعلى)</strong>: كل مفاتيح حقول الفهرس العامة في Everything + أزرار «فرض إعادة البناء» / «ضغط الفهرس» / «التحقّق من الفهرس» (عمليات حقيقية في الخدمة الخلفية مع إشعارات منبثقة بالنتيجة).","changelog.9c0402a55809":"<strong>الفهارس ← وحدات التخزين</strong>: اكتشاف وحدات التخزين متعدد المنصّات مع شارات نظام الملفات (NTFS / ReFS / exFAT / FAT32 / APFS / HFS+ / ext4 / Btrfs / ZFS / XFS / F2FS) + مؤشر حالة؛ ولكل وحدة تخزين: «تضمين في الفهرس» / «التضمين فقط» / تفعيل الاشتراك في سجل التغييرات (تختلف التسمية حسب نظام التشغيل — USN / FSEvents / inotify) / المخزن المؤقت / «فرق التخصيص» (لـ NTFS فقط) / تحميل التغييرات الأخيرة / «مراقبة التغييرات»؛ وأزرار خاصة بكل نظام تشغيل («إعادة إنشاء السجل» على NTFS، و«إعادة تعيين التدفق» على APFS، و«الترقية إلى fanotify» على Linux)؛ وزر «إزالة».","changelog.a85227577e86":"<strong>الفهارس ← المجلدات</strong>: الإضافة عبر منتقي المجلدات في نظام التشغيل + مفتاح المراقبة لكل مجلد + المخزن المؤقت + جدول إعادة الفحص (في وقت محدّد / كل N ساعة / أبدًا) + زرا «إعادة الفحص الآن» / «إعادة فحص الكل الآن».","changelog.7a5ae0347c10":"<strong>الفهارس ← قوائم الملفات</strong>: إضافة قائمة ملفات عبر المنتقي + قائمة منسدلة للصيغة (نص / JSON / .srcb) + مفتاح التصدير التلقائي لعمليات البحث المحفوظة + زر «محرّر قائمة الملفات».","changelog.e20f4ec8774d":"<strong>الفهارس ← الاستبعاد</strong>: قائمة المجلدات + أنماط glob + «تطبيق الاستبعادات الموصى بها من نظام التشغيل» (الاستبعادات المتعارف عليها لكل من Win / Mac / Linux) + شرائح الاستبعاد حسب الفئة (فيديو / صوت / صورة / أرشيف / ملف تنفيذي).","changelog.8fd5ecb1f212":"<strong>العدسات ← اسم الملف</strong>: شدّة التصفية بالثلاثيات + ميزانية ذاكرة مصفوفة اللواحق + حدّ توسيع أحرف البدل + مهلة التعبير النمطي.","changelog.38b4c6105b69":"<strong>العدسات ← المحتوى</strong>: التفعيل + وضع لكل صيغة من 11 صيغة + الميزانيات + طول المقتطف + لغة كلمات التوقف (لغات الإصدار الـ 18) + إعادة الاستخراج عند تغيير الإعدادات + التحقق من المجاميع الاختبارية للكتل.","changelog.299de69339e8":"<strong>العدسات ← الصوت</strong>: التفعيل + وضع لكل صيغة من 10 صيغ + معيار مرجع LUFS + طريقة حساب الذروة + عتبة الصمت + إعادة الاستخراج عند التعديل.","changelog.9b9db5aea8be":"<strong>العدسات ← التشابه</strong>: التفعيل + حجم التوقيع (64/128/256) + النطاقات (8/16/32) + عتبة الاستدعاء + الحدّ الأقصى للنتائج.","changelog.98316029b6fa":"<strong>العدسات ← مخصّص</strong>: سجلّ مُستخرِجات المجتمع مع مفاتيح الثقة + عرض تجزئات blake3 + عرض أذونات بيئة العزل + «تحديث التجزئات».","changelog.b244fd575e99":"<strong>الشبكة ← خادم HTTPS</strong>: البدء/الإيقاف + الربط/المنفذ/فرض HTTPS/المصادقة القديمة + إعادة توليد الرمز المميّز (يدوّر البصمة فورًا).","changelog.2b5f33d631fe":"<strong>الشبكة ← واجهة ETP/FTP</strong>: البدء/الإيقاف + المنفذ + مفتاح دعم FTP/ETP النصي القديم.","changelog.acd0f3e9e295":"<strong>الخصوصية والتحديثات</strong>: تواتر التحديث التلقائي + مفتاح الإصدارات الأولية + سياسة اتصالات الشبكة المثبّتة في الشيفرة للقراءة فقط.","changelog.a7f925aabcc4":"<strong>السجلات والتصحيح</strong>: مستوى السجل (يغيّر مرشّح التتبّع فورًا) + الاحتفاظ + فتح مجلد السجل (عبر <code>tauri-plugin-opener</code>) + تصدير حزمة التشخيص.","changelog.71e2554230fe":"<strong>النسخ الاحتياطي والتصدير وإعادة التعيين</strong>: تصدير / استيراد الإعدادات (ذهاب وإياب بصيغة TOML عبر <code>tauri-plugin-fs</code>) + تصدير / استيراد حزمة الإشارات المرجعية (.srcb) + إعادة تعيين الكل (مع تأكيد).","changelog.af4a3d364535":"<strong>اللغة والمنطقة</strong>: قائمة منسدلة بلغات الإصدار الـ 18 — <strong>الإنجليزية مثبّتة أولًا</strong> ثم ترتيب أبجدي حسب الاسم الأصلي (تجميع: اللاتينية ← السيريلية ← RTL ← أنظمة الكتابة الأخرى)؛ وكل تسمية هي اسم اللغة بلغتها نفسها، كي يستطيع المستخدم اختيار لغته حتى لو كانت الواجهة بنظام كتابة لا يستطيع قراءته؛ وقلب فوري للاتجاه RTL عبر <code>applyRtlForLocale()</code> (يضبط <code>dir=&quot;rtl&quot;</code> و<code>lang</code> على <code>document.documentElement</code> حين تكون اللغة العربية أو تكون معاينة RTL مفعّلة)؛ وتنسيق التاريخ / الأرقام (نظام التشغيل / ISO / RFC / مخصّص).","changelog.34eea5e6fc14":"<strong>حول</strong>: الإصدار + الإيداع + اكتشاف نظام التشغيل + الترخيص + الإشادة بـ voidtools + إشعارات المصادر المفتوحة.","changelog.5db29baba331":"SettingsDialogModel (<code>lib/stores/settings_dialog.svelte.ts</code>) — آلة حالة التعديلات غير المحفوظة. تتتبّع علامات التعديل لكل لوحة؛ وعند فتح النافذة تأخذ لقطة لكل مخزن؛ ويُنفّذ <code>apply()</code> دالة <code>flush()</code> لكل مخزن دفعة واحدة؛ ويستعيد <code>rollback()</code> اللقطات؛ ويعيد <code>resetPanel(id)</code> المفاتيح التي تملكها تلك اللوحة فقط. ويربط <code>PANEL_KEYS</code> كل PanelId بمفاتيح SettingsState التي يملكها من أجل إعادة تعيين دقيقة.","changelog.7d9367a4db32":"6 مخازن جديدة تمرّ عبر الخدمة الخلفية تحت <code>lib/stores/</code>: <code>volumes / folders / excludes / network / custom_extractors / history</code>. يحمل كلٌّ منها <code>hydrate()</code> (تُستدعى عند فتح النافذة)، و<code>snapshot()</code> / <code>rollback()</code>، و<code>flush()</code>، و<code>reset()</code>.","changelog.f76dd7e6a086":"<strong>الملف التنفيذي لسطر الأوامر <code>freally</code></strong> (<code>crates/freally-cli</code>) يصبح عميلًا ثانيًا لطبقة النقل <code>freally-rpc</code> نفسها — مسار المقبس نفسه، ووضع المصادقة نفسه. الأوامر الفرعية: <code>search &quot;&lt;query&gt;&quot;</code> (مع الخيارين <code>--strict-everything</code> و<code>--parse-only</code>)؛ و<code>index status / verify / compact / rebuild / pause / resume / add-root &lt;path&gt; / rm-root &lt;path&gt;</code>؛ و<code>bookmark save / list / delete</code> (حالة على جانب الواجهة — تُظهر رسالة واضحة مفادها «يديرها التطبيق قيد التشغيل» حتى تنقل المرحلة 13 الإشارات المرجعية إلى طبقة نقل الخدمة الخلفية)؛ و<code>theme system | light | dark</code>. يشترك الأمر الفرعي <code>search</code> في الإشعارات أولًا كي لا تفوته أحداث <code>query:batch</code> المبكرة، ويطبع النتائج مجمّعة حسب العدسة فور وصولها، ويطبع توقيتات العدسات النهائية عند <code>query:done</code>.","changelog.af56538d34af":"<strong>التدويل (i18n).</strong> وُسّعت ملفات <code>.ftl</code> الـ 18 كلها بمفاتيح نافذة الإعدادات في المرحلة 12 (~250 مفتاحًا لكل لغة، و~14 KiB لكل ملف). اللغات: en / ar / de / es / fr / hi / id / it / ja / ko / nl / pl / pt-BR / ru / tr / uk / vi / zh-CN. كل لغة مترجمة بالكامل إلى لغتها الأصلية (لا تُشحن مسودات ترجمة آلية). ويُختبر تخطيط العربية من اليمين إلى اليسار عبر القلب الفوري <code>applyRtlForLocale()</code> في <code>lib/bootstrap.ts</code> ومفتاح <strong>اللغة والمنطقة ← معاينة من اليمين إلى اليسار</strong>. وتتيح القائمة المركّبة التي تعرض كل لغة باسمها الأصلي للمستخدم العالق في نظام كتابة لا يستطيع قراءته أن يختار لغته رغم ذلك.","changelog.3cd9ef6d9858":"<strong>اختبارات الدخان</strong> (<code>tests/smoke/phase_12_*</code> إضافةً إلى إعادة التصدير لكل حزمة تحت <code>crates/freally-rpc/tests</code> و<code>crates/freally-indexd/tests</code> و<code>crates/freally-extractor-host/tests</code>):","changelog.233c2ff71ae3":"<code>phase_12_rpc_transport.rs</code> — ذهاب وإياب عبر مقبس UDS حقيقي (Unix) / أنبوب مسمّى (Windows)؛ وتأكيد وضع الملف 0600 على ملف المقبس؛ وسلوك EOF النظيف؛ ورفض الإطارات المفرطة الحجم.","changelog.037808959a87":"<code>phase_12_indexd_client.rs</code> — <code>query.run</code> يبثّ الدفعات ويُصدر <code>query:done</code>؛ و<code>index.state</code> يُرجع عرضًا محدّد النوع؛ وذهاب وإياب لـ <code>extractors.list</code> + <code>extractors.set_mode</code>؛ وذهاب وإياب لـ <code>excludes.get</code> / <code>excludes.set</code>؛ وبوابة الانحدار <code>no_canned_rs_in_tree</code> التي تُفشل البناء إذا عاد <code>canned.rs</code> للظهور.","changelog.c5cfbc1b43d4":"<code>phase_12_settings.rs</code> — ذهاب وإياب JSON قائم على بيانات اختبار لشكل <code>SettingsState</code> في المرحلة 12؛ ويحفظ تسطيح <code>extras</code> المفاتيح غير المعروفة.","changelog.3f571f0f5d1b":"<code>phase_12_custom_extractor.rs</code> — القيم الافتراضية للبيان؛ وذهاب وإياب الثقة؛ وتعطيل عدّاد التعطّلات عند الثالثة؛ وتخطّي البيان غير الصالح؛ وتهيئة محرّك المضيف.","changelog.3dbbc40cea55":"<code>phase_12_theme_switch.rs</code> — ذهاب وإياب JSON لاختيار السمة عبر <code>settings.apply</code>.","changelog.972927dbd83f":"<code>phase_12_preview_hosts.rs</code> — تصنيف البديل الاحتياطي العام لعرض بداية النص + جدول ألوان SVG للأيقونات حسب النوع.","changelog.a578a3241000":"<code>phase_12_volumes.{ps1,sh}</code> — سكربتات صدفة لكل نظام تشغيل تشغّل <code>cargo test -p freally-indexd --test phase_12_indexd_client</code> (توجد ثوابت اكتشاف وحدات التخزين في اختبارات الوحدة لحزمة indexd؛ واختبارات الدخان عبر الصدفة هي البوابة عبر أنظمة التشغيل).","changelog.c7b0c19f8b54":"<strong>انحرافات عن دليل البناء</strong> (انحراف واحد): طلب التوجيه أن يكون مضيفو المعاينة الأصليون لنظام التشغيل (QuickLook / Shell / Sushi+KIO) <em>موصولين بالكامل</em> في المرحلة 12. تُشحن في هذه المرحلة بنية الوحدات متعددة المنصّات + البديل الاحتياطي العام؛ وتصل تكاملات COM/objc2/DBus الخاصة بكل نظام تشغيل كتحسينات لجودة الاستخدام دون تغيير عقد عناوين البيانات أو واجهة أوامر Tauri. واجهة الوحدة <code>preview</code> جاهزة، فيكون الاستبدال محليًا.","changelog.409ff5baabf9":"<strong>[كل المنصّات]</strong> واجهة البحث في المرحلة 11 — اللحظة السحرية (<code>apps/freally-ui</code>). تطبيق سطح مكتب بـ Tauri 2 + Svelte 5 + TypeScript + Tailwind CSS فوق واجهة خلفية IPC <em>وهمية</em> في <code>src-tauri/src/commands/</code>. الأمر الوحيد الذي يتحدث إلى واجهة خلفية حقيقية هو <code>query_parse</code>، الذي يتجه مباشرةً إلى <code>freally-query::parse_to_report</code> فيطابق التقطيع الحي في شريط البحث محلّل الإنتاج تمامًا. وتستبدل المرحلة 12 (TASK-086a/b/c) الطبقة الوهمية بطبقة نقل RPC الحقيقية لـ <code>freally-indexd</code> دون تغيير عقد أنواع TS في <code>lib/ipc/types.ts</code>.","changelog.8c8596283703":"<strong>واجهة المستخدم (PRD §8.28 + §8.29 + §9):</strong> SearchBar مع تقطيع حيّ إلى رموز عبر <code>query.parse</code> في IPC + عرض المقاطع في طبقة مرآة ملوّنة حسب نوع الرمز + شارة خطأ تحليل مضمّنة مثبّتة على أول مقطع خاطئ (يمسحها Esc)؛ ونتائج مجمّعة حسب العدسة (اسم الملف / المحتوى / الصوت / التشابه) بأقسام قابلة للطيّ، وشارات توقيت لكل عدسة، ومفاتيح ظهور العدسات عبر <code>View → Lenses</code>؛ ونتائج متعددة الأعمدة (الاسم | المسار | الحجم | آخر تعديل | النوع | الامتداد) مع تغيير الحجم بالسحب عبر التقاط المؤشر على مقابض الأعمدة، والترتيب بالنقر للتبديل (دورة تصاعدي / تنازلي)، وملفات تعريف أعمدة محفوظة عبر <code>settings.column_profiles[active]</code>، ومفتاح كثافة الصفوف مضغوط (32 px) / مريح (44 px)؛ وتفاعلات الصفوف (Enter للفتح / Ctrl+Enter للإظهار في المجلد / Shift+Enter لنسخ المسار / Ctrl+C لنسخ الاسم / Del للتأكيد ثم الحذف؛ وCtrl+نقرة لتبديل التحديد)؛ وجزء معاينة مرتبط بأول <code>file_id</code> محدّد (يعرض بداية النص من <code>files_preview</code> عبر IPC، ويدعم عناوين بيانات الصور، ويُظهر «غير مدعوم» للملفات الثنائية — ويُوصل مضيفو المعاينة الأصليون لنظام التشغيل في المرحلة 12)؛ وعمود الصور المصغّرة (يستدعي <code>ThumbnailCell</code> الأمر <code>files_thumbnail</code> عبر IPC مع مربعات SVG وهمية ملوّنة لكل امتداد)؛ وBookmarksDropdown في شريط القوائم تُملأ من <code>bookmarks_list</code> (حفظ حقيقي معتمد على JSON تحت مجلد بيانات التطبيقات في نظام التشغيل) + OrganizeBookmarksDialog مع إعادة التسمية + الحذف (Ctrl+D للإضافة، وCtrl+Shift+B لفتح التنظيم)؛ وQuickFiltersPalette بسبع شرائح (صوت / فيديو / صورة / مستند / ملف تنفيذي / أرشيف / مجلد) تبدّل الرمز المطابق؛ ومفتاح اختصار عام عبر <code>tauri-plugin-global-shortcut</code> (افتراضيًا Alt+Space على macOS، وSuper+Space على Win/Linux) — يؤدي إطلاقه إلى إحضار النافذة إلى المقدّمة + التركيز على حقل البحث؛ وبروتوكول عناوين <code>freally://search?q=…</code> عبر <code>tauri-plugin-deep-link</code>؛ ومعالج التشغيل الأول (4 خطوات: الجذور / مفتاح الاختصار / اللغة / السمة) المشروط بـ <code>settings.first_run_complete</code>؛ ونظام السمات (PRD §9) بحالة ثلاثية <code>system</code> / <code>light</code> / <code>dark</code> عبر السمة <code>&lt;html data-theme&gt;</code>، حيث تقود الرموز (tokens) كل لون عبر خصائص CSS المخصّصة (<code>tokens.{dark,light,shared}.css</code>)، وتلاشٍ متبادل مدته 100 ms يحترم <code>prefers-reduced-motion</code>، ومستمع <code>prefers-color-scheme</code> يقلب السمة فورًا في وضع <code>system</code>، وتهيئة Tailwind تربط الأدوات المساعدة بـ <code>var(--…)</code>.","changelog.ab4ea4f7502a":"<strong>شريط القوائم الرئيسي (PRD §8.28)</strong> — قوائم كاملة مكافئة لـ Everything عبر ملف / تحرير / عرض / بحث / الإشارات المرجعية / أدوات / مساعدة، مع كل القوائم الفرعية + العناصر الفرعية + مسرّعات لوحة المفاتيح + إضافات Freally (القائمة الفرعية عرض ← السمة، والقائمة الفرعية عرض ← العدسات، وأدوات ← صيانة الفهرس ▶ التحقّق / الضغط / فرض إعادة البناء، وأدوات ← مدير المُستخرِجات المخصّصة، ومساعدة ← مرجع مُعدِّلات الصوت / التشابه، ومساعدة ← رعاية / تبرّع). التموضع حسب نظام التشغيل: يستخدم macOS الأداة <code>tauri::menu::MenuBuilder</code> لشريط القوائم العام (مع قائمة التطبيق <code>Freally →</code> التي يتطلبها macOS وتحمل «حول» / «التفضيلات» / «إنهاء»)؛ بينما يعرض Win/Linux المكوّن <code>MenuBar.svelte</code> داخل النافذة، مستهلكًا المواصفات التصريحية نفسها عبر مجموعة CommandId نفسها. تُصدر أحداث النقر من قائمة macOS الأصلية <code>menu-command</code>؛ ويستمع <code>bootstrap.ts</code> في الواجهة ويوزّعها عبر سجلّ الأوامر داخل العملية — مصدر واحد للحقيقة لمساري العرض كليهما. وتُصدر أحداث التمرير <code>MenuHoverEvent</code> إلى مقطع التلميحات في شريط الحالة. تطابق تلميحات التمرير سلاسل Everything تمامًا («يحتوي على أوامر للعمل مع Freally.»، «يحتوي على أوامر لترتيب قائمة النتائج.»، إلخ) إضافةً إلى إضافات Freally («التبديل بين سمات النظام أو الفاتحة أو الداكنة.»، «تبديل ظهور كل عدسة في قائمة النتائج.»، «إدارة المُستخرِجات المخصّصة المعزولة في بيئة Wasm.»، «أدوات صيانة الفهرس.»).","changelog.d29275561d2e":"<strong>شريط الحالة (PRD §8.29)</strong> — قابل للتبديل عبر <code>View → Status Bar</code>. سبعة مقاطع افتراضية من اليسار إلى اليمين: مؤشر الفهرسة (تمت الفهرسة / جارٍ الفهرسة N/M / متوقّف مؤقتًا / خطأ) مع إظهار مفتاح الاختصار عند التمرير، وعدد النتائج + عدد المحدّد، وحجم المحدّد (مشروط بـ <code>show_size_in_status_bar</code>)، وتوقيت الاستعلام النشط، وزمن الاستجابة لكل عدسة (مشروط بـ <code>show_timing_badges</code>)، ومؤشر نقطة النهاية (قاعدة بيانات محلية / واجهة API: \\&lt;name\\&gt;)، ومنطقة تلميحات التمرير المشتركة في مخزن تمرير القوائم مع نص الخمول <code>Ready · {indexed} indexed</code>. إضافات خاصة بـ Freally: مؤشر السمة في أقصى اليمين (أيقونة شمس / قمر، والنقرة الواحدة تدور بين 3 حالات)؛ وإظهار مفتاح الاختصار عند التمرير على مؤشر الفهرسة هو إحدى الإضافتين (+) في PRD §8.29.","changelog.5bcf148b5b86":"<strong>سجلّ الأوامر + اختصارات لوحة المفاتيح:</strong> يحمل <code>lib/commands/ids.ts</code> اتحادًا نصيًا شاملًا يُتحقق منه وقت التصريف هو <code>CommandId</code>، يغطي ~95 عنصر قائمة؛ و<code>isCommandId</code> هو فحص المجموعة المغلقة الذي يستخدمه <code>bootstrap.ts</code> للتحقق من حمولات أحداث <code>menu-command</code> القادمة من قائمة macOS الأصلية (ويرفض الحمولات المشوّهة). يوزّع <code>lib/commands/registry.ts</code> عبر <code>Map&lt;CommandId, CommandHandler&gt;</code> — لكل CommandId معالج مسجّل عند بدء التشغيل؛ ويُصدر مسار الإقلاع <code>console.warn</code> إن نقص أيٌّ منها. <code>lib/commands/menu_spec.ts</code> (TS) + <code>src-tauri/src/menu_spec.rs</code> (Rust) — أشجار قوائم تصريحية يستهلكها كلا العارضين، ويُبقيها متزامنة اختبارُ التكافؤ <code>tests/menubar_parity.rs::rust_spec_covers_every_command_id</code> + <code>does_not_introduce_unknown_command_ids</code> (كانت خطوة توليد شيفرة وقت البناء ستضيف نطاقًا بعائد سلبي؛ واختبار التكافؤ هو بوابة الانحدار). <code>lib/commands/shortcuts.ts</code> واعٍ بنظام التشغيل — يُحَلّ <code>mod</code> إلى ⌘ على macOS وإلى Ctrl على Win/Linux وقت التشغيل عبر <code>isMac()</code>. المعالجات الحقيقية الموصولة في هذه المرحلة: التكبير (حجم خط الجذر)، وحجم النافذة (<code>WebviewWindow::setSize</code> في Tauri)، والترتيب (حقل <code>sortStore</code> + حالة الترتيب)، والبقاء في المقدّمة (<code>set_always_on_top</code>)، والصور المصغّرة/التفاصيل (row_density)، والسمة (ذهاب وإياب السمة + الإعدادات)، وظهور العدسات، والتحديث (إعادة تشغيل الاستعلام)، ومفاتيح المعاينة/شريط الحالة، وfile.close / file.exit (إغلاق النافذة)، وtools.options (نافذة إعدادات مؤقتة)، وtools.verify/compact/rebuild_index (IPC حقيقي)، وhelp.\\* (فتح عناوين URL عبر إضافة opener)، وhelp.about (نافذة «حول»)، وbookmarks.add/organize (المخزن + النافذة)، ومعرّفات أوامر عوامل التصفية السريعة (إضافة الرمز في البداية + إعادة التشغيل)، وedit.cut/copy/paste/select_all/invert_selection، وedit.advanced.copy_full_name/path/filename/as_json/with_metadata/as_bundle_ref. أما المعالجات المؤقتة المتبقية (file.new_window / file.open_file_list / file.export_results / view.go_to / search.advanced / search.add_to_filters / search.organize_filters / مفاتيح المطابقة في البحث / tools.file_list_editor / edit.copy_to_folder/move_to_folder) فموسومة صراحةً بـ <code>Phase 12</code> في الشيفرة — إذ تنتظر IPC حقيقيًا مع الخدمة الخلفية أو نافذة الإعدادات الكاملة، وكلاهما ضمن نطاق المرحلة 12.","changelog.a2506592845e":"<strong>واجهة IPC خلفية وهمية في Rust</strong> (<code>apps/freally-ui/src-tauri/src/commands/</code>): يوجّه <code>query.rs</code> الأمر <code>query_parse</code> عبر <code>freally-query::parse_to_report</code> الحقيقي (واجهة المرحلة 10، حقيقية)؛ وتُنتج <code>query_run</code> / <code>query_cancel</code> / <code>query_lens_timings</code> / <code>query_fetch_batches</code> دفعات جاهزة حتمية عبر العدسات الأربع مع LensTimings اصطناعية لكنها واقعية الشكل (8 ms لاسم الملف / 22 ms للمحتوى / 5 ms للصوت / 11 ms للتشابه / 14 ms إجمالًا). يولّد <code>canned.rs</code> لكل استعلام 12 / 8 / 4 / 6 نتيجة عبر العدسات الأربع (بشكل حتمي كي تستطيع اختبارات الدخان التثبيت مقابل المخرجات؛ ويُضيء ثابت إجمالي المفهرس البالغ 5 234 123 ملفًا نص الخمول في مؤشر الفهرسة). وينتقل <code>index_state.rs</code> من <code>Indexing N/total</code> إلى <code>Indexed (total)</code> خلال نافذة إحماء مدتها 4 ثوانٍ. ويوفّر <code>bookmarks.rs</code> حفظًا حقيقيًا معتمدًا على JSON تحت <code>app.path().app_data_dir()</code> (جذر معتمد من Tauri). ويحمل <code>extractors.rs</code> سجلًّا جاهزًا للمُستخرِجات السبعة من المراحل 7–9 مع <code>ExtractorMode</code> لكل مُستخرِج (eager / lazy / disabled). و<code>settings.rs</code> معتمد على JSON مع ذهاب وإياب بالدمج العميق <code>settings_set(patch)</code> عبر <code>serde_json::to_value</code> + إعادة إلغاء تسلسل محدّدة النوع؛ ويستعيد <code>settings_reset</code> القيم الافتراضية؛ ويغطي المخطط السمة / اللغة / مفاتيح شريط الحالة / مفتاح شارات التوقيت / المعاينة / كثافة الصفوف / ملفات تعريف الأعمدة / ظهور العدسات / مفتاح الاختصار / نقطة النهاية / علم التشغيل الأول / وضع الخصوصية. ويستخدم <code>files.rs</code> الإضافة <code>tauri-plugin-opener</code> لمعالجات الفتح/الإظهار الحقيقية في نظام التشغيل، و<code>tauri-plugin-clipboard-manager</code> لـ copy_path / copy_name، و<code>std::fs::remove_file</code> للحذف (بعد التأكيد في الواجهة)، وعنوان بيانات SVG ملوّنًا للصورة المصغّرة (وهمي)، وبداية النص أو <code>Unsupported</code> للمعاينة (وهمي).","changelog.7d2b902ad7ff":"<strong>التكاملات الأصلية:</strong> يبني <code>native_menu.rs</code> تعاوديًا كائن <code>tauri::menu::Menu</code> من <code>menu_spec.rs</code>، وعلى macOS يضبطه كقائمة التطبيق عبر <code>app.set_menu(...)</code> (تحمل قائمة التطبيق <code>Freally →</code> التي يتطلبها macOS «حول» / «التفضيلات» / «إنهاء» مع المسرّعات الصحيحة وفق إرشادات HIG). ويسجّل <code>hotkey.rs</code> تسلسل المفاتيح الافتراضي (Alt+Space على macOS، وSuper+Space على Win/Linux) عبر <code>tauri-plugin-global-shortcut</code>؛ وعند إطلاقه يُظهر النافذة الرئيسية ويركّز عليها ويُصدر <code>hotkey:fired</code> كي تركّز الواجهة على حقل البحث؛ ويظهر التعارض كسجل <code>warn</code> (يستطيع المستخدم تجاوز تسلسل المفاتيح في إعدادات المرحلة 12). ويسجّل <code>url_protocol.rs</code> المخطط <code>freally://</code> عبر <code>tauri-plugin-deep-link</code> ويُصدر <code>url:opened</code> لعناوين URL الواردة؛ ويحلّلها مستمع الواجهة بـ <code>new URL(...)</code> ولا يتصرّف إلا على شكل <code>?q=</code>.","changelog.dfae438bb9e9":"<strong>التدويل (i18n)</strong> (القاعدة الدائمة #4): حزمة en مضمّنة (توصل المرحلة 12 مُحمِّل Fluent الكامل مع <code>locales/&lt;code&gt;/freally.ftl</code> للغات الـ 18 كلها). وُسّعت ملفات <code>.ftl</code> الـ 18 كلها بمفاتيح المرحلة 11 (مجموعات الحالة / القوائم / السمة / العدسات / أخطاء التحليل / الإجراءات / عوامل التصفية السريعة / المعالج) — مسودات ترجمة آلية بانتظار مراجعة بشرية قبل v0.19.84. ويبقى <code>xtask i18n-lint</code> ناجحًا عند عدد المفاتيح الجديد × 17 لغة غير مصدرية.","changelog.d61b34326782":"<strong>الاختبارات + التحقق:</strong> يغطي <code>tests/smoke/phase_11_ui_e2e.rs</code> (7 حالات — مُعاد تصديرها تحت <code>crates/freally-query/tests/phase_11_ui_e2e.rs</code>) ثوابت تدفق الرموز في <code>parse_to_report</code> التي يعتمد عليها <code>highlight.ts</code> في شريط البحث، وإظهار أخطاء وضع strict-everything لشارة خطأ التحليل، وثبات ذهاب وإياب JSON لـ <code>LensId</code> + <code>IndexPhase</code> عبر IPC من أجل الاستبدال في المرحلة 12، و<strong>بوابة أداء اللحظة السحرية</strong> (TASK-085): يبلغ متوسط <code>parse_to_report</code> أقل بكثير من 4 ms لكل تكرار على استعلام من حرف واحد وعلى استعلام واقعي من 32 حرفًا — فيبقى المسار الحرج لضغطة المفتاح ضمن ميزانية 16 ms التي يحدّدها دليل البناء. <code>apps/freally-ui/src-tauri/tests/menubar_parity.rs</code> (4 حالات) — كل CommandId من PRD §8.28 موجود في مواصفات Rust؛ ولا زيادات؛ و7 جذور علوية بالترتيب الصحيح؛ ولا معرّفات مكرّرة. <code>apps/freally-ui/src-tauri/tests/menubar_wiring.rs</code> (3 حالات) — كل معرّف عنصر قائمة سليم البنية (بشكل <code>namespace.action</code>)؛ وكل سلسلة مسرّع تُحلَّل بسلاسة؛ وعناصر «حول» / «التفضيلات» / «إنهاء» في قائمة تطبيق macOS تستهدف معرّفات CommandId حقيقية. <code>apps/freally-ui/src-tauri/tests/statusbar_parity.rs</code> (حالتان) — تثبيت 7 مقاطع افتراضية + إضافتي Freally (+). <code>apps/freally-ui/tests/unit/*.test.ts</code> (هيكل vitest، ~25 حالة) — المنسّقات، والمجموعة المغلقة لمعرّفات الأوامر + تزامنها الصارم مع <code>MENU_BAR</code>، وتشكيل المقاطع في <code>highlight()</code> الخاصة بالمقطّع + طبقة الأخطاء + <code>firstError</code>، وتفرّد <code>BINDINGS</code> + <code>shortcutMatches</code> + <code>formatShortcut</code>، وتبديل <code>sortStore</code> / القفز إلى حقل مختلف / التشابه حسب الدرجة، ودورة مخزن السمات + تغيير سمة DOM. يشغّل <code>tests/smoke/phase_11_ui_e2e.{sh,ps1}</code> اختبار التوجيه عبر <code>cargo test</code> + حزمة src-tauri عبر <code>cargo check</code> + (عند توفّر <code>pnpm</code>) <code>pnpm install + check + build</code>. <strong>بوابة التحقق</strong>: <code>cargo fmt --all -- --check</code> و<code>cargo clippy --workspace --all-targets -- -D warnings</code> و<code>cargo test --workspace</code> كلها ناجحة؛ و<code>apps/freally-ui/src-tauri</code> نظيف في cargo check + clippy دون أي تحذير؛ وتنجح 9 اختبارات لـ src-tauri + 7 اختبارات دخان. و<code>/review</code> + <code>/security-review</code> نظيفان (القاعدة الدائمة #9).","changelog.03bf40d97b72":"هيكل <strong>Storybook</strong> + 3 قصص أولية (LensTimingBadge وQuickFiltersPalette وSearchBar) تحت <code>apps/freally-ui/src/stories/</code>، مع <code>.storybook/main.ts</code> + <code>preview.ts</code> يحملان مبدّل السمة الداكنة / الفاتحة في شريط الأدوات وفق متطلب اختبار الانحدار المرئي في PRD §9.","changelog.5df93276a274":"<strong>التسليم من المرحلة 11 إلى المرحلة 12</strong> (مؤجَّل إلى TASK-086a/b/c، وموثّق في Build-Prompts-Guide + ROADMAP): استبدال <code>commands/canned.rs</code> + <code>IndexStateMock</code> الوهميين بطبقة نقل JSON-RPC حقيقية مسبوقة بالطول عبر <code>freally-rpc</code> فوق مقبس Unix / أنبوب مسمّى لكل مستخدم (وضع الملف 0600 + فحص uid عند القبول على Unix؛ وقائمة DACL للأنبوب مقصورة على SID المستخدم الحالي على Windows)؛ وتوجيه <code>query_run</code> عبر <code>freally-query::execute_with_audio</code> الحقيقي فوق <code>freally-index</code> حي، مع بثّ الدفعات عبر <code>Window::emit(&quot;query:batch&quot;, ...)</code> كي تبقى بوابة 16 ms في الواجهة صادقة عند 5M ملف؛ ويحلّ مضيفو المعاينة الأصليون لنظام التشغيل (QuickLook عبر <code>objc2</code> على macOS / معالجات المعاينة في الصدفة عبر <code>windows-rs</code> على Windows / معاينات GNOME Sushi عبر DBus + KDE KIO على Linux) محلّ <code>files_preview</code> / <code>files_thumbnail</code> الوهميين. ويبقى عقد TS في <code>lib/ipc/types.ts</code> ثابتًا عبر الاستبدال.","changelog.1cfd9c0b8865":"<strong>انحرافات عن دليل البناء</strong> (ثلاثة، كلها مذكورة في الشيفرة + في هذا الإدخال): (1) <strong>إضافة shell في Tauri</strong> — أوحى دليل البناء باستخدام <code>tauri-plugin-shell::open()</code> لـ <code>files_open</code> / <code>files_reveal</code>؛ لكن واجهة API تلك مُهمَلة لصالح <code>tauri-plugin-opener::open_path</code>. نستخدم الإضافة الجديدة لتجنّب تحذير الإهمال في كل بناء. (2) <strong>القائمة الأصلية على Win/Linux</strong> — ينصّ دليل البناء على «داخل النافذة على Win/Linux، وشريط قوائم عام على macOS»؛ وتشحن المرحلة 11 قائمة داخل النافذة على Win/Linux + القائمة الأصلية على macOS. ويُؤجَّل تكامل DBus AppMenu على Linux (حيث يتوفّر) إلى المرحلة 12. (3) <strong>مضيفو المعاينة الأصليون لنظام التشغيل</strong> — تُشحن المرحلة 11 مع مزوّد المحتوى الوهمي لجزء المعاينة (بداية النص + صور مصغّرة SVG ملوّنة)؛ وتنتقل تكاملات QuickLook / Shell / Sushi / KIO إلى المرحلة 12 (TASK-086c) حيث تتشارك نطاق IPC الحقيقي مع الخدمة الخلفية. ويحمل التوجيهان TASK-075 / TASK-076 في المرحلة 11 ملاحظات ROADMAP مضمّنة حول التأجيل.","changelog.2e4654ecd39f":"<strong>[كل المنصّات]</strong> لغة الاستعلام في المرحلة 10 + تقوية المحلّل (<code>freally-query</code>) — يحتفظ المحلّل المكتوب يدويًا من المرحلة 5 بواجهته المطابقة 1:1 لـ voidtools-Everything (عقد القاعدة الدائمة #8) ويكتسب أربع قطع جديدة: (1) <strong><code>ParseOpts { strict_everything: bool }</code></strong> + <code>pub fn parse_with(s, opts) -&gt; Result&lt;Query, ParseError&gt;</code> (أصبحت <code>parse(s)</code> من المرحلة 5 الآن <code>parse_with(s, ParseOpts::default())</code>). يرفض وضع strict-everything كل مُعدِّل خاص بـ Freally — <code>similar:</code>، ومُعدِّلات الصوت الستة (<code>lufs:</code> / <code>codec:</code> / <code>length:</code> / <code>rate:</code> / <code>silence:</code> / <code>dr:</code>) إضافةً إلى الاسمين البديلين <code>duration:</code> / <code>samplerate:</code>، وبادئات العدسات <code>audio:(...)</code> / <code>content:(...)</code> / <code>similar:(...)</code> — مُظهرًا الخطأ الجديد محدّد النوع <code>ParseError::StrictEverythingViolation { pos, token, reason }</code> كي يستطيع شريط البحث في المرحلة 11 إبراز المُعدِّلات التي لن تعمل لدى مستخدم voidtools الخالص. وتواصل الواجهة ذات شكل voidtools (size وdate وext وattrib وpath/parent/child + الاسمان البديلان name/folder، وعوامل التصفية السريعة، والتعابير النمطية، وأحرف البدل، والربط المنطقي، والأقواس، والحجوزات المألوفة بحكم العادة <code>wfn:</code> / <code>case:</code> / <code>count:</code> / <code>dupe:</code> / <code>nodiacritics:</code> / <code>type:</code> / <code>lang:</code>) التحليلَ في الوضع الصارم. (2) <strong>صيغة بادئة العدسة</strong> <code>&lt;key&gt;:(...)</code> لـ <code>name:</code> / <code>audio:</code> / <code>content:</code> / <code>similar:</code>. يغلّف متغيّر AST الجديد <code>QueryNode::Lens { kind: LensKind, inner: Box&lt;QueryNode&gt; }</code> (مع <code>pub enum LensKind { Name, Audio, Content, Similar }</code>) استعلامًا فرعيًا داخليًا كي تستطيع واجهة النتائج المجمّعة حسب العدسة في المرحلة 11 عرض أقسام لكل عدسة. لا يستدعي المحلّل مسار بادئة العدسة إلا حين يكون الرمز <code>&lt;key&gt;:</code> بالضبط <em>وكان</em> الرمز التالي <code>(</code> — فيبقى <code>audio:</code> المجرّد عامل التصفية السريع؛ ويبقى <code>similar:foo</code> المُعدِّل <code>Similar</code> القائم؛ ويبقى <code>name:foo</code> الاسم البديل لـ <code>child:</code>. وتنهار نطاقات العدسات الفارغة (<code>audio:()</code>) إلى <code>True</code>. يعامل المنفّذ اليوم نطاقات العدسات <code>Name</code> / <code>Audio</code> / <code>Similar</code> كأغلفة شفافة (فالمُعدِّلات بداخلها لا تزال تقود التوجيه)؛ بينما تُظهر نطاقات عدسة <code>Content</code> الخطأ <code>QueryError::UnsupportedModifier(&quot;content&quot;)</code> إلى أن توصل المرحلة 11+ مُستخرِجات المحتوى من المرحلة 8 بالمنفّذ. (3) <strong>مرحلة المُحسِّن</strong> في الملف الجديد <code>crates/freally-query/src/optimizer.rs</code>: تعيد <code>pub fn optimize(q: &amp;Query) -&gt; Query</code> ترتيب أبناء <code>And</code> حسب <code>selectivity_rank</code> (الأرخص أولًا، فيلتقطها قِصَر الدارة)، وتنزل تعاوديًا في <code>Or</code> / <code>Not</code> / <code>Lens</code> (ويُحفظ ترتيب Or — فالترتيب مهم لثبات ترتيب النتائج)؛ ودالة الترتيب معايَرة على كلفة كل شرط في منفّذ المراحل 5/6/9 (literal/quick-filter/child = 10-12، ext = 13، size/date/attrib = 20-24، path/parent = 30، wildcard = 40، regex = 50، audio = 80، similar = 85، reserved = 90). وتتيح دالتا توجيه العدسات المساعدتان <code>is_audio_only_route(node)</code> و<code>is_similarity_route(node)</code> للمنفّذ تخطّي المرشّح المسبق بثلاثيات أسماء الملفات في الاستعلام الصوتي الخالص (فكل صف حي مرشّح، فيعمل <code>for_each_live</code> دون استدعاء <code>evaluator.matches</code> لكل صف). وقد وُصل المُحسِّن بـ <code>execute_with_audio</code> (في مقدّمة خط المعالجة) وبـ <code>PlanCache::get_or_plan</code> (الصيغة المخزّنة مؤقتًا هي الصيغة المُحسَّنة)، فيستفيد كل تشغيل فعلي دون تغيير شكل AST الذي يراه المستخدم من <code>parse()</code>. (4) <strong><code>pub fn parse_to_report(s: &amp;str, opts: ParseOpts) -&gt; ParseReport</code></strong> — نقطة الدخول <code>query.parse</code> عبر IPC في الملف الجديد <code>crates/freally-query/src/report.rs</code>. البنية <code>ParseReport { source, strict_everything, ast: Option&lt;AstNode&gt;, tokens: Vec&lt;TokenInfo&gt;, errors: Vec&lt;ErrorInfo&gt; }</code> قابلة للتسلسل بالكامل عبر serde (Serialize)، وجاهزة لأمر Tauri أو لطلب POST مستقبلي إلى <code>/v1/query.parse</code> في <code>freally-http</code>. تحمل <code>TokenInfo { kind, span: TokenSpan { start, end }, text }</code> مقاطع لكل رمز + نوعًا دلاليًا <code>TokenKind</code> (<code>Literal</code> / <code>Quoted</code> / <code>Wildcard</code> / <code>Regex</code> / <code>Modifier{name}</code> / <code>QuickFilter{name}</code> / <code>LensPrefix{lens}</code> / <code>LParen</code> / <code>RParen</code> / <code>Bang</code> / <code>And</code> / <code>Or</code> / <code>Not</code>) كي يستطيع شريط البحث تلوين الرموز أثناء الكتابة. وتُسقط <code>ErrorInfo { span, message, code: ErrorCode }</code> كل متغيّر من <code>ParseError</code> على مقطع + رسالة ملائمين للواجهة + <code>ErrorCode</code> قابل للقراءة آليًا (<code>Empty</code> / <code>UnexpectedEof</code> / <code>UnexpectedToken</code> / <code>UnbalancedParens</code> / <code>InvalidRegex</code> / <code>InvalidWildcard</code> / <code>UnknownModifier</code> / <code>InvalidModifierValue</code> / <code>StrictEverythingViolation</code>). تطابق <code>AstNode</code> القابلة للتسلسل <code>QueryNode</code> باستثناء الحمولة <code>Arc&lt;Regex&gt;</code> (يُحفظ مصدر التعبير النمطي كسلسلة — ويصرّفه مستهلك IPC من جهته)؛ وتحمل <code>ModifierDetail</code> أصغر مجموعة حقول تحتاجها الواجهة لكل مُعدِّل (size: <code>{op, bytes}</code>، وdate: <code>{op, epoch_day}</code> أو <code>{name}</code>، وext: <code>{extensions}</code>، وattrib: <code>{letters}</code>، وpath/parent/child/similar: <code>{needle}</code>، ومتغيّرات الصوت: <code>{op, value}</code>، وreserved: <code>{value}</code>). لا تُرجع <code>parse_to_report</code> القيمة <code>Err</code> أبدًا — فحتى المصدر الفارغ يُنتج تقريرًا كاملًا؛ وتحت <code>--strict-everything</code> تفحص تدفق الرموز مسبقًا وتُظهر <em>كل</em> مخالفات المُعدِّلات / بادئات العدسات الخاصة بـ Freally في مرور واحد (بدلًا من سلوك <code>parse_with</code> القائم على التوقف عند أول مخالفة). ويبقى المسار الساخن (حسابات المحلّل + <code>tokenize</code>) دون تغيير — فالأنواع الجديدة مشتقّة. وداخل المحلّل: اكتسب <code>Token</code> الحقل <code>byte_len: usize</code> كي تستطيع طبقة التقرير توليد المقاطع لكل رمز دون إعادة التقطيع. اعتمادية تشغيل جديدة <code>serde = workspace</code> للأنواع الجديدة (وهي أصلًا اعتمادية في مساحة العمل عبر ذاكرة الصوت المؤقتة في المرحلة 9). اختبارات جديدة: 67 اختبار وحدة في <code>freally-query</code> (المحلّل + الذاكرة المؤقتة + المُحسِّن + التقرير)، و17 حالة دخان للمرحلة 10 تحت <code>tests/smoke/phase_10_query.rs</code> (مُعاد تصديرها باسم <code>crates/freally-query/tests/phase_10_query.rs</code>)، و21 اختبارًا على بيانات لغة استعلام Freally في <code>crates/freally-query/tests/freally_dsl.rs</code> (≥200 استعلام مولَّد)، و3 اختبارات توافق مع voidtools بينها الاختبار الجديد <code>three_hundred_voidtools_queries_parse</code> (≥300 إجمالًا، منها أكثر من 120 منتقاة يدويًا + مولّد خوارزمي). وبوابة انحدار القاعدة الدائمة #8 هي مجموعة الاستعلامات الخمسين داخل المجموعة الأكبر التي تتجاوز 300.","changelog.07f1d2595011":"<strong>انحراف عن دليل البناء.</strong> قال توجيه المرحلة 10: «استبدل محلّل المرحلة 5 المرتجل بقواعد chumsky (أو pest).» اخترنا <strong>تقوية محلّل الانحدار التعاودي (recursive-descent) القائم</strong> بدلًا من إعادة كتابته، لأن واجهة المرحلة 5 عقد مطابق 1:1 لـ voidtools-Everything (القاعدة الدائمة #8) مع حالات حدّية متعددة — <code>(a)!b</code> يُحلَّل على أنه <code>(a) AND !b</code>؛ و<code>regex:</code> لا يستهلك إلا حتى القوس / المسافة التالية؛ و<code>attrib:HRA</code> <em>مجموعة</em> أعلام لا سلسلة؛ والتمييز بين عامل التصفية السريع <code>audio:</code> وبادئة العدسة يرتكز على فئة الرمز التالي. وإعادة ترميز كل غرابة في واجهة المُركِّبات (combinators) في chumsky 0.10 أو في قواعد PEG بملف <code>query.pest</code> دون انحدار في مجموعة الاستعلامات الخمسين مخاطرة عالية بمردود منخفض. يحقّق المحلّل المكتوب يدويًا بعد تقويته كل أهداف المرحلة 10 — تتبّع المقاطع لكل رمز عبر <code>Token::byte_len</code>، والأخطاء لكل رمز عبر <code>ParseReport::errors</code>، ووضع strict-everything، وبادئات العدسات، والمُحسِّن — دون أي خطر على عقد القاعدة الدائمة #8. ونموّ بيانات اختبار voidtools إلى أكثر من 300 <em>بوابة انحدار</em>، لا هدف نقل. وتقيّم جولة الأداء في المرحلة 13 ما إذا كان النقل إلى chumsky مجديًا حين تتوفّر أرقام القياس.","changelog.c2c6adddd634":"<strong>[كل المنصّات]</strong> مُستخرِج الصوت في المرحلة 9 (<code>freally-audio</code>) — مفكّك ترميز يعتمد على symphonia + قياس شدة الصوت وفق EBU R128 (عبر حزمة Rust الخالصة <code>ebur128 = &quot;0.1&quot;</code>) + نسبة الصمت + المدى الديناميكي، إضافةً إلى المُعدِّلات <code>lufs:</code> / <code>codec:</code> / <code>length:</code> / <code>rate:</code> / <code>silence:</code> / <code>dr:</code> في لغة الاستعلام. الواجهة العامة: <code>pub fn analyze_file(path: &amp;Path) -&gt; Result&lt;AudioAttributes, AudioError&gt;</code> إضافةً إلى <code>analyze_with_opts(path, AnalysisOpts)</code> لمسار الإلغاء التعاوني + ميزانية الوقت؛ و<code>pub trait AudioAttributesProvider</code> (تجريد على شكل ذاكرة مؤقتة يتحدث إليه المنفّذ)؛ و<code>pub struct AudioCache</code> (ذاكرة مؤقتة في الذاكرة + بصيغة JSON على القرص مع إبطال مرتبط بـ mtime، واستخراج أحادي التنفيذ (single-flight) عبر <code>Condvar</code>، وميزانية وقت لكل عملية استخراج قيمتها الافتراضية <code>DEFAULT_AUDIO_TIME_BUDGET = 5 s</code> كي لا يستطيع ملف صوتي عدائي الدوران بلا نهاية). تحمل <code>AudioAttributes</code> الحقل <code>codec</code> (المعرّف المختصر في symphonia بأحرف صغيرة — <code>flac</code> / <code>mp3</code> / <code>aac</code> / <code>vorbis</code> / <code>pcm_s16</code> / <code>alac</code> / …)، و<code>sample_rate</code>، و<code>channels</code>، و<code>bit_depth</code>، و<code>duration_ns</code>، و<code>lufs_integrated</code>، و<code>lufs_short_term_p99</code>، و<code>lufs_short_term_p10</code>، و<code>peak_dbfs</code> (الذروة الحقيقية عبر مُعيد التشكيل متعدد الأطوار 4× في حزمة ebur128 — ما يستوفي مواصفات دليل البناء دون مرشّح FIR مكتوب يدويًا)، و<code>silence_ratio</code> (النسبة المئوية للعيّنات تحت <code>−60 dBFS</code>؛ بحساب لكل عيّنة فتكون الرياضيات مستقلة عن عدد القنوات — انظر اختبار الانحدار <code>mono_and_correlated_stereo_report_same_ratio</code>)، و<code>dynamic_range_lu</code> (<code>short_term_p99 − short_term_p10</code>؛ تنهار إلى <code>0</code> للمقاطع الأقصر من 3 ثوانٍ التي لم تمتلئ نافذتها المنزلقة قصيرة المدى قط، مع إظهار المئينات بقيمة <code>f32::NEG_INFINITY</code> كي لا يطابق استعلام <code>lufs:&gt;x</code> زورًا أبدًا). تمرّ حقول LUFS / الذروة بالقيم غير المنتهية (<code>±∞</code> / <code>NaN</code>) ذهابًا وإيابًا عبر مساعد JSON مخصّص هو <code>lufs_serde</code> يستخدم ثلاث سلاسل حارسة (<code>&quot;-inf&quot;</code> / <code>&quot;+inf&quot;</code> / <code>&quot;nan&quot;</code>) — وإلا فإن سلوك <code>serde_json</code> الافتراضي القائم على <code>null</code> للقيم غير المنتهية كان سيُفسد الذاكرة المؤقتة بصمت؛ ويحرس <code>unknown_sentinel_rejects</code> مسار الخطأ محدّد النوع من الانحدار. تُحدّ القنوات بحدّ صارم هو <code>MAX_CHANNELS = 64</code> كي لا تفرض ترويسة مشوّهة تخصيصات هائلة لكل قناة قبل أن تلتقطها بيئة العزل. ويُظهر المحلّل الأخطاء محدّدة النوع <code>AudioError::NotAudio</code> / <code>Probe</code> / <code>Decode</code> / <code>Empty</code> / <code>Unsupported</code> / <code>Cancelled</code> / <code>Json</code> / <code>NonUtf8Path</code>. تضيف لغة الاستعلام المحلّلات <code>parse_audio_lufs</code> / <code>_codec</code> / <code>_length</code> / <code>_rate</code> / <code>_silence</code> / <code>_dr</code> التي تعيد استخدام شكل <code>split_op</code> من المرحلة 5 (<code>&lt;</code> / <code>&lt;=</code> / <code>&gt;</code> / <code>&gt;=</code> / <code>=</code> / المجرّد = <code>==</code>)؛ ويقبل <code>length:</code> الثواني و<code>mm:ss</code> و<code>hh:mm:ss</code> (مع حارس تجاوز الدقائق فيُرفض <code>length:1:90</code>)؛ ويقبل <code>rate:</code> الوحدتين <code>Hz</code> / <code>kHz</code>؛ ويقبل <code>silence:</code> النسب والنسب المئوية كلتيهما؛ ويرفض <code>dr:</code> القيم السالبة؛ و<code>duration:</code> اسم بديل لـ <code>length:</code>، و<code>samplerate:</code> اسم بديل لـ <code>rate:</code>، مراعاةً لعادات مستخدمي voidtools-Everything. يضيف المنفّذ <code>pub fn execute_with_audio(idx, similarity_opt, audio_opt, q, opts)</code> التي تكتشف الاستعلامات الحاملة لشروط صوتية عبر <code>has_audio_anywhere</code>، وتتطلب <code>AudioAttributesProvider</code> (وإلا أظهرت <code>QueryError::AudioProviderUnavailable</code> — خطأ محدّد النوع بدلًا من نتائج فارغة، بما يطابق عقد <code>SimilarityIndexUnavailable</code> في المرحلة 6)، وتبحث لكل صف عن <code>AudioAttributes</code> عبر المزوّد قبل تشغيل <code>eval_audio_predicate</code> على السمات المخزّنة مؤقتًا. تعمل تركيبات الصوت مع عدسة التشابه (<code>similar:bassdrop codec:flac length:&gt;3:00</code>) من الطرف إلى الطرف عبر مسار المنفّذ نفسه. تُجرى فحوص الإلغاء التعاوني مرة لكل حزمة symphonia (<code>Ordering::Acquire</code> على الذرّي الخاص بالإلغاء مقابل قلب <code>Release</code> المناظر من المشرف)؛ ويُعاد تعيين <code>SampleBuffer</code> عند <code>SymphoniaError::ResetRequired</code> كي تخصّص الحزمة التالية من جديد وفق <code>capacity()</code> الخاص بمفكّك الترميز الجديد (ما يتجنّب ذعرًا ناتجًا عن تأكيد السعة في <code>copy_interleaved_typed</code>). <code>TimeBudgetSupervisor</code> خيط منفصل يقلب علم الإلغاء عند انقضاء الميزانية، وينظّف نفسه عبر علم <code>done</code> يُقلب في <code>Drop</code> الخاص بالمشرف. اعتماديات تشغيل جديدة (كلها بتراخيص متساهلة، ومسموح بها في deny.toml): <code>symphonia = &quot;0.5&quot;</code> (MPL-2.0؛ مفكّك ترميز صوتي بـ Rust خالصة؛ الميزات المفعّلة: aac، alac، flac، isomp4، mp3، ogg، pcm، vorbis، wav، aiff، opt-simd — وOpus معطّل عمدًا لأن متجهات الاختبار في المصدر الأصلي تحمل بيانات ذات طابع GPL تحظرها سياسة deny؛ وسنعيد النظر حين تصدر حزمة Opus بترخيص MIT فقط)، و<code>ebur128 = &quot;0.1&quot;</code> (MIT/Apache-2.0؛ نسخة منقولة إلى Rust خالصة من libebur128)، إضافةً إلى اعتماديات مساحة العمل القائمة (<code>serde_json</code>، <code>parking_lot</code>، <code>tracing</code>، <code>thiserror</code>، <code>tempfile</code> للاختبارات). يغطي اختبار الدخان <code>tests/smoke/phase_09_audio.rs</code> (10 حالات — مُعاد تصديرها تحت <code>crates/freally-query/tests/phase_09_audio.rs</code>) رحلات الذهاب والإياب للمحلّل على بيانات اختبار WAV اصطناعية (موجة جيبية بتردد 1 kHz عند −23 dBFS تُقرأ ≈ −23 LUFS ضمن ±1 LU؛ والصمت الخالص يُقرأ <code>silence_ratio &gt; 0.99</code> وLUFS متكاملة = <code>f32::NEG_INFINITY</code>)، وذهاب وإياب ذاكرة الصوت المؤقتة على القرص + الإبطال حسب mtime، وتحليل مُعدِّلات الصوت الستة كلها، والمثال المركّب <code>lufs:&lt;-14 codec:flac length:&gt;3:00</code> من توجيه دليل البناء، والبوابة محدّدة النوع <code>AudioProviderUnavailable</code>، والتصفية من الطرف إلى الطرف عبر <code>execute_with_audio</code> مقابل <code>Index</code> في الذاكرة مملوء بملفات صوتية اصطناعية (موجات جيبية عالية + هادئة تتحقق من اتجاهي <code>lufs:&gt;-20</code> / <code>lufs:&lt;-20</code> كليهما)، ومطابقة إبسيلون <code>silence:=</code> على صوت صامت تمامًا، والسقوط عبر <code>NullProvider</code> (لا تطابق مُعدِّلات الصوت شيئًا بدلًا من الذعر)، ومسارات الإجهاض عبر علم الإلغاء / مشرف ميزانية الوقت. لا تُدخل المرحلة 9 أي سلاسل واجهة جديدة — فالمُعدِّلات على شكل أوامر (مثل <code>size:</code> / <code>ext:</code>)؛ ويبقى <code>xtask i18n-lint</code> ناجحًا عند 5 مفاتيح × 17 لغة غير مصدرية.","changelog.138d44119faa":"<strong>انحرافات عن دليل البناء.</strong> ملاحظتان مضمّنتان حول الاعتماديات التي لم تطابق دليل البناء حرفيًا:","changelog.c49ebee11cd1":"<strong>مفكّك ترميز الصوت</strong>: يسمّي دليل البناء «symphonia» — واستُخدم كما هو مكتوب. ويسمّي الدليل أيضًا «ebur128 (libebur128)»؛ ونحن نستخدم حزمة Rust الخالصة <code>ebur128 = &quot;0.1&quot;</code> (النسخة التي نقلها Sebastian Dröge) بدلًا من مكتبة C، لإبقاء مساحة العمل بـ Rust خالصة وتجنّب خطوات تثبيت مكتبات النظام في CI على أنظمة التشغيل الثلاثة.","changelog.fb9344590719":"<strong>دعم Opus</strong>: يسمّي دليل البناء Opus ضمن الصيغ المدعومة. ونحذفه في v0.19.84 لأن ميزة <code>opus</code> في symphonia تجلب متجهات اختبار ذات طابع GPL تتعارض مع حظر AGPL/GPL في <code>cargo-deny</code>. وتظهر حاوية OGG التي تحمل Opus كفشل <code>Probe</code>/<code>Decode</code> بدلًا من مطابقة مضلّلة؛ وسنعيد النظر حين يصدر مفكّك ترميز Opus بترخيص MIT فقط. ملاحظتان إضافيتان: <strong>مجموعة مطابقة EBU R128</strong>: يسمّي توجيه المرحلة 9 «مقاطع مرجعية معروفة الـ LUFS (مجموعة مطابقة EBU R128)، بتسامح ±0.1 LU» بوابةً. ويشحن اختبار الدخان أداة اختبار بموجة جيبية اصطناعية عند ±1 LU (موجة جيبية بتردد 1 kHz عند −23 dBFS تُقرأ ≈ −23 LUFS بعد ترجيح K)؛ ولا تُضمَّن مقاطع EBU المنشورة لأن مساحة العمل تسعى إلى عدم وجود أي بيانات اختبار ثنائية في الشجرة. وتضيف جولة الأداء في المرحلة 13 مجموعة المطابقة إلى مصفوفة CI حين يُحسم أمر بيانات الاختبار الثنائية. <strong>توصيل بيئة العزل</strong>: <em>لا</em> يعمل محلّل الصوت داخل <code>Sandbox</code> الخاص بـ <code>sandbox-extractors</code> من المرحلة 7 — فذلك المشرف مصمَّم لمُستخرِجات <code>Extractor</code> (ذات المخرجات النصية)، بينما يُنتج الصوت <code>AudioAttributes</code> منظّمة. وتشحن حزمة الصوت <code>TimeBudgetSupervisor</code> خاصًا بها بالميزانية الافتراضية نفسها البالغة 5 ثوانٍ؛ وعقد الإلغاء التعاوني مطابق (تحميل <code>Acquire</code> على الذرّي الخاص بالإلغاء لكل حزمة). أما عزل العمليات الفرعية للملفات الصوتية العدائية حقًا فهو تقييم المرحلة 13 نفسه الذي يغطي مسار فكّ ترميز PDF غير التعاوني.","changelog.1eeff18b7504":"<strong>[كل المنصّات]</strong> مُستخرِجات المستندات في المرحلة 8 (<code>freally-extractors::extractors</code>) — ستة مُستخرِجات قابلة للتوصيل مسجّلة في <code>Pipeline</code> من المرحلة 7، إضافةً إلى الدالتين المساعدتين <code>register_all(builder)</code> / <code>default_pipeline()</code> اللتين توصلانها بترتيب التوزيع. التغطية: <strong>(1) النص العادي + Markdown</strong> — يقرأ حتى <code>PLAIN_TEXT_CAP_BYTES = 5 MiB</code>، ويكتشف علامات ترتيب البايتات UTF-8 / UTF-16 LE / UTF-16 BE، ويفكّ ترميز المتن إلى UTF-8، ويدفع النص المفكوك إلى المصبّ (sink)؛ وهذا المُستخرِج هو أيضًا المسار الجامع للملفات التي لم يطالب بها أي مُستخرِج آخر (قائمة الامتدادات المسموح بها <code>.txt</code> / <code>.text</code> / <code>.md</code> / <code>.markdown</code> / <code>.mkd</code> / <code>.log</code> / <code>.rst</code> / <code>.adoc</code> / <code>.asciidoc</code> / <code>.rtf</code> إضافةً إلى استدلال <code>looks_like_text</code> على بايتات البداية الذي يتسامح مع بايت NUL شارد واحد ويرفض 2 فأكثر). <strong>(2) PDF</strong> — يحلّل <code>pdf-extract = &quot;0.10&quot;</code> (MIT، بـ Rust خالصة، من منظومة pdf-rs) المستند ويُصدر النص مع <code>U+000C</code> بين الصفحات كي تستطيع مقتطفات البحث ذكر أرقام الصفحات؛ وتظهر ملفات PDF المشفّرة / المحمية بكلمة مرور كـ <code>ExtractError::Unsupported(...)</code>، والمُدخلات المشوّهة كـ <code>ExtractError::Malformed(...)</code>. <strong>(3) Office</strong> — يستخدم <code>XlsxExtractor</code> الحزمة <code>calamine = &quot;0.34&quot;</code> (MIT) ويُصدر سطرًا واحدًا لكل خلية غير فارغة بصيغة <code>Sheet1!A1=value</code>؛ ويحلّل <code>DocxExtractor</code> و<code>PptxExtractor</code> ملفات OOXML مباشرةً عبر <code>zip = &quot;5&quot;</code> + <code>quick-xml = &quot;0.39&quot;</code> فلا نشحن اعتمادية <code>ooxmlsdk-rs</code> (انظر ملاحظة الانحراف). يعرض docx العناوين بصيغة Markdown (<code># Title</code>، <code>## Sub</code>، …) ويسطّح الجداول كصفوف <code>| cell | cell |\\n</code>؛ ويمرّ pptx على الشرائح بترتيبها الرقمي ويسبق كلًّا منها بـ <code># Slide N: &lt;title&gt;</code>. <strong>(4) الشيفرة</strong> — وقت تشغيل <code>tree-sitter = &quot;0.25&quot;</code> + 32 حزمة قواعد تغطي Rust وPython وJS وTS/TSX وGo وJava وC وC++ وC# وRuby وBash وLua وPHP وKotlin وScala وSwift وHaskell وOCaml وElixir وErlang وClojure وElm وDart وR وJulia وZig وNix وTOML وYAML وJSON وHTML وCSS وSQL. يُصدر كل تحليل أقسام <code>[lang]</code> / <code>[identifiers]</code> / <code>[strings]</code> / <code>[comments]</code>؛ وتُزال المعرّفات المكرّرة، وتحتفظ السلاسل + التعليقات بشكلها الحرفي فيطابق <code>content:&quot;hello world&quot;</code> المصدر الأصلي. وتُجرى فحوص الإلغاء التعاوني كل <code>CANCEL_CHECK_EVERY = 1024</code> عقدة كي يستطيع المشرف مقاطعة مرور طويل على الشجرة. <strong>(5) استعراض الأرشيفات</strong> — تعدّد <code>zip = &quot;5&quot;</code> + <code>sevenz-rust2 = &quot;0.21&quot;</code> + <code>tar = &quot;0.4&quot;</code> المُدخلات دون استخراج أي بايتات إلى القرص؛ وشكل المخرجات <code>archive.zip!path/to/inner.txt size=1234</code> لكل مُدخل (تسلّم الخدمة الخلفية هذا المسار الافتراضي للمُفهرِس فيطابق البحث عن <code>inner.txt</code> محتويات الأرشيف). حدّ أقصى صارم <code>MAX_ENTRIES = 100_000</code> لكل أرشيف؛ فأرشيف tar يضم 1M ملف لن يستنزف المصبّ وميزانية الوقت. <strong>(6) البيانات المنظّمة</strong> — تسطّح <code>serde_json</code> (من مساحة العمل) + <code>csv = &quot;1&quot;</code> + <code>serde_yaml_ng = &quot;0.10&quot;</code> البيانات إلى أسطر <code>key=value</code>: يستخدم JSON / YAML مفاتيح منقوطة (<code>address.zip=10001</code>) مع <code>[idx]</code> للمصفوفات؛ ويُصدر CSV أسطر <code>header=value</code> لكل صف غير صف العناوين، ويعود إلى <code>col0=value</code> عند غياب صف العناوين؛ ويسبق YAML متعدد المستندات كل مستند بـ <code>[doc=N]</code>. يغطي اختبار الدخان <code>tests/smoke/phase_08_doc_extractors.rs</code> (16 حالة) تسجيل <code>default_pipeline()</code>، وترتيب التوزيع (يتقدّم xlsx على استعراض الأرشيفات لـ <code>.xlsx</code>؛ ويتقدّم استعراض الأرشيفات لـ <code>.zip</code> العادي؛ ويتقدّم PDF بالبايتات السحرية <code>%PDF-</code>؛ ويلتقط النص العادي <code>.log</code>)، وإزالة BOM من النص العادي، وتسطيح JSON / CSV / YAML، وسرد zip بمسارات افتراضية، وتحويل أنماط العناوين في docx إلى Markdown، وترتيب شرائح pptx، والتقاط المعرّفات / السلاسل / التعليقات في مُستخرِج الشيفرة. اعتماديات تشغيل جديدة (كلها بتراخيص متساهلة، ومسموح بها في deny.toml): <code>pdf-extract = &quot;0.10&quot;</code> (MIT)، و<code>calamine = &quot;0.34&quot;</code> (MIT/Apache-2.0)، و<code>zip = &quot;5&quot;</code> (MIT)، و<code>quick-xml = &quot;0.39&quot;</code> (MIT)، و<code>sevenz-rust2 = &quot;0.21&quot;</code> (Apache-2.0)، و<code>tar = &quot;0.4&quot;</code> (MIT/Apache-2.0)، و<code>csv = &quot;1&quot;</code> (Unlicense/MIT)، و<code>serde_yaml_ng = &quot;0.10&quot;</code> (MIT/Apache-2.0)، و<code>tree-sitter = &quot;0.25&quot;</code> (MIT)، إضافةً إلى حزم القواعد الـ 32 المذكورة أعلاه (مزيج من MIT/Apache-2.0 — وترخيص كل حزمة قواعد مدرج في قائمة السماح في deny.toml).","changelog.eeeac6857769":"<strong>انحرافات عن دليل البناء.</strong> استُبدلت اعتماديتان مسمّاتان لإبقاء CI على أنظمة التشغيل الثلاثة ناجحًا وجدول اللغات الـ 18 في مساره:","changelog.56e5dde6f237":"<strong>استعراض الأرشيفات:</strong> يسمّي دليل البناء <code>compress-tools</code> (libarchive). وlibarchive مكتبة نظام — لا تأتي بها مضيفات CI على Windows، وتنسيق <code>vcpkg</code> كان سيعطّل المرحلة. نستخدم الثلاثي المكتوب بـ Rust خالصة (<code>zip</code> + <code>sevenz-rust2</code> + <code>tar</code>)؛ والنتيجة هي مخرجات المسار الافتراضي نفسها <code>archive.ext!entry size=N</code> التي يطلبها دليل البناء، دون أي اعتمادية على النظام.","changelog.bd47ec1aa5f2":"<strong>Office:</strong> يسمّي دليل البناء <code>ooxmlsdk-rs</code> لملفات docx + pptx. تلك الحزمة غير مُصانة على crates.io حتى 2026-Q1 وتفتقر إلى دعم Rust-2024. وOffice Open XML ليس سوى zip + XML، لذا نقرؤه مباشرةً بـ <code>zip</code> + <code>quick-xml</code>. الأثر الصافي: سطح هجوم أصغر (يقرأ المُفهرِس <em>النص</em> فقط، لا التنسيق / التخطيط / الكائنات المضمّنة) واعتمادية مثبّتة أقل بواحدة. ملاحظتان إضافيتان: لا تملك <strong>Dockerfile</strong> قواعد داخل الشجرة بعد، لأن <code>tree-sitter-dockerfile</code> الوحيدة المنشورة (0.2.0) لا تزال مرتبطة بوقت تشغيل tree-sitter 0.20، الذي يتعارض مع وقت تشغيلنا 0.25 عبر قاعدة <code>links = &quot;tree-sitter&quot;</code> في cargo؛ فتسقط ملفات Dockerfile إلى مُستخرِج النص العادي حاليًا، وسنعيد النظر حين يُعاد بناء القواعد على وقت التشغيل الأحدث. أما <strong>تعاون PDF</strong> فيجري على مستوى المستند كله لا لكل صفحة، لأن <code>pdf-extract</code> يحجب أثناء التحليل — فملف PDF ثقيل يتجاوز ميزانية الوقت في بيئة العزل ينتهي بتسريب خيط العامل (وهو العقد الموثّق لبيئة العزل مع المُستخرِجات غير التعاونية)؛ وعزل العمليات الفرعية هو موضوع تقييم المرحلة 13.","changelog.9aec97cffe7b":"<strong>[كل المنصّات]</strong> إطار عمل مُستخرِجات الصيغ في المرحلة 7 (<code>freally-extractors</code>) — السمة (trait)، والموزّع، وبيئة العزل لكل عملية استخراج، وطابور الاستخراج المحدود، ومخزن الكتل المعنون بالمحتوى، ووضع لكل مُستخرِج (Lazy / Eager / Disabled). تطابق الواجهة العامة توجيه المرحلة 7 في دليل البناء: <code>pub trait Extractor: Send + Sync { fn id(&amp;self) -&gt; ExtractorId; fn matches(&amp;self, path: &amp;Path, magic: &amp;[u8]) -&gt; bool; fn extract(&amp;self, path: &amp;Path, sink: &amp;mut TextSink) -&gt; Result&lt;ExtractionStats, ExtractError&gt;; }</code>. <code>Pipeline::builder().register(...).build()</code> هي خطوة التسجيل وقت التصريف؛ ويقرأ <code>Pipeline::dispatch_path(path)</code> حتى <code>MAGIC_HEAD_BYTES = 32</code> من بداية الملف المرشّح ويمرّ على المُستخرِجات المسجّلة بترتيب تسجيلها، متخطيًا أي مُستخرِج يكون <code>ExtractorMode</code> الفعلي له <code>Disabled</code>؛ ويتيح <code>Pipeline::replace_settings</code> للخدمة الخلفية تبديل الإعدادات فورًا دون إعادة تشغيل. يأخذ أسلوب السمة <code>Extractor::extract</code> معاملًا <code>&amp;mut TextSink</code> (كاتب بايتات محدود يمرّر علم الإلغاء الخاص ببيئة العزل عبر <code>is_cancelled()</code>)؛ والكتابات التي تتجاوز سقف النص لكل عملية استخراج تُرجع <code>SinkOverflow</code>، الذي يطويه المُستخرِج في <code>ExtractError::OutputTooLarge</code>. يُنشئ <code>Sandbox::execute(Arc&lt;dyn Extractor&gt;, PathBuf)</code> خيط عامل يستدعي المُستخرِج، بينما يعمل الخيط المستدعي مشرفًا — يستطلع <code>mpsc::sync_channel::recv_timeout</code> مع كل نبضة (افتراضيًا 100 ms)، ويفرض ميزانية الوقت البالغة 5 ثوانٍ بقلب علم الإلغاء وانتظار نافذة سماح واحدة للإلغاء (افتراضيًا 250 ms) قبل إرجاع <code>SandboxError::TimeBudget</code> بغض النظر عن انسحاب العامل من عدمه (المُستخرِجات غير التعاونية تسرّب خيط عامل مع كل خرق — عقد موثّق؛ وتقيّم المرحلة 13 عزل العمليات الفرعية للصيغ العدائية من أطراف ثالثة)؛ ويقرأ حارس RSS سطر <code>VmRSS:</code> من <code>/proc/self/status</code> على Linux، و<code>GetProcessMemoryInfo</code> على Windows، ولا يفعل شيئًا على macOS / أنظمة Unix الأخرى (توجيه المرحلة 7: «بلا أثر (macOS — الاعتماد على ميزانية الوقت)»). تفحص المُستخرِجات التعاونية <code>sink.is_cancelled()</code> بين بنود العمل الرئيسية وتُظهر <code>ExtractError::Cancelled</code>؛ وتطوي بيئة العزل ذلك مجددًا في <code>SandboxError::TimeBudget</code> أو <code>SandboxError::MemoryCeiling</code> حسب سبب الخرق الذي تتبّعته. <code>ExtractionQueue</code> كومة محدودة <code>BinaryHeap&lt;Entry&gt;</code> مفتاحها <code>(mtime_ns desc, FIFO seq)</code>، فتُوزَّع الملفات التي لُمست مؤخرًا أولًا وتخرج المُدخلات ذات mtime نفسه بترتيب إدخالها؛ ويُظهر <code>try_push</code> الخطأ <code>QueueError::Full(capacity)</code> حين تبلغ الكومة سعتها، و<code>QueueError::Closed</code> بعد <code>close()</code>، على غرار موقف أمان الإغلاق في <code>EventQueue</code> من المرحلة 4 (يوجد <code>closed</code> داخل <code>Mutex</code> نفسه الذي يحمي الكومة، فلا يستطيع <code>close()</code> متزامن أن يسابق فحص المنتظِر «هل الكومة فارغة؟»). يُنشئ <code>BlobStore::open(&lt;index_root&gt;/extracted)</code> الجذر؛ ويحسب <code>put(content)</code> المعرّف <code>BlobId = blake3(content)</code> (32 B تصبح 64 حرفًا ست عشريًا)، ويرمّز المحتوى بـ zstd (المستوى 3 افتراضيًا — تقيّم جولة الأداء في المرحلة 13 النزول إلى المستوى 1 إن هيمن الضغط على وقت الاستخراج)، ويكتب بشكل ذري عبر ملف مؤقت ثم إعادة تسمية داخل مجلد الشظية نفسه إلى <code>&lt;root&gt;/&lt;first2hex&gt;/&lt;full-hex&gt;</code>؛ ويربط <code>get(id)</code> الإطار المضغوط بالذاكرة (mmap) عبر <code>memmap2::Mmap</code> ويُرجع <code>Vec&lt;u8&gt;</code> المفكوك؛ ويمرّ <code>for_each(|id|)</code> على المخزن الحي، متخطيًا الملفات الجزئية <code>.tmp-*</code> وأسماء الملفات غير الست عشرية مع تسجيل بمستوى <code>warn</code>. إزالة التكرار متساوية القوة (idempotent) في <code>put</code> ضمنية ومعنونة بالمحتوى؛ وتغذّي <code>BlobStoreStats</code> (<code>puts</code> / <code>dedup_hits</code> / <code>get_hits</code> / <code>get_misses</code> / <code>bytes_written</code> / <code>bytes_decompressed</code>) جزء الحالة في الخدمة الخلفية. القيمة الافتراضية لـ <code>ExtractorMode::{Eager, Lazy, Disabled}</code> هي <code>Lazy</code> (فلا تستهلك الفهارس المُنشأة حديثًا المعالجَ في استخراج المحتوى قبل أن يُبدي المستخدم اهتمامًا بالبحث في المحتوى)؛ وتحمل <code>PipelineSettings</code> القيمة الافتراضية العامة إضافةً إلى <code>HashMap&lt;String, ExtractorMode&gt;</code> لتجاوزات كل مُستخرِج (مفتاحها <code>ExtractorId::as_str()</code> كي يبقى ملف JSON ثابتًا عبر ترقيات إصدارات الحزمة)، وميزانيات الوقت / الذاكرة / سقف المصبّ، وسعة الطابور. تمرّ الإعدادات ذهابًا وإيابًا عبر <code>serde_json</code> بسلاسة — وستتولّى نافذة الإعدادات في المرحلة 12 صيغة ملف JSON. اعتماديات تشغيل جديدة (كلها بتراخيص متساهلة، ومسموح بها في deny.toml): <code>zstd = &quot;0.13&quot;</code> (BSD-3-Clause؛ مجلوبة أصلًا عبر Tantivy، ومُعلنة هنا مباشرةً لمسار الضغط/فك الضغط في مخزن الكتل)، و<code>memmap2 = &quot;0.9&quot;</code> (MIT/Apache-2.0؛ مجلوبة أصلًا عبر <code>freally-index</code>، ومُعلنة هنا مباشرةً لقراءات mmap في مخزن الكتل)، و<code>blake3 = &quot;1&quot;</code> (CC0/Apache-2.0؛ بدائية العنونة بالمحتوى نفسها التي تستخدمها المرحلتان 4 + 6 أصلًا)، و<code>parking_lot = &quot;0.12&quot;</code> (MIT/Apache-2.0؛ تطابق بدائية الأقفال في بقية مساحة العمل)، و<code>serde_json = workspace</code> (MIT/Apache-2.0؛ لتسلسل الإعدادات)، و<code>windows-sys = &quot;0.59&quot;</code> مع الميزتين <code>Win32_System_ProcessStatus</code> + <code>Win32_System_Threading</code> على Windows لـ <code>GetProcessMemoryInfo</code>، و<code>libc = &quot;0.2&quot;</code> على Linux + macOS (تحليل <code>/proc/self/status</code> للقراءة فقط على Linux؛ ومجرد وجود على macOS لخطّافات RSS مستقبلية). يغطي اختبار الدخان <code>tests/smoke/phase_07_extractor_fw.rs</code> (17 حالة) توزيع Pipeline (الامتداد + البايتات السحرية + فوز أول مطابقة + تخطّي المعطَّل + قراءة البايتات السحرية من ملف قصير)، وSandbox (انطلاق ميزانية الوقت التعاونية ضمن الميزانية+فترة السماح + تمرير أخطاء المُستخرِج + مسار النجاح)، وQueue (الأولوية + الضغط العكسي + فكّ حجب pop-blocking عند الإغلاق)، وBlobStore (الذهاب والإياب + إزالة التكرار + التخطيط + الاستمرارية + ذهاب وإياب الترميز الست عشري)، وذهاب وإياب JSON للإعدادات.","changelog.d64d1c8e1432":"<strong>[كل المنصّات]</strong> عدسة تشابه أسماء الملفات في المرحلة 6 (<code>freally-similarity</code>) — فهرس للأسماء شبه المكرّرة قائم على MinHash للثنائيات (bigrams) + LSH بأبعاد 16×8. يفتح <code>SimilarityIndex::open(dir)</code> الملف <code>minhash.idx</code> أو ينشئه في المجلد المعطى؛ ويحوّل <code>upsert(file_id, name)</code> المُدخل إلى أحرف صغيرة، ويزيل الامتداد الأخير، ويحسب توقيع MinHash بصيغة <code>[u64; 128]</code> عبر عائلة تجزئة خطية حتمية (أزواج <code>(a, b)</code> مبذورة بـ SplitMix64، مع قيمة ثابتة <code>MINHASH_SEED = 0x534F5552_43455252</code>)، ويُدرج الصف في 16 نطاق LSH يضم كلٌّ منها 8 تجزئات؛ ويضع <code>remove(file_id)</code> علامة حذف (tombstone) على الصف ويزيله من كل نطاق، كي لا تُظهر إحالة قديمة في أحد النطاقات نتيجةً محذوفة. يستهلك <code>apply(&amp;[JournalEvent])</code> أحداث Create / Rename / Delete (أما Modify وAttrChange فبلا أثر لأن اسم الملف لم يتغيّر) ويعيد اشتقاق <code>file_id</code> عبر الاقتطاع نفسه <code>blake3(OsStr-bytes)[..8]</code> الذي يستخدمه <code>freally-index</code>، فيمرّ <code>SimilarityHit::file_id</code> ذهابًا وإيابًا عبر <code>Index::store::get_many</code> بسلاسة. يُجري <code>candidates(query, &amp;SimilarityOpts)</code> البحث في LSH، ويقيّم كل مرشّح بتقدير Jaccard، ويُسقط النتائج الأدنى من العتبة (افتراضيًا <code>DEFAULT_JACCARD_THRESHOLD = 0.30</code>)، ويرتّب تنازليًا حسب Jaccard مع فضّ التعادل بـ <code>file_id</code> تصاعديًا لمخرجات حتمية، ثم يقتطع إلى <code>candidate_cap</code>. يعيد <code>flush()</code> كتابة <code>minhash.idx</code> بشكل ذري عبر ملف مؤقت ثم إعادة تسمية — <code>[Header — 32 B] [Heap] [Rows: file_id u64 + name_off u32 + name_len u32 + signature [u64; 128]]</code> — بالبايتات السحرية <code>SRC-MNHS</code>، والإصدار 1؛ ويعيد <code>open()</code> بناء خريطة النطاقات من توقيع كل صف حي كي تبقى صيغة الملف على القرص مضغوطة (ملاحظة لجولة الأداء في المرحلة 13: حفظ خريطة النطاقات مباشرةً حين يصل SA-IS). أصبحت لغة الاستعلام (<code>freally-query</code>) تحلّل <code>similar:&lt;needle&gt;</code> إلى متغيّر جديد <code>ModifierKind::Similar(String)</code> — منقول من مجموعة <code>Reserved</code> في المرحلة 5؛ ونص البحث الفارغ (<code>similar:</code>) يُصدر الخطأ <code>ParseError::InvalidModifierValue</code>. توجّه نقطة الدخول الجديدة <code>execute_with(idx, similarity, q, opts)</code> أي استعلام يحمل مُعدِّل <code>Similar</code> في المستوى الأعلى عبر <code>SimilarityIndex</code> المعطى (مرشّحو LSH ← التحميل الكامل من SQLite ← تصفية الشروط المتبقية ← ترتيب تنازلي حسب Jaccard ما لم يختر المستخدم صراحةً <code>SortSpec</code> غير افتراضي)؛ وأصبحت <code>execute(idx, q, opts)</code> القديمة غلافًا رقيقًا حول <code>execute_with(idx, None, …)</code> يُرجع الخطأ محدّد النوع <code>QueryError::SimilarityIndexUnavailable</code> حين يصلها استعلام <code>similar:</code>، فيرى المستدعون رسالة واضحة بدلًا من نتائج فارغة. و<code>similar:</code> المدفون داخل <code>OR</code> / <code>NOT</code> / AND متداخل يُظهر <code>QueryError::UnsupportedSimilarPosition</code> — إذ تشحن المرحلة 6 نسخة أولى تقتصر على المستوى الأعلى، وترفع مرحلة المُحسِّن في المرحلة 10 هذا القيد. يرتّب المتغيّر الجديد <code>SortField::Relevance</code> تنازليًا حسب Jaccard حين يكون استعلام تشابه قيد التنفيذ، ويعود إلى الترتيب حسب <code>Name</code> في الاستعلامات الأخرى (بما يطابق دلالة «الترتيب حسب الصلة (Sort by Relevance)» في Everything من voidtools؛ وتُظهر واجهة المرحلة 11 هذا الخيار). تُحسب توقيعات أسماء الملفات على <em>الجذع</em> (الاسم دون الامتداد)، فيطابق المستخدمُ الذي يكتب <code>similar:report-final</code> الملفَّ المفهرس <code>report-final.pdf</code> بسلاسة دون عقوبة 4-5 ثنائيات بسبب <code>.pdf</code> في النهاية؛ ولا يزال الاسم الكامل بأحرف صغيرة محفوظًا في الكومة لأغراض التشخيص. بوابات مواصفات المرحلة 6: مجموعة اصطناعية من 5 000 اسم (ببذرة SplitMix64 حتمية) تضم 50 اسمًا شبه مكرّر معروفًا (زيادات اللاحقة <code>-v2</code> + إلحاق الوسم <code>-draft</code> + حذف حرف واحد بعيدًا عن ركبة منحنى LSH عند Jaccard ≈ 0.73) تبلغ حدّ الاستدعاء الأدنى في المواصفات وهو 95 % (<code>crates/freally-similarity/tests/recall.rs</code>)؛ ويغطي اختبار الدخان <code>tests/smoke/phase_06_similarity.rs</code> ثوابت التحليل/التوجيه/التركيب/الحفظ/موضع الخطأ. اعتماديات تشغيل جديدة (كلها بتراخيص متساهلة، ومسموح بها في deny.toml): <code>blake3 = &quot;1&quot;</code> (مجلوبة أصلًا عبر <code>freally-index</code>؛ ومُعلنة هنا مباشرةً لاشتقاق file_id)؛ وسلسلة <code>parking_lot</code> / <code>thiserror</code> / <code>tracing</code> / <code>freally-journal</code> القائمة.","changelog.1b0bc0f992e4":"<strong>[كل المنصّات]</strong> هيكل المرحلة 0: مساحة عمل Cargo؛ وغلاف واجهة بـ Tauri 2 + Svelte 5 بحجم 1100×720 بسمة داكنة؛ و18 ملف <code>.ftl</code> أوليًا للغات؛ و<code>xtask</code> (<code>i18n-lint</code>، <code>third-party-notices</code>، <code>icon-build</code>، <code>release</code>)؛ وCI على GitHub Actions لأنظمة التشغيل الثلاثة؛ وسياسة تراخيص <code>deny.toml</code> (AGPL محظور حظرًا قاطعًا)؛ وعائلة أيقونات بعدسة مكبّرة بلون أزرق فاتح. سيكون أول وسم عام <strong>v0.19.84</strong>.","changelog.24697757938e":"<strong>[Windows فقط]</strong> مشترك سجل USN لـ NTFS في المرحلة 1 (<code>freally-journal-win</code>): يستعلم <code>JournalSubscriber::open</code> عن السجل عبر <code>FSCTL_QUERY_USN_JOURNAL</code>، ويعدّد <code>bootstrap()</code> جدول MFT عبر <code>FSCTL_ENUM_USN_DATA</code>، ويبثّ <code>subscribe()</code> الأحداث التزايدية عبر <code>FSCTL_READ_USN_JOURNAL</code>، ويُحفظ مؤشر لكل وحدة تخزين (الرقم التسلسلي لوحدة التخزين + معرّف السجل + USN التالي) تحت <code>%LOCALAPPDATA%\\Freally\\cursors\\&lt;serial&gt;.json</code> بحفظ ذري عبر إعادة التسمية. وتُربط أعلام الأسباب بـ <code>JournalEvent::{Create, Modify, Delete, Rename, AttrChange}</code>. وسيوازنه مشترك FSEvents لـ macOS في المرحلة 2 ومشترك inotify/fanotify لـ Linux في المرحلة 3.","changelog.b71505a013b6":"<strong>[Windows فقط]</strong> توصيل <code>freally-indexd</code> بمدير التحكم بالخدمات (Service Control Manager): تسجّل الأوامر الفرعية <code>install</code> / <code>uninstall</code> / <code>service</code> الخدمة <code>Freally-Indexd</code> في Windows وتشغّلها (بدء تلقائي، وتقبل أمر الإيقاف من SCM). وتملأ المرحلة 4 المشترك لكل وحدة تخزين + نواة الفهرس داخل جسم الخدمة.","changelog.cc1fb2dcf2b9":"<strong>[macOS فقط]</strong> مشترك سجل FSEvents في المرحلة 2 (<code>freally-journal-mac</code>): يحلّ <code>JournalSubscriber::open</code> جذر مراقبة مطلقًا، ويلتقط <code>stat.st_dev</code> + <code>statfs.f_fstypename</code> الخاصين به، ويحمّل (أو ينشئ عند أول تشغيل) مؤشرًا لكل مراقبة تحت <code>~/Library/Application Support/Freally/cursors/&lt;root_hash&gt;.json</code>. يمرّ <code>bootstrap()</code> على الشجرة ويُصدر أحداث <code>JournalEvent::Create</code> اصطناعية. ويُنشئ <code>subscribe()</code> خيط CFRunLoop مخصّصًا يشغّل <code>FSEventStreamCreate(latency=0.5s, FileEvents | NoDefer | UseCFTypes | WatchRoot)</code>، ويصنّف قناع أعلام كل دفعة عبر جدول التحويل من أعلام FSEvents إلى <code>JournalEvent</code>، ويُجري <strong>مزاوجة إعادة التسمية لكل دفعة</strong> (بمطابقة نصفي زوج <code>ItemRenamed</code> حسب inode)، ويعيد فحص الأشجار الفرعية مباشرةً عند <code>MustScanSubDirs</code>، ويحفظ <code>last_event_id</code> للاستئناف عبر مرات إعادة التشغيل. وتتدهور أزواج إعادة التسمية العابرة للدفعات إلى <code>Delete + Create</code> (ملاحظة لجولة الأداء في المرحلة 13). اعتماديات التشغيل <code>core-foundation = &quot;0.10&quot;</code> و<code>core-foundation-sys = &quot;0.8&quot;</code> و<code>fsevent-sys = &quot;4&quot;</code> و<code>libc = &quot;0.2&quot;</code> — كلها MIT/Apache-2.0، ومسموح بها في deny.toml.","changelog.4fcde431e77b":"<strong>[macOS فقط]</strong> توصيل <code>freally-indexd</code> كوكيل launchd: تسجّل الأوامر الفرعية <code>install</code> / <code>uninstall</code> / <code>service</code> وكيل launchd لكل مستخدم في <code>~/Library/LaunchAgents/io.mikeweaver.freally.indexd.plist</code> مع <code>RunAtLoad=true</code> + <code>KeepAlive=true</code> وتشغّله. وتملأ المرحلة 4 المشترك لكل جذر + نواة الفهرس داخل جسم الوكيل. ويطبع وضع المقدّمة <code>run --root &lt;path&gt;</code> أحداث FSEvents إلى stdout للفحص اليدوي / في اختبارات الدخان.","changelog.051c4dd1753a":"<strong>[كل المنصّات]</strong> أصبحت واجهة <code>freally-journal</code> تعيد تصدير <code>open</code> / <code>JournalEvent</code> / <code>JournalError</code> / <code>JournalSubscriber</code> المرجعية من <code>freally-journal-mac</code> عند <code>cfg(target_os = &quot;macos&quot;)</code>. ولا يزال Linux يستخدم الواجهة محدّدة النوع لكنها فارغة التنفيذ؛ وستستبدلها المرحلة 3.","changelog.8b1b0978d0a2":"<strong>[Linux فقط]</strong> مشترك سجل inotify+fanotify في المرحلة 3 (<code>freally-journal-lin</code>): يحلّ <code>JournalSubscriber::open</code> جذر مراقبة مطلقًا، ويلتقط <code>stat.st_dev</code> الخاص به + اسم نظام الملفات المستخرج من الرقم السحري <code>statfs.f_type</code> (ext4/btrfs/zfs/xfs/f2fs/tmpfs/...)، ويكتشف <code>CAP_SYS_ADMIN</code> عبر سطر <code>CapEff:</code> في <code>/proc/self/status</code>، ويحمّل (أو ينشئ عند أول تشغيل) مؤشرًا لكل مراقبة تحت <code>~/.local/share/freally/cursors/&lt;root_hash&gt;.json</code> (مع مراعاة XDG_DATA_HOME). يمرّ <code>bootstrap()</code> على الشجرة عبر <code>getdents64(2)</code> الخام (أسرع من <code>read_dir</code> على الأشجار الضخمة) مع حارس دورات <code>(st_dev, st_ino)</code> ويُصدر أحداث <code>JournalEvent::Create</code> اصطناعية. ويُنشئ <code>subscribe()</code> خيطًا مخصّصًا يشغّل الواجهة الخلفية المختارة: <strong>inotify</strong> (الافتراضية، دون امتيازات) — <code>inotify_add_watch</code> تعاودي يغطي الإنشاء/التعديل/الإغلاق بعد الكتابة/الحذف/النقل/السمات، مع إطلاق <code>IN_Q_OVERFLOW</code> إعادة فحص كاملة للشجرة عبر <code>getdents64</code>؛ أو <strong>fanotify</strong> (يتطلب CAP_SYS_ADMIN) — استدعاء <code>fanotify_mark(FAN_MARK_FILESYSTEM)</code> واحد مع <code>FAN_REPORT_DFID_NAME</code> فيصمد تتبّع إعادة التسمية عند عبور الأحجام الفرعية في Btrfs وعبر overlayfs، وهو ما لا يستطيع inotify إعادة إنتاجه. ويحاكي مصنّف أقنعة inotify أسبقية أسباب USN في المرحلة 1 (<code>Delete &gt; Create</code>، <code>Rename &gt; Create</code>، و<code>IN_CLOSE_WRITE</code> يحسم <code>Modify</code>). مزاوجة إعادة التسمية لكل دفعة عبر cookie في inotify / سجل المعلومات <code>OLD_DFID_NAME</code> في fanotify؛ وتتدهور الانقسامات العابرة للدفعات إلى <code>Delete + Create</code> (ملاحظة لجولة الأداء في المرحلة 13). ويسقط fanotify عند <code>EPERM/EINVAL/ENOSYS</code> وقت التهيئة إلى inotify، فتبقى الأنوية الأقدم من 5.17 (التي لا تدعم <code>FAN_REPORT_DFID_NAME</code>) والبناءات بـ <code>CONFIG_FANOTIFY=n</code> عاملة. اعتمادية التشغيل <code>libc = &quot;0.2&quot;</code> فقط — مسار استدعاءات نظام خام خالص.","changelog.f558e7c13bef":"<strong>[Linux فقط]</strong> توصيل <code>freally-indexd</code> كوحدة systemd للمستخدم: تكتب الأوامر الفرعية <code>install</code> / <code>uninstall</code> / <code>service</code> الملف <code>~/.config/systemd/user/freally-indexd.service</code> مع <code>Type=simple</code> + <code>Restart=always</code> + <code>WantedBy=default.target</code> (وفق مواصفات المرحلة 3) وتشغّل <code>systemctl --user enable --now</code>. ويضع <code>ExecStart</code> مسار الملف التنفيذي بين علامتي اقتباس، فيصمد تثبيت بـ <code>--binary &quot;/path with spaces/freally-indexd&quot;</code> أمام محلّل وحدات systemd الحسّاس للمسافات. وتملأ المرحلة 4 المشترك لكل جذر + نواة الفهرس داخل جسم الخدمة. ويطبع وضع المقدّمة <code>run --root &lt;path&gt;</code> أحداث inotify/fanotify إلى stdout للفحص اليدوي / في اختبارات الدخان.","changelog.c891685c91b5":"<strong>[Linux فقط]</strong> سياسة Polkit في <code>crates/freally-indexd/polkit/io.mikeweaver.freally.policy</code> تُعلن الإجراء <code>io.mikeweaver.freally.elevate</code> لتدفق الترقية الاختيارية إلى fanotify. يطلب <code>auth_self_keep</code> (≈5 min) من المستخدم النشط كلمة مروره الخاصة؛ وتثبّت التعليقات التوضيحية <code>org.freedesktop.policykit.exec.path</code> + <code>argv1</code> الأمرَ <code>/usr/local/bin/freally-indexd elevate</code> فلا يمكن إعادة توظيف معرّف الإجراء ضد ملف تنفيذي مختلف. ويشحن مشرفو التوزيعات الملف في <code>/usr/share/polkit-1/actions/</code>.","changelog.5ce16f33ef5f":"<strong>[كل المنصّات]</strong> أصبحت واجهة <code>freally-journal</code> تعيد تصدير <code>open</code> / <code>JournalEvent</code> / <code>JournalError</code> / <code>JournalSubscriber</code> / <code>WatchCursor</code> المرجعية من <code>freally-journal-lin</code> عند <code>cfg(target_os = &quot;linux&quot;)</code>. وتحتفظ أهداف Unix الأخرى (FreeBSD وOpenBSD وillumos) بالواجهة <code>portable_stub</code> محدّدة النوع لكنها فارغة التنفيذ.","changelog.369e1b7b5e7f":"الإصلاحات (جولة مراجعة المرحلة 8)","changelog.600f17cedae8":"<strong>[كل المنصّات]</strong> أصبح مُستخرِج النص العادي في المرحلة 8 يكتشف الترميز <em>قبل</em> تشغيل الاقتطاع الناتج عن تجاوز السقف. كانت النسخة السابقة تُجري دون شرط تقليمًا بحلقة <code>from_utf8</code> على المخزن المؤقت المقتطع بغض النظر عن الترميز — فبالنسبة لمُدخل UTF-16 تجاوز سقف 5 MiB (≈ 2.5 M نقطة ترميز)، كانت الحلقة تنزع البايتات حتى تجد بادئة بشكل UTF-8، تاركةً المخزن المؤقت غالبًا بطول فردي من البايتات، فيرفضه <code>decode</code> بعدها على أنه <code>ExtractError::Malformed</code>. ومع الاقتطاع الواعي بالترميز، يُقلَّم UTF-16 إلى حدّ بايت زوجي ويُقلَّم UTF-8 إلى حدّ نقطة ترميز عبر الدالة المساعدة الجديدة <code>trim_to_utf8_boundary</code>. ويثبّت اختبار الانحدار الجديد <code>utf16_le_overshoot_truncates_at_even_boundary_not_malformed</code> هذا العقد.","changelog.29036e7ef80a":"<strong>[كل المنصّات]</strong> أصبح مُستخرِجا استعراض الأرشيفات والبيانات المنظّمة في المرحلة 8 يعقّمان محارف التحكم الخاصة بفواصل الأسطر (<code>\\n</code> / <code>\\r</code> / <code>\\0</code>) في أسماء مُدخلات الأرشيفات، وقيم حقول CSV، وقيم السلاسل المفردة (scalar) في JSON / YAML عبر الدالة المساعدة الجديدة <code>extractors::util::sanitize_inline</code>. كان بإمكان مُدخل zip / 7z / tar عدائي سابقًا أن يُعلن اسمًا يحتوي على <code>\\n</code> فيحقن صفوفًا وهمية في كتلة البحث (مُدخل واحد ينتحل صفة كثيرين)؛ وكان الخلل نفسه موجودًا في القيم المفردة لـ CSV / JSON / YAML حيث تحمل الحقول المقتبسة أسطرًا جديدة مضمّنة بشكل مشروع. ويحافظ الخرج المعقَّم على قابلية الاستدعاء في البحث بتهريب البايتات (<code>\\\\n</code> / <code>\\\\r</code> / <code>\\\\0</code>) بدلًا من إسقاطها. وتغطي اختبارات الانحدار الجديدة <code>entry_name_with_newline_is_sanitized</code> (للأرشيف) و<code>csv_field_with_newline_is_sanitized</code> و<code>json_string_value_with_newline_is_sanitized</code> العقد على كل سطح.","changelog.85af001a0e9a":"<strong>[كل المنصّات]</strong> أصبح محلّلا docx + pptx في المرحلة 8 يفحصان <code>sink.is_cancelled()</code> وفق ميزانية لكل حدث بدلًا من كل فقرة (docx) / كل شريحة فقط (pptx). كان ملف docx عدائي يحتوي على <code>&lt;w:p&gt;</code> عملاق واحد (آلاف مقاطع <code>&lt;w:t&gt;</code> المتسلسلة) يقضي ثوانيَ داخل <code>parse_docx_body</code> دون أن يستجيب لعلم الإلغاء؛ ولم يكن في محلّل XML الشرائح في pptx أي فحص داخلي للإلغاء على الإطلاق. يعدّ الإصلاح كل حدث من quick-xml ويختبر العلم كل 32 حدثًا — والتحميل نفسه عملية ذرّية واحدة <code>Ordering::Relaxed</code> بكلفة أقل من نانوثانية. تبقى نافذة السماح في بيئة العزل من المرحلة 7 شبكة الأمان لأسوأ الحالات، لكن الإيقاف التعاوني أصبح ينطلق ضمن ميزانية محدودة بغض النظر عن شكل XML المُدخل.","changelog.85445058bd37":"<strong>[كل المنصّات]</strong> أصبح مُستخرِج docx في المرحلة 8 يحذف الفقرات ذات نمط العنوان الخالية من النص. كانت النسخة السابقة تُصدر <code># \\n\\n</code> مجرّدًا (أو مستوى أعمق من علامات #) في كتلة البحث لكتل <code>&lt;w:p&gt;</code> الفارغة التي تحمل <code>&lt;w:pStyle w:val=&quot;HeadingN&quot;/&gt;</code>؛ والرموز اللاحقة مثل <code>#</code> ضجيج يُحسب من سقف المصبّ دون أي فائدة للاستدعاء. ويغطي ذلك اختبار الانحدار الجديد <code>docx_skips_empty_heading_paragraphs</code>.","changelog.1dad52d35905":"<strong>[كل المنصّات]</strong> أصبح مُستخرِجا الشيفرة والنص العادي في المرحلة 8 يقلّمان المخازن المؤقتة المتجاوزة للسقف إلى حدّ نقطة ترميز UTF-8 في O(1) عبر التراجع المشترك على بايتات الاستمرار في <code>trim_to_utf8_boundary</code>، بدلًا من الحلقة السابقة <code>while !std::str::from_utf8(&amp;buf).is_ok() { buf.pop(); }</code> التي كانت تعيد فحص المخزن المؤقت كاملًا البالغ 4 / 5 MiB مع كل نزع (O(N²) في أسوأ الحالات). وتحرس ستة اختبارات وحدة في <code>extractors::util::tests</code> من الانحدار حالاتِ نقطة الترميز الكاملة، ونقطة الترميز الجزئية، وحدّ ASCII، والبايتات الاستمرارية كلها، والمخزن المؤقت الفارغ.","changelog.4e47265991ba":"<strong>[كل المنصّات]</strong> اكتسبت جداول docx في المرحلة 8 (<code>&lt;w:tbl&gt;</code> / <code>&lt;w:tr&gt;</code> / <code>&lt;w:tc&gt;</code>) تغطية اختبارية صريحة. كان <code>parse_docx_body</code> يعالج وسوم الجداول بالفعل، لكن لم يكن أي اختبار يمرّ بهذا المسار؛ وأي انحدار هناك كان سيُسقط بصمت محتويات الجداول من نتائج البحث في كل ملف docx يحتوي على جدول. ويثبّت الاختبار الجديد <code>docx_renders_tables_as_pipe_rows</code> العرض بصيغة <code>| cell | cell |</code>.","changelog.f8937347b501":"<strong>[كل المنصّات]</strong> اكتسب YAML متعدد المستندات في المرحلة 8 (فواصل <code>---</code>) تغطية اختبارية صريحة. كان مسار <code>flatten_yaml</code> يُصدر مفاتيح مسبوقة بـ <code>[doc=N]</code> لكن لم يكن أي اختبار يغطي منطق البادئة؛ ويضمن الاختبار الجديد <code>flattens_multi_document_yaml_with_doc_prefix</code> ألا تتمكّن إعادة هيكلة مستقبلية من دمج حدود المستندات بصمت.","changelog.585aef173030":"الإصلاحات (جولة مراجعة المرحلة 5)","changelog.0aa74d3eaa36":"<strong>[كل المنصّات]</strong> أصبح محلّل الاستعلامات في المرحلة 5 يعامل <code>!</code> بعد <code>)</code> كنفي بادئ (NOT) — فيُحلَّل <code>(a)!b</code> على أنه <code>(a) AND !b</code> بما يطابق السلوك الموثّق في voidtools-Everything. في السابق كان فحص حدود البايتات والرموز يُغفل <code>RParen</code>، فكان <code>!b</code> اللاحق ينهار إلى نص حرفي واحد <code>!b</code> ويسقط النفي بصمت (انحدار عن القاعدة الدائمة #8). ويثبّت اختبار المحلّل الجديد <code>bang_after_rparen_is_not</code> هذا العقد.","changelog.7a304dd66705":"<strong>[كل المنصّات]</strong> لم تعد ذاكرة الخطط المؤقتة في المرحلة 5 تعدّل الخطة المخزّنة عند تفعيل <code>match_mode.match_path</code>. أصبح مسح البذرة الذي يتيح لبحث المسار تجاوز المرشّح المسبق بالثلاثيات يجري وقت التنفيذ فقط — فتبقى <code>ExecPlan</code> دالة خالصة لسلسلة الاستعلام، ولم يعد بإمكان مستدعيين متزامنين بالاستعلام نفسه وإعدادات <code>match_path</code> مختلفة أن يُفسد أحدهما خطة الآخر المخزّنة. ويغطي ذلك اختبار التوصيل الجديد <code>plan_cache_survives_match_path_toggle</code>.","changelog.fa995dcc342d":"<strong>[كل المنصّات]</strong> أصبح <code>parse_iso_day</code> في المرحلة 5 يرفض الأيام المستحيلة تقويميًا (30 فبراير، و31 أبريل، و29 فبراير في سنة غير كبيسة، …) مسبقًا عبر مدقّق جديد <code>days_in_month</code> (كانت حسابات أيام الحقبة لـ Howard Hinnant تقبل أي يوم 1-31 في أي شهر، مرحّلةً الفائض إلى الأمام بصمت). وvoidtools يرفض هذه الأيام — انحدار عن القاعدة الدائمة #8. ويغطي اختبار المحلّل الجديد <code>invalid_calendar_days_reject</code> حالات السنة الكبيسة + نهاية الشهر.","changelog.a94bbcf610a6":"<strong>[كل المنصّات]</strong> وُسّعت قائمة المُعدِّلات المحجوزة في المرحلة 5 لتشمل رموز voidtools-Everything المألوفة بحكم العادة (<code>wfn:</code>، <code>wholefilename:</code>، <code>case:</code>، <code>count:</code>، <code>dupe:</code>، <code>nodiacritics:</code>) فيحصل المستخدمون الذين يكتبونها على <code>QueryError::UnsupportedModifier</code> محدّد النوع وقت التنفيذ بدلًا من خطأ تحليل. «يُحلَّل لكنه يفشل بصوت عالٍ» هو عقد القاعدة الدائمة #8 إلى أن يصدر كلٌّ من هذه المفاتيح في المرحلة التي تملك عدسته. ويغطي اختبار المحلّل الجديد <code>voidtools_reserved_toggles_parse</code> هذه العائلة.","changelog.6543bc5ccebd":"<strong>[كل المنصّات]</strong> أصبح <code>eval_full</code> في المرحلة 5 يحوّل مسار المرشّح إلى أحرف صغيرة مرة واحدة لكل صف عند تفعيل <code>match_path</code>، بدلًا من إعادة التحويل لكل عقدة ابن في AND / OR — إذ رُفعت سلسلة المسار بالأحرف الصغيرة إلى <code>NameEvaluator::matches_full</code> وتُمرَّر عبر <code>eval_full</code> بوصفها <code>Option&lt;&amp;str&gt;</code>. ما يلغي تخصيص <code>to_lowercase()</code> لكل ابن في AND كان يتضخّم مع عمق الاستعلام.","changelog.cd2b5074233d":"<strong>[كل المنصّات]</strong> أصبح <code>eval_modifier::Reserved</code> في المرحلة 5 يستدعي <code>debug_assert!</code> عند بلوغه — فـ <code>validate_supported</code> هو البوابة الموثّقة في أعلى <code>execute()</code>، ووصول مُعدِّل Reserved إلى التقييم يعني أن مستدعيًا بنى شجرة <code>Query</code> AST يدويًا وتجاوز البوابة. الفرع السابق الذي يُرجع <code>false</code> بصمت شيفرة ميتة في مسارات الاستدعاء المدعومة، وأصبح الآن يفشل بصوت عالٍ تحت <code>cfg(debug_assertions)</code>.","changelog.dc40e0e57b5d":"<strong>[كل المنصّات]</strong> عدسة أسماء الملفات في المرحلة 5 (<code>freally-query</code>) — محلّل لغة استعلام على شكل voidtools-Everything + منفّذ فوق فهرس المرحلة 4. يبني <code>parse(s)</code> شجرة <code>Query</code> AST تغطي مصطلحات السلاسل الفرعية الحرفية / أحرف البدل (<code>*</code>، <code>?</code>) / التعابير النمطية (البادئة <code>regex:</code>)، والربط المنطقي (<code>AND</code> / <code>OR</code> / <code>NOT</code> / البادئة <code>!</code>، وAND ضمني بين الذرّات المتجاورة، والمجموعات بين أقواس)، وشروط المُعدِّلات: <code>size:</code> (مع <code>&gt;</code> و<code>&lt;</code> و<code>&gt;=</code> و<code>&lt;=</code> و<code>=</code>، والوحدات <code>b</code>/<code>kb</code>/<code>mb</code>/<code>gb</code>/<code>tb</code>)، و<code>date:</code> (الأسماء البديلة النسبية <code>today</code> / <code>yesterday</code> / <code>thisweek</code> / <code>lastweek</code> / <code>thismonth</code> / <code>lastmonth</code> / <code>thisyear</code> / <code>lastyear</code> إضافةً إلى الصيغة المطلقة <code>YYYY-MM-DD</code> مع عامل مقارنة)، و<code>ext:</code> (امتداد واحد أو قائمة مفصولة بـ <code>;</code>، مع إزالة <code>.</code>)، و<code>attrib:</code> (مجموعة الأحرف في Windows: <code>R</code>/<code>H</code>/<code>S</code>/<code>A</code>/<code>D</code>/<code>C</code>/<code>E</code>/<code>T</code>/<code>O</code>/<code>L</code>)، و<code>path:</code> / <code>parent:</code> / <code>child:</code> (مطابِقات سلاسل فرعية؛ مع احترام الاسمين البديلين <code>name:</code> / <code>folder:</code>). تتوسّع الأسماء البديلة لعوامل التصفية السريعة <code>audio:</code> / <code>video:</code> / <code>image:</code> / <code>document:</code> / <code>executable:</code> / <code>archive:</code> إلى مجموعات امتدادات محدّدة مسبقًا. أما مُعدِّلات العدسات المستقبلية (<code>content:</code> / <code>lufs:</code> / <code>codec:</code> / <code>channels:</code> / <code>samplerate:</code> / <code>length:</code> / <code>similar:</code> / <code>duration:</code> / <code>type:</code> / <code>lang:</code>) فتُحلَّل لكن <code>validate_supported</code> يحجبها، مُظهرًا <code>QueryError::UnsupportedModifier</code> إلى أن تصدر المرحلة التي تملكها. يخطّط <code>execute(idx, query, ExecOpts)</code> للاستعلام (تصبح أطول سلسلة فرعية حرفية بذرة الثلاثيات؛ وOR يحوّل البذرة إلى فحص للصفوف الحية)، ويسحب المرشّحين من فهرس الأسماء المخصّص عبر واجهتي البايتات المستعارة الجديدتين <code>for_each_candidate_named</code> / <code>for_each_live</code>، ويشغّل شروط جانب الأسماء، ويحمّل الناجين بالكامل عبر الجلب المجمّع الجديد بعبارة IN في <code>Store::get_many</code>، ويقيّم شروط السجل الكامل، ويطبّق <code>SortSpec</code> (الاسم / المسار / الحجم / التاريخ / النوع / الامتداد، تصاعديًا/تنازليًا)، ويبثّ النتائج عبر <code>ResultSet::first_batch</code> / <code>collect</code>. تُطبَّق مفاتيح <code>MatchMode</code> (<code>match_case</code> / <code>whole_word</code> / <code>match_path</code> / <code>match_diacritics</code>) طبقةً فوق الأخرى وقت التنفيذ؛ ويوسّع <code>match_path</code> هدف البحث ليشمل المسار الكامل الموحَّد بتخطّي المرشّح المسبق لفهرس الأسماء (ملاحظة لجولة الأداء في المرحلة 13)؛ ويزيل <code>match_diacritics: false</code> العلامات المركّبة عبر NFKD قبل مقارنة السلاسل الفرعية. وذاكرة الخطط المؤقتة <code>PlanCache</code> من نوع LRU بـ 16 إدخالًا (<code>PlanCache::default16</code>) مفتاحها سلسلة الاستعلام المشذّبة، وتعيد استخدام AST المحلَّلة + الخطة عند إعادة الكتابة المتكرّرة. اعتماديات تشغيل جديدة (كلها بتراخيص متساهلة، ومسموح بها في deny.toml): <code>regex = &quot;1&quot;</code> (MIT/Apache-2.0)، و<code>unicode-normalization = &quot;0.1&quot;</code> (MIT/Apache-2.0). واستبدل <code>name_index</code> في <code>crates/freally-index</code> تقاطع الثلاثيات من <code>BTreeSet</code> بدمج بمؤشرين على قوائم إحالة مرتّبة (ملاحظة الأداء PERF في دليل البناء §<code>name_index</code>)، ويعرض <code>name_bytes</code> / <code>for_each_candidate_named</code> / <code>for_each_live</code> للعدسة؛ ويقسّم <code>Store::get_many</code> المعرّفات إلى دفعات من 250 لكل عبارة IN للبقاء تحت <code>SQLITE_MAX_VARIABLE_NUMBER</code> في SQLite. يولّد <code>xtask gen-fixture</code> تدفقًا حتميًا من سجلات الملفات ببذرة SplitMix64 لاختبار أداء المرحلة 5 (<code>cargo bench -p freally-query --bench filename_lens</code>)؛ ويطبع الاختبار P50 / P99 لكل سيناريو مع علامات FAIL، ولا يخرج برمز غير صفري إلا عند <code>FREALLY_BENCH_GATE=1</code>. وتثبّت بيانات الاختبار في <code>tests/voidtools_compat.rs</code> خمسين استعلامًا حقيقيًا من Everything — بوابة انحدار القاعدة الدائمة #8؛ ويغطي <code>tests/wiring.rs</code> المنفّذ من الطرف إلى الطرف مقابل فهرس مدعوم بـ <code>tempfile</code>؛ و<code>tests/smoke/phase_05_filename_lens.rs</code> هو اختبار الدخان المستقل عن نظام التشغيل الذي يعمل في كل مُدخل من مصفوفة CI.","changelog.0af41265e3fd":"<strong>[كل المنصّات]</strong> نواة الفهرس في المرحلة 4 (<code>freally-index</code>) — واجهة مستقلة عن نظام التشغيل تستهلك التعداد المشترك <code>JournalEvent</code> وتنسّق ثلاثة مخازن دائمة: فهرس Tantivy (<code>index.tantivy/</code>) للبحث في النص الكامل + البحث متعدد الأوجه، و<code>files.db</code> المرجعي في SQLite بوضع WAL + <code>synchronous=NORMAL</code> لصف الحقيقة الدائم <code>FileRecord</code>، وفهرس أسماء مخصّص مدعوم بـ mmap (كومة سلاسل مضغوطة في <code>name.idx</code> + قوائم إحالة معكوسة للثلاثيات؛ ومصفوفة لواحق معجمية في <code>name.suf</code>) لتوليد مرشّحي السلاسل الفرعية. يُنشئ <code>Index::open(root)</code> شجرة المجلدات، ويفتح كل مخزن أو ينشئه، ويصالح الانحراف بإعادة تشغيل المخزن المرجعي في فهرس الأسماء حين تختلف أعداد الصفوف. ويمرّر <code>Index::apply(&amp;[JournalEvent])</code> أحداث Create / Modify / Delete / Rename / AttrChange عبر الحذف ثم الإضافة في Tantivy + الإدراج/التحديث في SQLite + الإدراج/التحديث/الإزالة في فهرس الأسماء، مع <code>file_id = blake3(path)[0..8]</code> كمفتاح ثابت. ويُفرغ <code>Index::commit()</code> بيانات Tantivy، ويعيد كتابة <code>name.idx</code> + <code>name.suf</code> بشكل ذري عبر ملف مؤقت ثم إعادة تسمية، وينقل سجل WAL في SQLite إلى قاعدة البيانات الرئيسية (checkpoint)، ويحفظ <code>manifest.json</code> مع <code>tantivy_generation</code> المزاد إضافةً إلى مؤشرات كل وحدة تخزين المسجّلة عبر <code>Index::record_cursor</code>. ويُظهر الطابور المحدود <code>EventQueue</code> (السعة الافتراضية 10 000 — وفق مواصفات دليل البناء) الضغط العكسي كـ <code>IndexError::QueueFull</code> بدلًا من إسقاط الأحداث بصمت؛ ويحترم <code>push_blocking</code> دلالة الإغلاق نفسها. والجذر الافتراضي للفهرس لكل نظام تشغيل (<code>%LOCALAPPDATA%\\Freally\\index</code> / <code>~/Library/Application Support/Freally/index</code> / <code>${XDG_DATA_HOME:-~/.local/share}/freally/index</code>) عبر <code>default_index_root()</code>. اعتماديات تشغيل جديدة (كلها بتراخيص متساهلة، ومسموح بها في deny.toml): <code>tantivy = &quot;0.26&quot;</code> (MIT)، و<code>rusqlite = &quot;0.37&quot;</code> مع الميزة <code>bundled</code> (MIT) — تجلب <code>libsqlite3-sys</code> + SQLite مضمّنة (ملكية عامة، ومسموح بها تحت <code>Unlicense</code>)، و<code>memmap2 = &quot;0.9&quot;</code> (MIT/Apache-2.0)، و<code>blake3 = &quot;1&quot;</code> (CC0/Apache-2.0)، و<code>parking_lot = &quot;0.12&quot;</code> (MIT/Apache-2.0). ويغطي اختبار الدخان <code>tests/smoke/phase_04_index.rs</code> تخطيط المجلدات، والذهاب والإياب الكامل للأحداث، والتعافي من SQLite بعد kill-9، وحفظ مؤشرات البيان، والضغط العكسي في الطابور، وإزالة التكرار بالحذف ثم الإضافة في Tantivy.","changelog.8167310c5eff":"<strong>[كل المنصّات]</strong> أصبحت واجهة <code>freally-journal</code> تعيد تصدير <code>JournalEvent</code> / <code>JournalError</code> / <code>JournalSubscriber</code> المرجعية من مشترك Windows عند <code>cfg(windows)</code>، ومن مشترك macOS عند <code>cfg(target_os = &quot;macos&quot;)</code>، ومن مشترك Linux عند <code>cfg(target_os = &quot;linux&quot;)</code>. وتحتفظ أهداف Unix الأخرى بالواجهة <code>portable_stub</code> محدّدة النوع لكنها فارغة التنفيذ.","changelog.f11a02c6c5f1":"<strong>[macOS + Linux]</strong> أصبح الخيار <code>--root &lt;path&gt;</code> للأمر الفرعي <code>Run</code> في <code>freally-indexd</code> (المفضَّل على macOS / Linux) يقود مشترك سجل Linux أيضًا؛ ويواصل <code>--volume</code> القائم العمل كمرادف على كل أنظمة التشغيل.","changelog.6897dd8bf8f4":"الإصلاحات (جولة مراجعة المرحلة 4)","changelog.2ed95ca28b12":"<strong>[كل المنصّات]</strong> أصبح <code>Index::apply</code> في المرحلة 4 يحوّل <code>JournalEvent::Rename</code> الذي لم يُفهرس <code>old_path</code> الخاص به قط (زوج إعادة تسمية عابر للدفعات تعذّر على مشترك السجل مزاوجته) إلى <code>Delete(old) + synthetic Create(new)</code> بدلًا من كتابة صف في Tantivy / فهرس الأسماء دون صف حقيقة مقابل في <code>files.db</code>. وهذا يحاكي عقد الحل الاحتياطي العابر للدفعات المنشور لمشتركي السجل؛ ويغطيه اختبار الدخان الجديد <code>rename_of_unknown_path_degrades_to_delete_plus_create</code>.","changelog.85d4a5272278":"<strong>[كل المنصّات]</strong> لم يعد <code>EventQueue::close</code> في المرحلة 4 يتسابق مع <code>wait_for_events</code> / <code>push_blocking</code> — إذ أصبح <code>closed</code> مخزّنًا داخل <code>Mutex</code> نفسه الخاص بالطابور بدلًا من <code>Mutex</code> شقيق، فلا يمكن لـ <code>notify_all</code> الصادر عن <code>close()</code> أن يقع بين فحص المنتظِر «هل الطابور فارغ؟» واستدعائه <code>Condvar::wait</code>. ويثبّت اختبارا الدخان الجديدان <code>close_unblocks_push_blocking_and_wait_for_events</code> و<code>try_push_after_close_refuses</code> هذا العقد.","changelog.8096900614c3":"<strong>[كل المنصّات]</strong> أصبح <code>Manifest::load_or_default</code> في المرحلة 4 يعامل خطأ تحليل JSON على أنه ملف مفقود مع تحذير بدلًا من خطأ <code>IndexError::Manifest</code> قاطع يحجب <code>Index::open</code>. فالمخزن المرجعي في SQLite و<code>meta.json</code> في Tantivy هما السجل الدائم؛ أما البيان فذاكرة مؤقتة لكل إيداع يعيد <code>Index::commit</code> كتابتها في كل دورة. ويغطي ذلك اختبار الدخان الجديد <code>torn_manifest_does_not_block_open</code>.","changelog.0f06a85ae4d4":"<strong>[كل المنصّات]</strong> أصبح <code>derive_file_id</code> في المرحلة 4 يجزّئ <code>OsStr::as_encoded_bytes()</code> مباشرةً بدلًا من <code>to_string_lossy()</code>، فلا تنهار المسارات التي لا تختلف إلا في بايتات UTF-8 غير صالحة إلى المعرّف نفسه. الأثر الفعلي نادر (أسماء الملفات في ext4 / Btrfs على Linux تسلسلات بايتات عشوائية) لكن الإصلاح يزيل فئة تصادمات صامتة قبل أن تبدأ المرحلة 5 بالاعتماد على <code>file_id</code> كتجزئة ثابتة.","changelog.4f8d098583e4":"<strong>[Windows فقط]</strong> أصبحت مزاوجة إعادة التسمية في سجل USN ضمن <code>freally-journal-win</code> من المرحلة 1 تصنّف نصف الاسم القديم من إعادة التسمية (وأي سجل <code>FILE_DELETE</code>) على أنه <strong>نهائي</strong>: يُصدَر فورًا دون اشتراط <code>USN_REASON_CLOSE</code>. لا يُصدر NTFS سجل إغلاق لجلسة الاسم القديم — فلا شيء آخر يُنتظر عند ذلك المسار. في السابق كان المصنّف يُرجع <code>Pending</code> لسجلات <code>RENAME_OLD_NAME</code> التي تفتقر إلى <code>CLOSE</code>، فيبقى جدول المزاوجة فارغًا، ويسقط سجل <code>RENAME_NEW_NAME | CLOSE</code> المطابق بصمت عبر <code>?</code>. الأثر الصافي: لم يُصدَر <code>JournalEvent::Rename</code> قط لأي إعادة تسمية داخل الشجرة. وقد أكّدت إعادة تشغيل تشخيصية على وحدة تخزين NTFS حقيقية الإصلاح؛ وأصبح اختبار التكامل <code>realtime_create_modify_rename_delete_round_trip</code> ينجح من الطرف إلى الطرف ولم يعد مُعلَّمًا بـ <code>#[ignore]</code>.","changelog.6924516bf9eb":"<strong>[Windows فقط]</strong> أصبح <code>JournalEvent::Delete</code> يرجع إلى جدول مزاوجة إعادة التسمية حسب FRN قبل اللجوء إلى نتيجة <code>build_path</code> للسجل. فإصدارات Windows الحديثة تستخدم عمليات حذف <code>NtSetInformationFile</code> بدلالة POSIX، تعيد داخليًا تسمية الملف إلى اسم مؤقت <code>$.dF{guid}</code> قبل إصدار <code>FILE_DELETE</code>؛ ودون هذا البحث كان المستهلك سيرى <code>Delete $.dF{guid}</code> بدلًا من <code>Delete &lt;original_path&gt;</code>. إجراء دفاعي: فالاختبار الذي كشف خلل إعادة التسمية رأى هنا سلوك <code>DeleteFile</code> الكلاسيكي، لكن مسار POSIX قد ينطلق في سيناريوهات الملفات المقفلة / العمليات المتعددة.","changelog.6b2e8f83dd8e":"الميزات المُهمَلة","changelog.43e7d9ac5463":"_(فارغ)_"};
